window.__D("text/maamarei-admur-haemtzai/c006",{"p":[[1900420276,"עולה תמיד למעלה כמ\"ש אש תמיד תוקד כו' ונק' עולת תמיד כו', וכמ\"ש בזוהר ע\"פ אלקים אל דמי לך<sup data-n=\"1199\">257</sup> דאלקים עצמו שהוא כח הפועל בנפעל אל דמי לך דקארי תדיר לנהורא עילאה שהוא שם הוי' ולא שכיך לעלמין כו', וכטבע האש שעולה ומסתלק וחוזר ונמשך וחוזר ועולה כו', משא\"כ בחי' אור ישר דמשפיע שהוא מלמעלה למטה הוא כמו המים שיורדים מגבוה לנמוך וזהו היפך טבע הגבו' דאו\"ח כידוע. וא\"כ מובן שכמו שב' הדיעות המה הפכיים כנ\"ל, כך בטבע מהותם המה הפכים שזה מבחי' החסדים שיורד מלמעלה למטה וזה מבחי' הגבורות שעולה למעלה וב' הפכים הן מן הקצה לקצה כאש ומים ממש (ועפ\"י הנ\"ל מובן שאינם ב' הפכים כלל ואדרבה זה עוזר לזה ושניהם כאחד ממש, שהרי אם לא האור וזיו עצם הנפש להיות נמשך בבחי' מקור לחיי בשרי דגוף אין לחיי בשרי מציאות כלל והוא בחי' החסדים דמשפיע בבחי' או\"י שמלמעלה למטה כנ\"ל, ואם אין העלי' והסתלקות דחיי בשרי בבחי' רצוא ושוב בלב העולה כו' לא הי' נמשך כל פעם מאור חיי הנפש הרוחניות להתחבר בגשמיות, ונמצאו ששניהם כא' ממש כנ\"ל ולא שהמה הפכיים כאש ומים שא\"א שיתחברו כלל, ומבואר למעלה שע\"י האמצעי הן מתחברים וכו', וזהו ענין אחד עם מה שית' בסמוך בעזר\"ה וד\"ל).\n[כט] <b>והנה</b> מעתה יש להבין דאם בחי' חתן וכלה שהם ב' מיני כבוד הנ\"ל ב' הפכים הן ממש איך יתחברו ויתייחדו ואיך יקראו בשם חתן וכלה ע\"ש היחוד וזוג דוקא מאחר שא\"א שיתחברו כאש ומים כנ\"ל. אך הנה הענין הוא דזהו מ\"ש על כל כבוד חופה, דהנה החופה היא החופפת על החתן וכלה מלמעלה על גביהם ליחד אותם יחד ולא יהיו ב' הפכים כלל אדרבה יתכללו זע\"ז והיו לאחדים ממש להוליד מאמצעות חיבורם כו', וז\"ש כי על כל כבוד כבוד דחתן וכבוד דכלה היינו על כל ב' מיני כבוד הנ\"ל שהמה ב' הפכים יש חופה עליהם המחברם יחד (ואין פשט הענין כן דעל כל כבוד וכבוד יש חופה בפ\"ע).\n<b>והענין</b> יובן בהקדים הידוע בב' מיני אהבות דבכל נפשך ובכל מאדך, דאהבה דבכל נפשך היא התפעלות אלקות של בחי' או\"פ המתיישב בלב ולבו מלא מורגש מהתפעלות זו בתשוקה ואהבה נפלאה (ולא כמו שטועים המטעים א\"ע לאמר על טוב רע שמורגש זה הוא רק למלאות התגלות לבו בחי' לגרמי' שזהו לא בהתפעלות אלקות רק בהתפעלות עצמו שרוצה להיות איזה דבר מה וא\"ל וכו', אבל כשמשיג אלקות ומתפעל בהשגה זו במוח ולב (ער דער הערט זייער כו') ע\"ז נאמר קרבת אלקים ל\"י טוב<sup data-n=\"1200\">258</sup> ל\"י דוקא במורגש ויש ולגרמי' כמו",[["1199","257","<b>אש תמיד תוקד. . עולת תמיד. . בזוהר ע\"פ אלקי' אל דמי לך</b>: צו ו, ו. פינחס כח, ו. תהלים פג, ב. ראה לעיל ח\"א ע' יט-כא. וש\"נ."],["1200","258","<b>קרבת אל' לי טוב</b>: תהלים עג, כח."]]],[1900420277,"שאוהב חיי עצמו, וזהו בכל נפש\"ך וכן כי הוא חיי\"ך וכן לב\"י ובשר\"י<sup data-n=\"1201\">259</sup> ממש ירננו כו', וזהו היפך דלגרמי' ממש כי באלקי' חפצו ולא בעצמו אדרבה משליך כל עצמו וכו' וכמ\"ש מי לי בשמים כו' וכמ\"ש בקונטרס ההתפעלות<sup data-n=\"1202\">260</sup>), אך שהתפעלות הזאת לפי אופן כלי הלב והמוח דוקא (בל\"א ווי דער מוח אונ די ה„רץ פארנעמט) היינו כפי אופן מהות נשמתו להתפעל במוחו ולבו וכמ\"ש תוכן לבות ה' ותוכן רוחות<sup data-n=\"1203\">261</sup> כו' יש שכל מתפעל כך כו' וזהו נודע בשערי\"ם בכאו\"א לפי שיעורא דילי'<sup data-n=\"1204\">262</sup> כו'. אבל בחי' אה\"ר דבכל מאדך הוא התפעלות אלקי' שבלתי מתיישב בכלי הלב כלל, וזהו מקיף דאו\"ח היינו שמצד שלא יכיל כלי הלב יהי' ההתפעלות למעלה מכלי הלב (די ה„רץ פאר נעמט ניט די התפעלות מחמת עש איז טְיף זייער ניט איבערן ה„רץ), והוא שיצא מכלי הלב ויהי' בבחי' מקיף על כלי הלב ונק' תעלומות לב, ומזה יבא צעקה פתאומית מקירת הלב בלא טעם ודעת כלל וכמו צעק לבם אל ה' כו' כשצר להם כו', וכל זה מצד שההתפעלות במוח היא ג\"כ מלמעלה מכלי המוח המשיג, דאם הי' מתפעל במוח כפי שיכיל שאת הי' כן גם בכלי הלב והיינו כאשר יתפעל במוח מסובב כ\"ע שלא יכיל במוח ההתפעלות עד שיהי' בבחי' מקיף על השכל וממילא יהי' בלב כן (ובאמת יוכל להיות שבמוח יתפעל לפי השיעור בהשגתו ובהתפעלות הלב יתגבר ההתפעלות עד שלא יוכל להכילה בלבו כלל, והוא מצד נקודת הלב שלמעלה מן הרצון שבמוח וכמ\"ש לך אמר לבי בקשו פני<sup data-n=\"1205\">263</sup> כו'[)]. וזהו מלמטה למעלה באהבה דכנ\"י שנק' חופה שחופף על הלב בבחי' מקיף דאור חוזר, וזהו חופה דכבוד התחתון שבא מצד בחי' אור חוזר שיוצא מן הכלי כנ\"ל, וכמ\"כ מאה\"ר דמלמעלה למטה מהקדב\"ה לכנ\"י כמו אה\"ר אהבתנו ג\"כ בא בבחי' מקיף מלמעלה מהכיל במוחא ולבא למעלה כו' אך שנק' מקיף דאור ישר שהוא מן האהבה דמשפיע אל המקבל, והוא כאהבת החתן אל הכלה מלמעלה מכלי מוח ולב כו' שבלתי מתיישב ג\"כ במוח ולב אך משיכותו נמשך מגבוה לנמוך אל המקבל עד שלא יכיל הכלי, וזהו בחי' חופה דכבוד עליון דמשפיע, וזה בא ע\"י התעוררות אה\"ר דבכל מאדך דכנ\"י מלמטה למעלה וכמ\"ש ואל אישך תשוקתך בתשוקה כרשפי אש שלא תוכל להתיישב בכלי וכמו צמאה לך נפשי<sup data-n=\"1206\">264</sup> כלת\"ה נפשי כו' וד\"ל.\n[ל] <b>והנה</b> ידוע דבאתדל\"ת אתדל\"ע ממש כפי אותו האופן, אם אתדל\"ת רק בבחי' התפעלו' אהבה באו\"פ מוגבל בכלי גם אתדל\"ע מלמעלה",[["1201","259","<b>בכל נפשך. . כי הוא חייך. . לבי ובשרי</b>: ואתחנן ו, ה. נצבים ל, כ. תהלים פד, ג."],["1202","260","<b>מי לי בשמי'. . בקונ' ההתפעלו'</b>: תהלים עג, כה."],["1203","261","<b>תוכן לבות ה' ותוכן רוחות</b>: משלי כא, ב. טז, ב."],["1204","262","<b>נודע בשערים בכאו\"א לפי שיעורא דילי'</b>: משלי לא, כג. זח\"א קג, ב."],["1205","263","<b>לך א' לבי בקשו פני</b>: תהלים כז, ח."],["1206","264","<b>צמא' לך נפשי</b>: תהלים סג, ב."]]],[1900420278,"למטה ג\"כ בבחי' או\"פ מוגבל בכלי וכמ\"ש כי לך החסד<sup data-n=\"1207\">265</sup> כי אתה תשלם לאיש כמעשהו דוקא וכן יהי חסדך ה' עלינו כאשר יחלנו לך, וגם באופן התפעלות דאה\"ר שבבחי' מקיף ג\"כ אתדל\"ע במקיף דאור ישר מלמעלה למטה בא לפי ערך לבד, ואע\"פ שבחי' מקיף בלתי בא בגבול ואיך יפול בו ערך ושיעור, הענין הוא דכמו שאו\"פ יש בו מדרגות חלוקות הכל לפי הכלי וכענין ב' דיעות זה שכלו מתפעל כך כו' כנ\"ל, כך בבחי' מקיף של כל א' הרי מקיף של כל א' אינו דומה לחבירו, שמה שבזה נק' מקיף על לבו ושכלו בגדול הימנו במוח ולב הוא עדיין בבחי' או\"פ המתיישב בלב, דמה שיתפעל הקטן בדעת עד שלא יכיל ההתפעלות במוחו הקטן כו' בגדול ממנו יתיישב ולא יהי' בהתפעלות יתירה מכח המוח והלב רק מהתבוננות דבר נפלא מזה כו', וכך יוכל להיות עילוי מדרגות זו למעלה מזו, וכן במלאכים ושרפים וחיות כל אחד במדרגתו יתפעל ומה שאצל זה בחי' מקיף ואו' איה מקום כבודו לגבי למעלה הימנו נק' או\"פ כו' וד\"ל. ובאתדל\"ת בבחי' מקיף פרטי של כל אחד ואחד שנק' מקיף דאו\"ח מעוררים למעלה ג\"כ בחי' מקיף דאו\"י ג\"כ לכל אחד בפרט כפי מדרגת אור מקיף שלו, וזהו הנק' חופה עליונה, וכמארז\"ל כל אחד ואחד נכוה מחופתו<sup data-n=\"1208\">266</sup> של חבירו דלע\"ל יהי' חופה לכל צדיק לפי ערך מקיף דאו\"ח שלו שלמעלה מכלי לבו ומוחו בעבודתו בתפלה ותו\"מ כו', וחופה עליונה דאור האלקי הוא שנמשך לכאו\"א בבחי' מקיף דאו\"י (והיינו צדיקים יושבים ועטרותיה\"ן בראשיהן עטרות שעשו מצד עבודתם בבחי' מקיף דאו\"ח נמשך להם עטרות מקיף דאו\"י, וכמ\"כ בשעת מ\"ת שנמשך כתר לכל א' כפי מדרגתו דוקא כמ\"ש במ\"א<sup data-n=\"1209\">267</sup>). ולפ\"ז הרי יובן בכללות נש\"י דרך כלל כמו דרך פרט לכל ניצוץ פרטי דאור אה\"ר דבכל מאד\"ך בכללות שלמעלה מהכלי שנק' מקיף דאו\"ח בכלל מעוררים אתדל\"ע מלמעלה למטה ג\"כ מקיף דאה\"ר עליונה מלמעלה למטה לכנ\"י לפי ערך ממש, כמו שבהעלאה דאו\"פ ממשיך לו מלמעלה בבחי' או\"פ לפי ערך דוקא, כך ממש בבחי' מקיף דאו\"ח ממשיך מקיף דאו\"י לפי ערך דוקא וכמ\"ש אם ישים אליו לבו כו' ורוח אייתי רוח<sup data-n=\"1210\">268</sup> כמוהו בין בבחי' או\"פ בין בבחי' מקיף הכל לפי ערך ההעלאה דוקא ולא יותר וד\"ל.\n<b>וזהו</b> כי על כל כבוד חופה (ויתורץ כפי פשט הענין כנ\"ל דעל כל כבוד וכבוד יש חופה בפ\"ע רק שזה חופה דאו\"ח וזה דאו\"י), פי' ב' מיני כבוד",[["1207","265","<b>כי לך החסד</b>: ע\"פ תהלים סב, יג."],["1208","266","<b>כל א' וא' נכוה מחופתו</b>: ב\"ב עה, א."],["1209","267","<b>צדיקי' יושבי'. . בשעת מ\"ת שנמשך כתר לכל א' כפי מדריגתו דוקא כמ\"ש במ\"א</b>: ברכות יז, א. שבת פח, א."],["1210","268","<b>אם ישים אליו לבו. . ורוח אייתי רוח</b>: איוב לד, יד. ראה זח\"ב קסב, רע\"ב [ועוד בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' רי]."]]],[1900420279,"עליון ותחתון היינו בחי' מקיף דאו\"ח דאהבת הכלה לחתן שהוא בכל מאדך נק' חופ\"ה מקיף דכבוד התחתון כו', ובחי' מקיף דאו\"י שמאהבת החתן לכלה מלמעלה למטה נק' חופה דכבוד העליון וכמ\"ש והוא כחתן יוצא מחופתו כו', וחופה דחתן נמשך לפי ערך החופה דכלה שבאה מלמטה למעלה בבחי' מקיף דאו\"ח במדה ושיעור א' ממש לא יוסיף ולא יגרע כו' (וזהו כמשל שני חצאי כדורים<sup data-n=\"1211\">269</sup> חצי כדור התחתון קצר למטה והולך ועולה ומתרחב באמצע במדה ושיעור וחצי כדור העליון קצר למעלה והולך ויורד ומתרחב באמצע ומתחברים ברוחב שבשניהם במדה א' ממש וד\"ל) (וזהו למהוי אחד באחד<sup data-n=\"1212\">270</sup> שזהו או\"י וא\"ח במדה, וכמ\"כ יש מקיף בלתי מדה כמו ופרצת ימה כו' פרזות תשב<sup data-n=\"1213\">271</sup> כו' שטח בלתי מוגבל מלמטה למעלה, וכמ\"כ מעצמות אא\"ס מלמעלה למטה מקיף דאו\"י בלתי מוגבל ומתחברין יחד כמו דמיון ב' חצאי כדורים הנ\"ל בלתי מוגבלים, וכמ\"ש במ\"א ע\"פ כי גדול יו\"ם יזרעאל וכמ\"ש במ\"א ע\"פ ביום ההוא יהי\"ה<sup data-n=\"1214\">272</sup> ב\"פ י\"ה כו' וד\"ל).\n[לא] <b>ובכל</b> הנ\"ל יובן ברייתא הידועה כיצד מרקדין<sup data-n=\"1215\">273</sup> לפני הכלה ב\"ש אומרים כלה כמות שהיא ובה\"א כלה נאה וחסודה כו'. והנה שרש ענין מחלוקת זאת היינו למעלה בחו\"כ העליונים (שהאד\"ם התחתון הרי הוא בצלם האדם העליון כידוע שהוא בחי' זו\"נ) שהם הקדב\"ה וכנ\"י ונק' קודב\"ה ושכינתי' ובזוהר נק' סובב וממלא<sup data-n=\"1216\">274</sup> בכלל ובפרט בכל עולם. וכללות הענין דמחלוקת זאת הנה היא דוקא בענין הריקוד דוקא כיצד מרקדין ולפני הכלה ולא א' לפני החתן ולהיות שב\"ש שרשן מבחי' הגבורות וב\"ה שרשן מבחי' החסדים (כידוע דכל שכל מטה כלפי חסד שרשו מבחי' החסדים ושכל מטה כלפי דין שרשו מהגבורות ולא יש רק ששה דברים שהן מקולי ב\"ש<sup data-n=\"1217\">275</sup> וחומרי ב\"ה והרוב הכל ב\"ה מטי' כלפי חסד להקל וב\"ש להחמיר כו' והוא מצד שרש נשמתם זה בקו ימין כו'), וכל אחד כפי מדרגתו בשרשו למעלה אומר דעתו בזה הריקוד לפני",[["1211","269","<b>וזהו כמשל שני חצאי כדורי'</b>: ראה לעיל ד\"ה להבין שבברכה ראשונה סוף אות לא. וש\"נ."],["1212","270","<b>למהוי אחד באחד</b>: זח\"ב קלה, א."],["1213","271","<b>ופרצת ימה. . פרזו' תשב</b>: ויצא כח, יד. זכרי' ב, ח."],["1214","272","<b>במ\"א ע\"פ כי גדול יום יזרעאל. . במ\"א ע\"פ ביום ההוא יהי'</b>: ראה ע\"פ כי גדול [ושם נזכר ג\"כ ע\"פ ביום ההוא]: סה\"מ תקס\"ה ח\"ב ע' תקצט וע' תרו. ומקבילו בס' מאמרי אדהאמ\"צ במדבר ח\"א ע' קיז. וע\"פ ביום ההוא: מאמרי אדהאמ\"צ ויקרא ח\"א ע' שנג. במדבר ח\"ב ע' תשסב ואילך."],["1215","273","<b>[לא] ובכל הנ\"ל יובן ברייתא הידועה כיצד מרקדין</b>: כתובות טז, סע\"ב ואילך. מכאן (עד הסיום) מיוסד על ד\"ה כיצד מרקדין בסה\"מ תקס\"ז ע' קפו ואילך. ומקבילו בלקו\"ת שה\"ש מח, ב. ובסה\"מ הנחות הר\"פ ע' מה [והגהות באוה\"ת סידור (חתונה) ע' רנח ואילך]. וראה גם לעיל ח\"א ע' כה. עד. רנא. רסב. שלט. לעיל סוד\"ה משמח חו\"כ. סוד\"ה להבין מה שבברכה ראשונה. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' יא [ובמ\"מ שם נסמן לספרי מאמרי אדה\"ז]. דברים ח\"א ע' מט [ע\"ד המבואר כאן]."],["1216","274","<b>ובזוהר נק' סובב וממלא</b>: זח\"ג רכה, א. ובכ\"מ."],["1217","275","<b>ששה דברי' שהן מקולי ב\"ש</b>: עדיות פ\"ה מ\"א."]]],[1900420280,"הכלה ב\"ש כמדרגתם למעלה בחי' הגבורות וב\"ה כמדרגתם למעלה בחי' החסדים וע\"כ ב\"ש אומרים כלה כמות שהיא דוקא וב\"ה אומרים כלה נאה וחסודה וכמשי\"ת ב\"ה. אך הנה תחלה יש להבין ענין גוף הריקוד לפני הכלה ואח\"כ יובן ענין המחלוקת הזאת כיצד הוא הריקוד כו'.\n<b>דהנה</b> מ\"ש לפני הכלה ולא אמרו לפני החתן דבר זה פלא ודאי דהרי עיקר השמחה לשמח החתן ואח\"כ הכלה וכמ\"ש משמח חו\"כ כו', והרי אמרו הנהנה מסעודת חתן ואינו משמחו עובר בה' קולות<sup data-n=\"1218\">276</sup> ולא הזכיר כלה. אך הענין הוא דבריקוד דוקא הוא שצריך להיות לפני הכלה דוקא ולא לפני החתן וע\"כ א' כיצד מרקדין כו' כידוע שהי' מנהגם שירקדו אנשים גדולים וחשובים לפני הכלה דוקא כדי לחבבה על בעלה וכמו רב שמואל הוה מרקד אתלת<sup data-n=\"1219\">277</sup> כו'. ולהבין זה הנה ידוע ענין כלה למעלה שהוא כנ\"י בכלל והוא בפרט בכל ניצוץ אלקי שבכאו\"א מישראל, ופי' כלה ל' כליון כמו תכלה וכלתה נפשי (וגם ל' כלי להכיל הכל וכמאמר כלה שכלולה מהכל<sup data-n=\"1220\">278</sup> כו' כל ה' ושיסוד נק' כ\"ל ומל' נק' כ\"ל ה'), וזהו בחי' אהבה טבעית ועצמית המושרשת בכל ניצוץ אלקי למס\"נ באחד מצד שחלק אלוה הוא ממש ונמשך אל שרשו כו' כמ\"ש כי רוח האדם הוא העולה<sup data-n=\"1221\">279</sup> למעלה, שזהו כמו ניצוץ הנמשך אחר השלהבת ממש שנכלל בשלהבת בעמדו בקירוב דוקא (והוא בחי' מזלא שית' שעומד למעלה בקירוב למקור חוצבו באלקות, משא\"כ בחי' נר\"נ שבמוח ולב כו' מרחוק ה' נראה להם כו' וד\"ל), וכמארז\"ל למה צדיקים דומים<sup data-n=\"1222\">280</sup> בפני השכינה כנ\"ר בפני האבוקה כו'. אך א\"כ הי' כל איש מישראל נמשך רוחו ולבו תמיד למעלה ולא למטה כלל מאחר שנשמתו נמשך תמיד מצד טבעה העצמי' (שישנה גם בכל הפחו' שבישראל וקל שבקלים, וראי' ממה שאנו רואים שיוכל גם הקל שבקלים לבא למס\"נ על קדה\"ש אע\"פ שעובר כל עבירות כו' כשיאמרו לו לכפור באחד ימסור עצמו להריגה, או מה שאנו רואים בבע\"ת שפתאום יתפעל מנקודת לבבו ויתמרמר בנפשו עד כלותה ממש, כתשובה דראב\"ד עד שיצאה נשמתו בבכי' וכה\"ג היו רבים כנתן דצוציתא<sup data-n=\"1223\">281</sup> כו', אין כל זה רק ראי' ואות אמת על בחי' אה\"ר הטבעית העצמית המושרשת בכל ניצוץ אלקי כנ\"ל ואע\"פ שחטא הרבה מאד מ\"מ ישרא\"ל הוא מצד שרש נשמתו למעלה כמשי\"ת). אך הענין",[["1218","276","<b>הנהנה מסעודת חתן. . בה' קולות</b>: ברכות ו, ב."],["1219","277","<b>רב שמואל הוה מרקד אתלת</b>: כתובות יז, א."],["1220","278","<b>כלה שכלולה מהכל</b>: ראה גם לעיל ד\"ה אשר ברא (הראשון) סוף אות ח. ס' שער היחוד לאדהאמ\"צ ריש פמ\"ח."],["1221","279","<b>כי רוח האדם הוא העולה</b>: ע\"פ קהלת ג, כא."],["1222","280","<b>למה צדיקי' דומי'</b>: פסחים ח, א."],["1223","281","<b>כתשובה דראב\"ד. . כנתן דצוציתא</b>: ע\"ז יז, א. שבת נו, ב ורש\"י סנהדרין לו, ב [וז\"ל רש\"י: ומצאתי בספרי הגדה שהי' מר עוקבא בע\"ת שנתן עיניו כו' וכבש יצרו כו' וכשהי' יוצא לשוק הי' נר דלוק בראשו מן השמים וע\"ש כך קרי לי' נתן צוציתא כו']. ובסדר הדורות מע' נתן דצוציתא."]]],[1900420281,"הוא דאע\"פ ששרש נשמתו בתשוקה ודביקות נפלאה לימשך למקור חוצבה בתמידות כמו שא' כי רוח האדם העולה<sup data-n=\"1224\">282</sup> העולה תמיד כנ\"ל, אבל הרי זה בבחי' ההעלם ומקיף על האדם ולא בבחי' גילוי כלל וכלל, שאם הי' זה בא בבחי' גילוי במוח ולב כו' שנק' נר\"נ שבאדם באמת הי' דבוק תמיד למעלה ולא למטה כלל (וכמ\"ש והיית רק למעלה<sup data-n=\"1225\">283</sup> ולא תהי' למטה שהוא בעה\"ח שלמעלה מעה\"ד), אבל באמת אין בחי' זו דרוח האדם העולה כנר בפני האבוקה ונק' נר הוי' רק בהעלם ומקיף שזהו הנק' צל\"ם ומזלא, כמ\"ש אך בצל\"ם<sup data-n=\"1226\">284</sup> יתהלך איש, איש זהו מוחא ולבא אוי\"ר שכליי' כו' וצל\"ם דאיש הוא בחי' המקיף שנק' מזלא כמו שידוע בענין מזלייהו חזו<sup data-n=\"1227\">285</sup> כו' (ובחי' צלם ומזלא זה הוא לא בא לכלל טומאה מעון הנעשה ע\"י הגוף וע\"ז א' כולך יפה רעייתי ומום אין בך, ואע\"פ שלכאורה סותר לפסוק דמכף רגל<sup data-n=\"1228\">286</sup> עד ראש אין בו מתום כו', יכול להיות דגם שבנר\"נ דאדם בפרט ובכלל בכללות נש\"י מכף רגל עד כו' מ\"מ כולך יפה רעייתי מום אין בך כלל והוא מצד בחי' מזלא וצלם דאדם שדבוק תמיד למעלה ואין שם בחי' מום כלל וכמשי\"ת) (ובזה יובן מארז\"ל דאכל עשרה שכינתא שריא<sup data-n=\"1229\">287</sup> ולכאורה איך אפשר זה בעשרה רשעים גמורים שעברו על עבירות חמורות כו', אך מפני שאע\"פ שחטא ופגם בכל נר\"נ שבכל קומת אדם מכף רגל עד ראש כו' מ\"מ ישראל הוא בבחי' המזלא שבו שכולך יפה כו' וד\"ל). והנה אם הי' בחי' מזלא דכאו\"א בא לגילוי כמו שבא לפרקים כמו למס\"נ על קדה\"ש וכבע\"ת לפרקים לא הי' אדם בא לידי חטא לעולם (וכמ\"ש בכתבי האריז\"ל שאם הי' גילוי מזלי' דאדם זהו כמו גילוי ורוה\"ק ממש<sup data-n=\"1230\">288</sup> כו', וזהו מאן דקטיל לחויא יהבין לי' ברתא דמלכא כמ\"ש במ\"א<sup data-n=\"1231\">289</sup>), אבל הוא בהעלם גדול וצריך שיבא לידי גילוי מלמעלה בכאו\"א לפי ערכו. וזהו ענין הב\"ק שמכרזת<sup data-n=\"1232\">290</sup> בכל יום שובו בנים שובבים שב\"ק זה נמשך מבחי' י\"ג מדה\"ר העליונים שבמל' דאצי' שחפץ חסד הוא וחשב מחשבות<sup data-n=\"1233\">291</sup> לבלתי ידח ממנו נדח שהן נשמות שבגופים חומריים ביותר הפוגמים אורה כו' ע\"כ יעורר עליהם רוח ממרום הוא כרוז הב\"ק שיעורר לבחי' מזלי' של כאו\"א מישראל שבכחו לפעול",[["1224","282","<b>העולה העולה</b>: כ\"ה בגוכי\"ק."],["1225","283","<b>והיית רק למעלה</b>: תבוא כח, יג."],["1226","284","<b>אך בצלם</b>: תהלים לט, ז."],["1227","285","<b>מזלייהו חזו</b>: מגילה ג, א."],["1228","286","<b>כולך יפה רעייתי. . דמכף רגל</b>: שה\"ש ד, ז. ישעי' א, ו."],["1229","287","<b>דאכל עשרה שכינתא שריא</b>: סנהד' לט, א."],["1230","288","<b>בכהאריז\"ל שאם הי' גילוי מזלי'. . גילוי </b>[אוצ\"ל: גילוי אליהו]<b> ורוה\"ק ממש</b>: ראה שערי קדושה להרח\"ו ח\"ג ש\"ה, וש\"ז (ד\"ה הנה). ובהנסמן עוד במ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תצא."],["1231","289","<b>מאן דקטיל לחויא. . כמ\"ש במ\"א</b>: ראה תקוני זהר סוף תי\"ג. ס' מאמרי אדהאמ\"צ דברים שם ע' תפב [ובהמ\"מ], וע' תצ."],["1232","290","<b>הב\"ק שמכרזת</b>: ע\"פ ירמי' ג, יד. כב. ראה זח\"ג קכו, א. ובהנסמן עוד לעיל ח\"א ע' קנב."],["1233","291","<b>וחשב מחשבות</b>: שמואל-ב יד, יד."]]],[1900420282,"התעוררות רב במוח ולב כו' וזהו עד יערה עלינ\"ו רוח ממרום כו', והן הן הרהורי תשובה הנופלים פתאום בכל איש מישראל כפי מדרגתו שישוב אל ה' וירחמהו כו', וכמ\"כ השיבנו ה' אליך השיבנו זה הוא ע\"י הב\"ק הזה כו' כמבואר במ\"א<sup data-n=\"1234\">292</sup> וד\"ל.\n<b>וזהו</b> פי' כל\"ה ל' כליון כמו כלת\"ה נפשי שהוא בחי' אהבה המסותרת בתעלומת נקודת הלב שבכנ\"י בכלל ובפרט שהוא בחי' מזלא שעולה תמיד למעלה (וע\"ז נא' כולך יפ\"ה כו' כנ\"ל) שראוי ליחוד עליון שישכון בה בחי' אור העצמות דא\"ס ב\"ה שנק' חת\"ן העליון, וכידוע שזהו יחוד קודב\"ה ושכינתי' שהוא יחוד הוי' ואלקים שהוא יחוד סובב וממלא בכלל ובפרט כנ\"ל (וגם פי' כלה היפך הכליו\"ן וצמאון שכלת\"ה נפשי ליכלל כו' אלא ל' כלי להכיל ולקבל האור ושפע בתוכה, והוא אחר היחוד כו' ואז נק' כל\"ה שהיא כלולה מהכל מכל אורות עליונים שבמשפיע וכנ\"ל דיסוד נק' כל והמל' נק' כ\"ל ה\"א כו', רק קודם היחוד נק' כל\"ה ע\"ש הכליון כלת\"ה נפשי כו' והעיקר מפני שהוא בהעלם עדיין כנ\"ל וצריך להביאה לגילוי ואז נק' כלה ל' כלי וכוללת הכל בגילוי כו' וד\"ל).\n[לב] <b>ומעתה</b> יובן ענין הריקוד לפני הכלה הנ\"ל. דהנה מבואר למעלה דבחי' התקשרות אהבה הטבעית ועצמית שבכנ\"י הוא בהעלם וצריך להביאה לגילוי, וזהו ענין הריקוד לפני הכלה שע\"י הריקוד כנגדה ממשיכים להתעורר בה בחי' נקודת התקשרות שבה מן ההעלם לגילוי ואז תהי' בחי' בית קיבול להתייחד בבעלה, כי ע\"י שמחה ותענוג שלה שממשיכים לה ע\"י הריקוד לפניה מתרוממת בעצמה ונתעורר בה בחי' הסתום שבה לבא לגילוי להיות תשוקתה ליחוד (והוא בחי' הנ\"ל שביסוד דנוק' שמתעורר' לבא מן ההעלם לגילוי לגבי בעלה, וכידוע בענין גן נעול מעיין חתום חותם בתוך חותם דהיינו בחי' התקשרות עצמי' דמס\"נ ותשובה מעומקא דלבא הנ\"ל סתום ונעלם בכנ\"י בהעל\"ם אחר העל\"ם וכמ\"ש ויריחו סוגר\"ת ומסוגר\"ת<sup data-n=\"1235\">293</sup> חותם בתוך חותם כו', וע\"י הריקוד אנשים גדולים ששרשן באור אבא כו' מעוררים בה שמחה ועונג העליון שתתן תת כחה בהעלאת מ\"ן לבעלה תמיד וד\"ל). וכך הוא בניצוץ האלקי בפרט שנק' כלה ע\"י בחי' הריקוד שמרקדין לפניה עי\"ז יאיר בה מה שבהעלם לגילוי והוא אור אה\"ר הנ\"ל (וענין הריקוד הוא בחי' דילוג כמו קול דודי כו' מדלג על ההרים, והוא בחי' אורות עליונים מקיפים שמעולם העליון שבאין לעזור לניצוץ האלקי וכמ\"ש ה' לי בעוזרי, והיינו הבא לטהר<sup data-n=\"1236\">294</sup> מסייעי' אותו שיש הרבה מסייעי\"ן לכל ניצוץ כשבא לטהר לבו למעלה כו').",[["1234","292","<b>השיבנו ה' אליך. . כמבוא' במ\"א</b>: איכה ה, כא. וראה ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תלו. תקז. לעיל ח\"א ע' קנב."],["1235","293","<b>גן נעול. . ויריחו סוגרת ומסוגרת</b>: ע\"פ שה\"ש ד, יד. יהושע ו, א."],["1236","294","<b>קול דודי. . ה' לי בעוזרי. . הבא לטהר</b>: שה\"ש ב, ח. תהלים קיח, ז. שבת קד, א."]]],[1900420283,"<b>והנה</b> יש ב' דרכים בענין הריקוד והמה ב' הפכי' איך להוציא אור אה\"ר הנ\"ל לגילוי בכנ\"י בכלל ובכל ניצוץ בפרט כנ\"ל, והוא ענין מחלוקת דב\"ש וב\"ה כנ\"ל. ולהבין עיקר ושרש מחלוקתם מהיפוך להיפוך כזה שזה אומר כלה כמות שהיא כו', הנה יש להקדים ענין המבואר במ\"א ע\"פ ושמתי כדכ\"ד שמשותיך פליגי תרי מלאכי<sup data-n=\"1237\">295</sup> כו' ח\"א שוהם וח\"א ישפה ואמר הקדב\"ה להוי כדין וכדין כו'. והענין ידוע דאור זרוע לצדיק היא הנשמה כלולה מב' מדרגות, א' כמו שהיא למעלה ונק' נר ה' נהורא חוורא אור המאיר בעצם, והב' כמו שהיא למטה בגוף מלא פגמים מחומריות הגוף, וזה נק' קדוש בעצם וזה נק' טהור, וההפרש בין קדוש לטהור ידוע שהקדושה היא מבטן מתחלת ההויה וטהור מכלל טומאה קאתי כמו מי יתן טהור מטמא כו' וכמו טהר יומא טהרו של מזבח<sup data-n=\"1238\">296</sup> וכה\"ג, וידוע דטהרה מביאה לידי קדושה<sup data-n=\"1239\">297</sup> שזהו הזדככות אור הנשמה בגוף מן הטומאה ועכרורית התאו' החומרי' אז נק' נשמה זו טהור\"ה ומביאה לידי קדוש\"ה שהיא אור הנשמה שנק' קדוש בעצם כנ\"ל (שזהו בחי' המזלא וצלם שדבוק למעלה תמיד). וזהו כדכ\"ד שהן ב' מיני אבנים שוהם בהיר בתחלת הוייתו והוא אור זרוע לצדיק עליון בחי' יוסף וישפה אבן טוב הנעשה בהיר (גישלייפט בל\"א והוא בורלאנט וכה\"ג שמתנוצץ בעין) (וכן יש ב' מיני כוכבים א' אורו בהיר בלתי מתנוצץ כלל והב' אורו מתנוצץ אנה ואנה, וזהו מנהרי\"ן ומנצצין שהוא בחי' אור ישר ואור חוזר כמ\"ש במ\"א<sup data-n=\"1240\">298</sup>), והוא בחי' בנימי\"ן צ\"ת שהוא הזדככות חומר הגוף שתאיר הנשמה בבחי' אור מתנוצץ כו', וזהו ועמך כולם צדיקים ב' צדיק עליון וצדיק תחתון וזהו ורב שלום בנייך<sup data-n=\"1241\">299</sup> שלום עליון מלמעלה למטה בחי' צדיק עליון ושלום שלמטה התקשרות המקבל מלמטה כו'.\n[לג] <b>והנה</b> יש עוד להקדים ענין א' (הנז' בס' שער הקדושה להרח\"ו ז\"ל<sup data-n=\"1242\">300</sup>) והוא אשר יש ב' דיעות חלוקות בדרכי ה' האמיתי' על היות האדם רחוק ושפל ערכו מאד מפני גסות חומרו בכל מיני תאוה חומריו' ואיך יבא",[["1237","295","<b>במ\"א ע\"פ ושמתי כדכד. . פליגי תרי מלאכי</b>: ישעי' נד, יב. ב\"ב עה, א. ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תכ ואילך."],["1238","296","<b>מי יתן טהור מטמא. . טהור יומא. . טהרו של מזבח</b>: איוב יד, ד. ברכות ב, א. יומא נח, ב."],["1239","297","<b>דטהרה מביאה לידי קדושה</b>: ע\"ז כ, ב."],["1240","298","<b>מנהרין ומנצצין שהוא בחי' או\"י ואו\"ח כמ\"ש במ\"א</b>: ראה זח\"ב קלו, ב: השמים מספרים כו' דנהרין ונציצין בנציציו דנהורא עלאה כו'. ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תע. ס' פירוש המלות לכ\"ק אדהאמ\"צ פט\"ז."],["1241","299","<b>ועמך כולם צדיקי'. . ורב שלום בנייך</b>: ישעי' ס, כא. שם נד, יג."],["1242","300","<b>הנז' בס' שער הקדושה להרח\"ו ז\"ל</b>: ראה שע\"ק ח\"ג ש\"ג. [שם כאופן הא' המובא כאן. ועיג\"כ תניא פי\"ז]. והובא גם בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' יא: ”וכמ\"ש בשעה\"ק להרח\"ו שא\"א שתבוא ותעלה הנשמה אלקית להשגות פנימיות ורזין דאורייתא בסוד ה' כו' אם לא שתטהר הנפש הטבעית בבירור וביעור לגמרי מכל המדות רעות כו'\". ע\"ש בארוכה."]]],[1900420284,"בברית והתקשרות אמיתי' להקריב לבו לה' בדביקות אמיתית וכמ\"ש ובו תדבקון<sup data-n=\"1243\">301</sup> ממש כו'. והנה יש או' דודאי א\"א שיבא אדם החומרי לבחי' השלימות בדביקות במוח ההשגה בגדולת ה' ובלבו להתפעל כו' כ\"א אחרי [ש]יטהר א\"ע מכל פסולת וטומאה בנקיון גמור בלב ובמעשה וגם בהרהור ובסיגופים לגוף עד שיזדכך חומרו מעט מעט אז יוכל לגשת אל הקדש לידבק באלקים במוח ההשגה ולא בסתרי המרכבה דוקא אלא בהשתלשלות דאבי\"ע ביח\"ע ויח\"ת כידוע, אבל כל זמן שלא נטהר גופו ונזדכך לגמרי איך יקרב במום ופגם אל הקדש העליון, וכמ\"ש מי יעלה בהר ה'<sup data-n=\"1244\">302</sup> ומי יקום במקום קדשו נקי כפים ובר לבב, נקי כפים היינו במעשה בסור מרע בתכלית ובר לבב בתכלית מכל רצון זר בלבו אפי' בהרהור כ\"ש<sup data-n=\"1245\">303</sup> חוצץ ולא יוכל לעלות עוד כו'. ולפ\"ז הדעת לא שבק חיי לכל ברי' דמי הוא אשר יכול לזכך גופו כ\"כ עד שיוכל לעלות ולידבק באלקים חיים כו', ואמנם הדיעה הב' להיפך, דודאי מי שהוא בחושך ולא ראה אור אלקי מעולם במה יזכך א\"ע ואיך יטהר לבו ומחשבתו ומדותיו החומריי' אם הוא אחוז וקשור באשר הוא שם (ומה שנופל לו הרהורי תשובה זה אינו שלו כלל כו'), אלא עצה היעוצה בדרך אחר, שיאמר ללבו הגם שאינו ראוי לעלות בצד גופו שלא נזדכך ונשבר בתענית ולא במעשה הטוב כראוי כנ\"ל מ\"מ יוכל להיות שינקה מכל רע ע\"י שיאיר את נפשו באור האלקי בהשגה שבמוח ולב לתכלית העומק גם ביתר מכפי מדתו ושיעורא דילי' ואז האור דוחה את החושך וגם מעט מן האור דוחה הרבה מן החושך וכמ\"ש גם חושך לא יחשיך ממך<sup data-n=\"1246\">304</sup> כו', וכנראה בחוש שבהאיר אור אלקי בתוך המוח ולב מעט מיד יפול כל זוהמא וחומריות הגוף באותה שעה עד אשר יסיח דעתו ולבו לגמרי בהבלי העולם, אבל כל עוד שאור ה' נגה<sup data-n=\"1247\">305</sup> במוחו ולבו בהתפעלות אלקות בהשגות עמוקות לא יראה רע כי ה' עמו וכהמס דונג<sup data-n=\"1248\">306</sup> כו' כי לא יוכל הרע לעמוד במקום הקדושה כלל וכלל ואפי' תאות היתר כו' (רק זוג מצוה בליל ש\"ק וסעודות השבת לתיאבון שאינו מזיק כלל מצד קדושת השבת כו'). וזהו כמשל ב' בני אדם<sup data-n=\"1249\">307</sup> אחד עומד למעלה והב' עומד למטה יש ב' דרכים שיתחברו, או שיעלה התחתון למעלה והוא הזדככות החומר תחלה שהוא דיעה",[["1243","301","<b>ובו תדבקון</b>: דברים יג, ה."],["1244","302","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["1245","303","<b>כ\"ש</b>: כל שהוא."],["1246","304","<b>גם חושך לא יחשיך ממך</b>: תהלים קלט, יב."],["1247","305","<b>נגה</b>: כן הוא בגוכי\"ק."],["1248","306","<b>וכהמס דונג</b>: תהלים סח, ג."],["1249","307","<b>כמשל ב' בנ\"א. . ב' דרכים שיתחברו או שיעלה התחתון כו'</b>: ראה סה\"מ תקס\"ג ע' תרסז [ולדרוש זה מציין באוה\"ת מקץ שמז, ב]. לקו\"ת ראה כו, א. כז, ד. ר\"ה נה, ג. ס' מאמרי אדהאמ\"צ: בראשית ע' קה. במדבר ח\"ה ע' א'תרס. דברים ח\"א ע' רנה. ח\"ב ע' תמד. נ\"ך ע' תנ. ובשער הפסוקים להאריז\"ל משלי ס\"ט ז\"ל: הנה שני מינים של השפעה הם הא' הוא כאשר העליון משפיע אל התחתון הב' הוא כאשר התחתון עולה עד העליון לקבל כו'."]]],[1900420285,"הא', והב' שירד העליון לגבי התחתון ויזדכך ממילא כדיעה הב' הנ\"ל. וזהו ענין ב' אבנים דשהם וישפה הנ\"ל צ\"ע וצ\"ת כנ\"ל שהוא טהרה וקדושה, ואמר הקדב\"ה להוי כדין וכדין שצריך שיהיו ב' הדרכים וב' דיעות הנ\"ל, וזהו כ\"דכ\"ד כ\"ד אותיות דבשכמל\"ו<sup data-n=\"1250\">308</sup> דק\"ש שחרית וערבית מדת יום ומדת לילה שהן ב' דיעות הנ\"ל ובהתחברם יחד נק' כדכד שהיא זכוכית בהירה בהזדככות כ\"כ כאילו היא בהוייתה ממש וד\"ל.\n[לד] <b>ואחר</b> הקדמה הנ\"ל יובן שזהו ג\"כ ענין מחלוקת ב\"ש וב\"ה בריקוד לפני הכלה שהוא באיזה אופן תעלה הנשמה שבגוף שנק' כל\"ה שיתעורר בכל אדם מישראל אה\"ר הנ\"ל לצאת מחושך חומר הגוף ולידבק במקור חוצבה באור פני מלך שזהו בחי' היחוד דכנ\"י בבעלה. והנה ב' דיעות הנ\"ל דיעה שמלמטה למעלה בהזדככות המדות גופניות תחלה שזהו הנק' טהרה שמביאה לידי קדושה שבעצם כנ\"ל זהו דעת ב\"ש שאו' כלה כמות שהיא דוקא, בהיות כי דיעה זו לעלות מלמטה למעלה ע\"י הזדככות כו' היינו בבחי' הגבורות והדינין שהוא בהכרח שירגיש<sup data-n=\"1251\">309</sup>* על יצה\"ר שבו ויתמרמר עליו ולא יקל לעצמו כלל וכלל אדרבה מאד יחמיר וידקדק בעצמו למצוא כל חסרון ופגם בתכלית הדקדוק עד כחוט השערה, כמו גם בהרהור בעלמא ובהיתר כו' ידמה עליו כהר וקשה עליו, לחשוב עצמו כחוטא גמור, והוא לעורר בחי' הדין על עצמו איך שחוטא גדול הוא כו', וגם במעשה הטוב ישקול במאזני שכלו תוך ופנימי' כל מעשיו גם הטובים איך שאינם לש\"ש ולא לתכלית האמת, וכה\"ג ימצא רק חוב בנפשו ויהי' שפל בעיניו נבזה ונמאס ממש כו' כשמוצא בעצמו כל מיני מומין חסרון ופגם מכף רגל עד ראש אין בו מתום כולו פגום כו' בין בסור מרע בין בועשה טוב ומכ\"ש באוי\"ר שבלב ומוח כו' שחסר נפשו מכל אור כו' ובחשך ילך כל ימי חיי הבלו וכה\"ג, והרי לפ\"ז לא יערב לבבו לגשת אל הקדש פנימה כי נבזה בעיניו נמאס ואינו בא במדרגה לעבוד עבודת ה' בבחי' השגה שבמוחא ולבא ביח\"ע ויח\"ת וכה\"ג שכל איש אשר בו מום לא יקרב לעלות למעלה כו' ביתר מכפי מדתו וערכו לבד, והוא הנק' בית שמאי פי' שמאי מל' שומא ששמין א\"ע ומפלס דרכו ששוקל כל דרכיו ומעשיו היטב הדק ואינו מטעה א\"ע כלל וכלל כי ה' בוחן לבבות ודובר שקרים לא יכון לפניו ואיך יבא לפניו בעבודה שבמוח ולב להתבונן כו' ולעבוד ה' בשמחה, אך הכל לפי החשבון והדקדוק היטב שיודע ומשער בנפשו וערכו אחר אשר הוטהר מעט לבבו מכל תאוה זרה ומדות מגונות ויש בו תשובה שלימה כו' יכול לעמוד בנפשו לגשת אל הקדש לעבודה תמה בשמחה וטוב לבב כו' אך ורק לפי ערך שישער בנפשו לפי מעשיו כו' שראוי לעבודה זו ולא יותר מכדי",[["1250","308","<b>כדכ\"ד כ\"ד אותיו' דבשכמל\"ו</b>: תקוני זהר בהקדמה (יד, א). וראה ס' מאמרי אדהאמ\"צ דברים שם ע' תמו, ובהמ\"מ שם."],["1251","309","<b>שירגיש</b>: כ\"ה בגוכי\"ק."]]],[1900420286,"מדתו אפי' כקש\"י ממש, וזהו ל' שומא ששם א\"ע ושוקל כל דרכיו לפי ערך הזדככות שלו כך יעלה ולא יותר. וזהו כמארז\"ל ע\"פ ושם דרך אראנו בישע אלקים כל השם אורחותיו<sup data-n=\"1252\">310</sup> זוכה ורואה בישועתו של הדקב\"ה, פי' השם ששם ושוקל דרכיו ואורחותיו במדה ברורה איך הוא ומה הוא בכל כלי גופו אם מזוככים מכל סיג ופסולת לפי ערך מה שהוא מוצא בנפשו יעלה ולא יגבה לבבו לעלות למעלה ביתר מכפי שומא שלו בערכו כו', הוא הזוכה ורואה בישועתו כו' שה' בוחן לבבות, וכמ\"ש דוד לשלמה וכל לבבות דורש ה' כי תדרשנו ימצא לך<sup data-n=\"1253\">311</sup> כו' פי' לפי אופן הבקשה והדרישה בלב נכון וטהור כך ימצא לך, וכמ\"ש מי יעלה כו' נקי כפים ובר לבב שזהו השם אורחותיו ומוצא לבבו בר וטהור בלי שום סיג ותערובת רע ושקר שלא ימצא בלבו שום רצון זר הפונה לחוץ וכמאמר לב אחד לאביו שבשמים<sup data-n=\"1254\">312</sup> כו' ואם אין לבו כך לא יטעה א\"ע וירחק נפשו מדבר שקר וכו' וד\"ל (ואז זוכה ורואה בישועתו כו' היינו כנ\"ל בענין טהרה וקדושה שהבא לטהר מסייעין אותו וכמו שאנו אומרים וטהר לבבינו לעבדך באמת, פי' הבא לטהר לבו מכל סיג ופסולת בחשבון ודקדוק היטב הדק בכל דרכיו בסתר ובגלוי ויתמרמר בנפשו וירגיז על יצה\"ר והוא הנק' תשובה תתאה כידוע, אז ימצאו לו הרבה מסייעין ועוזרין לו מלמעלה שיעזרוהו ויושיעוהו בעזר ה' עליו להנצל מכל רע, וכמאמר יצרו של אדם מתגבר עליו בכל יום<sup data-n=\"1255\">313</sup> ואלמלא הקדב\"ה עוזרו לא יכול לו כו', ועזר זה נמצא לכל איש דורש לבו ליטהר מכל רע ומפשפש במעשיו מאד להחמיר ולא להקל כלל הוא הזוכה לראות בישועת אלקים שהוא להמשיך לו מסייעין הרבה, ועיקר המסייע ועוזר הוא הקדושה האלקית שזהו שא' טהרה מביאה לידי קדושה<sup data-n=\"1256\">314</sup> שמבחי' הטהרה שמלמטה למעלה יומשך בחי' הקדושה העליונה שמלמעלה למטה וד\"ל. וזהו ג\"כ כל עיקר ענין תשובה עילאה שנמשך אחר תשובה תתאה דוקא, וכמ\"ש במ\"א ע\"פ ישוב ירחמינו יכבוש כו' שזהו הנק' תש\"ע ואינו בא כ\"א אחרי תש\"ת דוקא, והיינו במי ששם אורחותיו לדקדק בכל דרכיו לשוב אל ה' מכל אשר ימצא פגם וחסרון בנפשו כו', אז זוכה לבחי' תש\"ע שהוא מלמעלה למטה כמ\"ש ישוב ירחמינו כו' וא' בזוהר מאן אתר<sup data-n=\"1257\">315</sup> מההוא ע\"י כו' שהקדב\"ה שב אלינו מלמעלה למטה לעזור ולהושיע, והוא בחי' הקדושה אלקי' שנמשך על השב בתש\"ת בלב נשבר ומטהר לבבו באמת שזהו טהרה מביאה כו' וד\"ל).",[["1252","310","<b>ושם דרך אראנו. . כל השם אורחותיו</b>: תהלים נ, כג. סוטה ה, ב."],["1253","311","<b>וכל לבבות. . כי תדרשנו ימצא לך</b>: ע\"פ דברי הימים-א כח, ט."],["1254","312","<b>לב אחד לאביו שבשמים</b>: סוכה מה, ב. ועוד."],["1255","313","<b>יצרו של אדם מתגבר עליו בכל יום</b>: סוכה נב, א."],["1256","314","<b>טהרה מביאה לידי קדושה</b>: ע\"ז כ, ב."],["1257","315","<b>במ\"א ע\"פ ישוב ירחמינו. . בזוהר מאן אתר</b>: מיכה ז, יט. ראה זח\"ג טז, א. דרך חיים כא, ב. תו\"ח שמות שלה, א. ס' מאמרי אדהאמ\"צ בראשית ע' קה. דברים ח\"ב ע' תקכד. תקכז. תרנז. ח\"ג ע' תשמז. ח\"ד ע' א'תכא."]]],[1900420287,"<b>וזהו</b> בש\"א כלה כמו שהיא, פי' בענין הריקוד לפני הכלה להוציא כל תעלומות לב שבה כנ\"ל, בית שמאי שהן מבחי' הגבורות ודינין ששמין דרכם כנ\"ל אומרים שאופן הריקוד צריך להיות שיאמרו כלה כמות שהיא, וכפשט הענין שלא יוסיפו ולא יגרעו בשבחה וחסרונה רק כמות שהיא דוקא, ולכאורה זהו פלא דהלא בריקוד לפני הכלה א\"א לספר בגנותה כלל רק בשבחה ואיך יאמר כלה כמו שהיא ואם היא חיגרת יאמר בגילוי לגנותה א\"כ ריקוד זה למה, ואם הכונה שלא להוסיף בשבחה רק כמות שהיא גם זה לא יתכן כונת הריקוד והשמחה לפניה כו' כי אם ידקדק בחשבון שלה בכל מעשה הטוב והרע כנ\"ל א\"כ יהפך משמחה ליגון ואין כאן ענין ריקוד כלל. אך הענין הוא דר\"ל באופן העצה איך שיוציאו מן ההעלם לגילוי בחי' נקודת התקשרות שבכל ניצוץ אלקי שבכאו\"א מישראל שנק' כלה כנ\"ל, דהיינו דוקא ע\"י ששם אורחותיו כפי ערך טהרת לבו ולא יותר זהו כלה כמות שהיא דוקא שעי\"ז זוכה ורואה בישועת ועזר אלקי' שיהי' ראוי לבחי' גילוי אור המשכות אלקות בנפשו בתו\"מ ובתש\"ע כנ\"ל שהוא גילוי אה\"ר העצמי' שבה כנ\"ל, ודוקא לפי ערך אם מעט אם רב בבחי' הבירור בנפשו לאכפייא לסט\"א בסור מרע ועשה טוב כנ\"ל כך יומשך לו עזר האלקי מלמעלה שהוא בחי' הקדושה האלקי' שיהי' ראוי ליחוד עליון דקודב\"ה ושכינתי' כו' ולא יוסיף ולא יגרע משום דב\"ש מבחי' הגבו' דאו\"ח שעולה כו' וכמ\"ש אם ישים אליו לבו כו' רוח אייתי רוח<sup data-n=\"1258\">316</sup> ואמשיך רק לפי ערך ההעלאה בלבד ולא יותר, וזהו הריקוד לפני הכלה להמשיך לה מלמעלה רק לפי ערך מעשיה כמות שהיא לבד ולא יותר כנ\"ל וד\"ל (וא\"כ אם היא חגרת וסומא כמו שפגם בעין הרואה ראי' אלקי' ובהילוך כו' כל אשר בו מום כו' לא יומשך לתקן הפגם כלל רק שלא יגלה קלונה אמנם לא יהי' הריקוד להוסיף אור במקום הפגם רק במקום התיקון שניתקן דרכו כבר להוסיף אור למעלה והכל במדה ומשקל, ולפ\"ז עדיין לא מתיישב כונת הריקוד לפ\"ד ב\"ש כנ\"ל שא\"כ אין השמחה שלימה וריקוד זה בדין ומשפט לפי המדה לבד לא יתכן כנ\"ל).\n[לה] <b>ומעתה</b> יש להבין ענין דעת ב\"ה שאומרים כלה נאה וחסודה ולא כמות שהיא דוקא אלא אדרבה גם אם היא חיגרת או סומא אעפ\"כ כלה נאה וחסודה כו', וזהו כמו דיעה הב' דלעיל שחולק על דיעה הא' דודאי מי שהוא בחושך ולא ראה אור כו' איך יזכך א\"ע כו' אלא העצה שיאיר אור האלקי בנפשו מלמעלה למטה עד שהאור ידחה החושך כו', וזהו להיפך ממש מדעת דב\"ש לדקדק ע\"ע כו' אלא אדרבה הגם שמוצא א\"ע בכל הפחיתות כנ\"ל בכל דרכיו ומעשיו לא ימנע לגשת אל העבודה האלקי' בהשגות אלקות וגילוי המשכות אור אלקי עד אשר יזדכך גופו ויצדק בכל דרכיו תחלה, כי אם ימתין ע\"ז לעולם לא יראה אור האלקי ולא יוכל לבא לפני ה' בעבודה שבמוחו ולבו",[["1258","316","<b>אם ישים אליו לבו. . רוח אייתי רוח</b>: איוב לד, יד. ראה זח\"ב קסב, רע\"ב."]]],[1900420288,"כו', אלא אדרבה יתחיל מלמעלה למטה והוא שיתבונן בגדולת הבורא בפרטו' ויעמיק דעתו ולבו לה' להאיר נפשו בבחי' גילוי אלקות ממש עד שיקבע האור הזה במוחו ולבו בתוך ופנימיות נפשו ולבו ואז ממילא יפול כל רע שבלב במדות וחומריות גופו עד שיזדכך מעט מעט בהרגל עבודתו זו יום ולילה בג' תפלות ובתו\"מ כל היום, וכנ\"ל דמעט מן האור דוחה הרבה מן החושך כי כהמס דונג כו' לפי שאין מקום לרע במקום שמאיר האור האלקי דקדושה, וזהו מ\"ש ואמרת כו' על כי אין אלקי בקרבי<sup data-n=\"1259\">317</sup> מצאוני הרעות שהן הקליפות דכל טומא' מחשבה רעה ומדות רעות, דמשמע מזה שאם הי' אלק\"י בקרב\"י במוח ולב אין מקום לרע כלל וזהו כי רע ומר עזבך ה'<sup data-n=\"1260\">318</sup> כו', ולהיפך בהאיר אור האלקי בנשמתו שבמוחו ולבו בשמחת ההתבוננות כו' יתפשט ההארה האלקי' הזאת גם בחלק הגשמי שבדם הוא הנה\"ט שהוא חלל השמאלי שיטה כל לבו לה' ולא יהי' לו רק לב אחד לאביו שבשמים וזהו בכל לבבך בשני יצריך<sup data-n=\"1261\">319</sup> כו', וזהו חדלו לכם מן האדם אשר נשמה באפו פי' שקודם התפלה<sup data-n=\"1262\">320</sup> שלא האיר אור אלקי בנשמתו עדיין הנשמה באפ\"ו ואחר התפלה הרי הארה האלקי' מתפשט בכל חלקי הגוף לזכך חומריות שלו וכנראה בחוש לכל טועם טעם בעבודה שבמוח ולב בתפלה.\n<b>וזהו</b> בה\"א כלה נאה וחסודה, פי' בית הלל להיותם מבחי' החסדים דאור ישר היפך בית שמאי ששמין א\"ע תחלה כנ\"ל אלא אדרבה משבחים ומהללים תמיד בגדולת ה' בעבודה שבלב בשמחה גם אם אינו מוצא א\"ע בכשרון כלל, וזהו ל' בהל\"ו נר\"ו<sup data-n=\"1263\">321</sup> שיוסיפו אור אלקי בנשמתם תמיד מלמעלה למטה ואינם משגיחים לדקדק ע\"ע כ\"כ אם אינם ראוים לזה לפי מעשיהם אלא המה ממשיכים תמיד גילוי אור אלקי' חיים גם שלא לפי ערך מעשיהם בסור מרע וכשרון גופם שנק' העלאה (וזה סותר למאמר דר' פנחס בן יאיר דטהרה מביאה לידי קדושה מלמטה למעלה וכן מאמר דכל שיראת חטאו קודמת לחכמתו כו' וכן אם אין יראה<sup data-n=\"1264\">322</sup> כו' וגם ענין תש\"ת שקדמה לתש\"ע, אלא הכל בהיפך דוקא שקדושה דאור האלקי שנמשך מלמעלה עי\"ז נזדכך חומר גופו ונטהר לבו מן הרע מעט מעט כו' והוא ע\"י תו\"מ אשר קדשנ\"ו במצוותי\"ו כו' מביאה לידי טהרת הלב כו', ותש\"ע קדמה לתש\"ת כמ\"ש השיבנו ה' אליך מלמעלה למטה ואח\"כ ונשובה וכן משכני<sup data-n=\"1265\">323</sup> ואח\"כ נרוצה כמשי\"ת, ומ\"ש כל שיראת חטא קודם",[["1259","317","<b>ואמרת כו' על כי אין אלקי בקרבי</b>: וילך לא, יז."],["1260","318","<b>כי רע ומר עזבך ה'</b>: ירמי' ב, יט."],["1261","319","<b>בכל לבבך בשני יצריך</b>: ברכות נד, א."],["1262","320","<b>חדלו לכם. . שקודם התפלה</b>: ישעי' ב, כב. ברכות יד, ב."],["1263","321","<b>בהלו נרו</b>: איוב כט, ג [וראה ס' מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תח]."],["1264","322","<b>דטהרה מביאה. . דכל שיראת חטאו. . אם אין יראה</b>: ע\"ז כ, ב. אבות פ\"ג מ\"ט. מי\"ז."],["1265","323","<b>השיבנו ה' אליך. . משכני</b>: איכה ה, כא. שה\"ש א, ד."]]],[1900420289,"בזה מודים ב\"ה דודאי א\"א לומר שגם רשע גמור שעובר על ל\"ת של תורה יוכל לעבוד בגילוי אור המשכות אלקות בתפלה ותו\"מ שהרי א' ולרשע מה לך<sup data-n=\"1266\">324</sup> כו' וכן המתועב במדות רעות וחטאים לא יוכל לבא להודות ולהלל, וזהו הנק' יראת חטא בפ\"מ שקדם ודאי וליכא מאן דפליג ע\"ז, רק כמו תאות היתר שבא מצד חומר הגופני ובמניעת מעשה הטוב כו'* שיזדכך ע\"י הארה האלקי' מלמעלה למטה, ודוגמא לדבר במצות ת\"ת שהיא המשכת אא\"ס בח\"ע כו' א' בעל קרי מותר<sup data-n=\"1267\">326</sup> בד\"ת<sup data-n=\"1268\">325</sup> שאין ד\"ת מקבלים טומאה וכן אמרו מאור שבה מחזירו למוטב<sup data-n=\"1269\">327</sup> שזהו הזדככות הגוף הבא מצד אור העליון דתורה, אבל לא שיוכל לתקן ולזכך מי שעשה עבירה גמורה שע\"ז א' ולרשע כו' וכה\"ג, וזהו מבחי' החסדים דיכולים הכל לעלות גם שאינו בר לבב בהיתר) (ולפי פשט הענין מורה דגם חיגרת או סומא כלה נאה הרי גם בפגם העון בפ\"מ יוכל לעלות ע\"י שיעסוק בתו\"מ וכו' דלא כדלעיל).\n[לו] <b>וזהו</b> משכני אחריך נרוצה דהיינו הארת אור האלקי בנשמ' המושך אותה עד שתרוץ ממילא כניצוץ לשלהבת, וזהו ונרוצה ממילא בלתי בחירה, אך בתנאי דמשכנ\"י תחלה מלמעלה למטה, וכן השיבנו ה' אליך תחלה ואח\"כ ונשובה מעצמינו, וכמ\"ש במ\"א בפי' ישוב ירחמינו<sup data-n=\"1270\">328</sup> כו' דבר\"ה ויו\"כ תש\"ע קדמה לתש\"ת, בהיות שידוע דאו\"פ קדם לאו\"מ, כמו תחלה אהבה שמצד השכל המתיישב בלב ומה שלא יתיישב בלב נק' או\"מ דא\"ח והוא אה\"ר דבכל מאדך, ולפ\"ז גם תש\"ת מפנימיות הלב ממעמקים קראתיך תחלה ואח\"כ תש\"ע שישוב ירחמינו מלמעלה למטה, ונהפוך הוא דתש\"ע קודמת וכמ\"ש השיבנו תחלה כו'. והענין הוא דבחי' מקיף דאור ישר המקיף קדם לפנימי לפי שהולך מלמעלה למטה משא\"כ מקיף דאור חוזר שבא מלמטה למעלה ולפי ערך אהבת עולם דבחי' או\"פ כן יהי' מקיף דאה\"ר אח\"כ, וזהו כדעת ב\"ש דלעיל משום דמאתדל\"ת נעשה אתדל\"ע לפי ערך הזדככות המקבל לבד כנ\"ל, אבל דעת ב\"ה הוא בבחי' מקיף דאור ישר מבחי' החסדים שיורד מגבוה לנמוך ע\"כ אדרבה תש\"ע דישוב ירחמינו הולך מלמעלה למטה בכנ\"י תחלה ואח\"כ נעשה בחי' תש\"ת שנק' אתדל\"ת, ואין אור המקיף דתש\"ע תלוי' בתש\"ת כלל דגם אם אין התעוררות תשובה למטה כלל ישוב ירחמינו מצד התעוררות עצמו, וכענין משכנ\"י הנ\"ל ואז ממילא יפול התעוררות תשובה בכנ\"י וכמ\"ש ונרוצ\"ה ממילא אחריך בהתעוררות תשובה למעלה מן הטעם כי לא שלנו היא כו' כי בלתי זה",[["1266","324","<b>ולרשע מה לך</b>: תהלים נ, טז."],["1267","326","<b>בעל קרי מותר בד\"ת</b>: ברכות כב, א."],["1268","325","<b>כו'. . בד\"ת</b>: תיבה אחת טושטשה כאן בדיו, ולא ניתנה לקריאה."],["1269","327","<b>מאור שבה מחזירו למוטב</b>: ראה ירושלמי חגיגה פ\"א סה\"ז (ובקה\"ע שם). איכ\"ר פתיחתא ב (ובמת\"כ שם)."],["1270","328","<b>וכמ\"ש במ\"א בפי' ישוב ירחמנו</b>: ראה לעיל אות לד. וש\"נ."]]],[1900420290,"שיערה עלינו רוח ממרום אין כח בכנ\"י להתעורר בתשובה, וכמשל הנ\"ל בב' בנ\"א שהעליון יורד לגבי התחתון כו'.\n<b>(ונמצא</b> מובן מכל זה שעיקר ההפרש בין דעת ב\"ש לדעת ב\"ה שהוא לפי שרש מדרגתם למעלה היינו בבחי' החו\"ג דמקיף דאו\"ח ומקיף דאור ישר, דשרש ב\"ש מבחי' הגבורות דאור חוזר הרי בחי' או\"פ קדם שהוא מה שיוכל הלב להזדכך בתש\"ת ומה ששם אורחותיו תחלה כן לפי ערך יבא לבחי' אה\"ר הנ\"ל והוא מקיף דאו\"ח שבא מלמטה למעלה ובזה תש\"ת קודם לתש\"ע ואהבת עולם קודם לאה\"ר כו', אבל דעת ב\"ה שהן מבחי' החסדים דאור ישר היינו מבחי' המקיף דאור ישר שנהפוך הוא שתחלה יאיר האור מלמעלה למטה על נשמות האלקי' בבחי' מקיף, והוא בהילול ושבח כנ\"ל וכהשיבנו ה' וישוב ירחמינו הנ\"ל שהוא בהעלם ובאור דתורה ומצו' בחי' קדושה אלקי' בבחי' מקיף, ואח\"כ מבחי' המשכות אלקות זה יבא האור גם בבחי' פנימי לזכך הלב ומוח, והוא כמו תש\"ת שאחר תש\"ע דוקא שזהו עיקר ההפרש בין מקיף דאור ישר ובין מקיף דאור חוזר וד\"ל) (והיינו ענין ב' מיני כבוד עליון ותחתון דחופה דכבוד עליון נק' מקיף דאור ישר וחופה דכבוד תחתון דכלה לחתן שהוא בכל מאדך נק' מקיף דאור חוזר, והוא מחלוקת דב\"ש וב\"ה הנ\"ל).\n[לז] <b>אך</b> הנה עדיין יש להבין דברי ב\"ה שאומרים כלה נאה וחסוד\"ה מה ענין הנוי הזה לכלה אע\"פ שאינו כן באמת, וגם מה ענין חסוד\"ה לכאן שהרי גם אם מצד האור מקיף דאור ישר שמאיר מלמעלה בנשמה אלקי' יומשך ויבא גם במוח ולב ומעשה בבחי' או\"פ עדיין לא יתכן שתקרא נאה וחסודה במעשיה אם יש בה פגם וחסרון כחגרת או סומא (וגם יש להבין תשובת ב\"ה על קושיא חזקה דב\"ש שמקשי' לב\"ה הרי אמרו מדבר שקר תרחק והשיבו מי שלקח מקח כו', דעדיין לא מיושב דמ\"מ מדבר שקר תרחק, וגם מהו ענין זה המשל דמי שלקח כו'). והנה יש להקדים לזה ענין הנ\"ל בב' מיני מדרגות שבנשמה שנק' צדיק עליון וצדיק תחתון ונק' נהורא חוורא ונהורא אוכמא כו' ונק' קדושה וטהרה והן ב' אבנים דשהם וישפה כו' כנ\"ל באורך. והנה אנו אומרים נשמה שנתת בי טהורה היא (מבחי' טה\"ע), ולכאורה איך יאמר אדם על אור נשמתו שבגופו טהור\"ה היא אחר שיודע בנפשו שנטמאה בהרבה מיני טומאה אם בהיתר וכ\"ש באיסור כו', כמו כאשר פגם בעין רואה דכתיב ולא תתורו<sup data-n=\"1271\">329</sup> כו' ואחרי עיניכם כו' פגם עיניו להסתכל ביקרא דמלכא<sup data-n=\"1272\">330</sup>, וזהו שאומרים בוידוי דק\"ש שעהמ\"ט שפגמתי באות יו\"ד כו', וכך פגם בה\"א וי\"ו וה\"א דשם הוי' שבצלם נפשו שנק' בשם נר הוי', ואיך או' נשמה כו'",[["1271","329","<b>ולא תתורו</b>: שלח טו, לט."],["1272","330","<b>להסתכל ביקרא דמלכא</b>: ע\"פ זח\"א לח, א-ב. קצט, א. זח\"ב קלד, א. רמז, ב."]]],[1900420291,"טהור\"ה היא לגמרי מכל פגם וחסרון, ואם נאמר כדעת ב\"ש ששם אורחותיו ונמצא כולו טהור כו' ודאי אין צדיק בארץ שלא יחטא בהרהור עבירה וכו' וא\"צ לדבר מזה כו', אך מזה מוכרח לומר דהלכה כב\"ה במחלוקת זו דגזרו אומר דאע\"פ שהכלה חיגרת או סומא מ\"מ כלה נאה כו'.\n<b>והענין</b> הוא כנ\"ל שיש ב' מדרגות בנשמות, והמדרגה העליונה הוא מה שנק' בשם קדושים וכמ\"ש וקדושי\"ם אשר בארץ<sup data-n=\"1273\">331</sup> וקדושים בכל יום יהללוך כו', והוא מ\"ש עליהן כולך יפה רעייתי<sup data-n=\"1274\">332</sup> מום אין בך כלל, דשרש הנשמות כמו שהן דבוקות וצרורות למעלה שנק' מזלא וצל\"ם כנ\"ל נק' רחל יפת תואר ויפת מראה (וכמ\"ש במ\"א בפ' כי תצא בענין וראית בשביה<sup data-n=\"1275\">333</sup> אשת יפ\"ת כו' באריכות), פי' תוא\"ר הוא העצם שבעצם היא יפה ויפת מראה הוא למראה העין לבד. וההפרש הוא ששרש הנשמות כמו שהן למעלה אף של הפחות וקל כו' נק' יפ\"ת ומום אין בה כלל, וכמ\"ש מיד כל\"ב יחידת\"י<sup data-n=\"1276\">334</sup> שבחי' יחידה דכאו\"א נקי מכל פסולת וסיג לגמרי וע\"ז נא' ועמ\"ך כולם צדיקים<sup data-n=\"1277\">335</sup> כולם ממש גם פושעי ישראל כו' והוא בחי' צדיק עליון נהורא חוורא הנ\"ל. אך הנה כתיב חדשים לבקרים רבה אמונתך, שבכל בקר מתחדש כח הנשמה שבגוף הנפגם מבחי' מזלא וצלם המאיר מבחי' קדוש שנק' נהורא חורא כו' ליתן בה כח ועוז להתפעל במוח ולב בהתבוננות ובמעשה כל היום להנצל מכל הרהור רע כו', וזהו רבה אמונת\"ך אמונ\"ה דנשמה כמו אומ\"ן את היונק ממש כו' (וכמ\"ש במ\"א באריכות<sup data-n=\"1278\">336</sup>), וכאשר יורד האור מבחי' צלם ומזלא להאיר בדרך פרט בכל חלקי הנשמה האלקי' שבמוח ולב ומעשה ותשובה כו' יוכל להיות שיתקן כל הפגמים וחסרונות שבעונות האדם שדש בעקביו, וכענין התשובה שמביאה רפואה לעולם<sup data-n=\"1279\">337</sup> כרפואה שמרפא חולי הגוף כך ירפא חולי הנפש בכל מקום שנפגמה, והיינו מעט מעט, והוא מדי יום ויום שצל ימינו עלי ארץ שלזה ניתן לאדם ע' שנה לברר פרקי הצל\"ם דנשמה דא\"ך בצל\"ם<sup data-n=\"1280\">338</sup> יתהלך איש כל ימי",[["1273","331","<b>וקדושים אשר בארץ</b>: ע\"פ תהלים טז, ג."],["1274","332","<b>כולך יפה רעייתי</b>: שה\"ש ד, ז."],["1275","333","<b>במ\"א בפ' כי תצא בענין וראית בשבי'</b>: ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תצח ואילך [וראה בהנסמן שם בתחילת המאמר בסוף ע' תפא]."],["1276","334","<b>מיד כלב יחידתי</b>: תהלים כב, כא."],["1277","335","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["1278","336","<b>חדשים לבקרים רבה אמונתך. . אומן את היונק. . וכמ\"ש במ\"א באריכות</b>: איכה ג, כג. בהעלותך יא, יב. ראה ס' מאמרי אדהאמ\"צ בראשית ע' קה. במדבר ח\"ד ע' א'שיד. דברים ח\"ב ס\"ע תקה. ח\"ג ע' תתטו ואילך וע' תתכב. לעיל ח\"א ס\"ע קעט. וש\"נ."],["1279","337","<b>תשובה שמביאה רפואה לעולם</b>: יומא פו, א."],["1280","338","<b>שצל ימינו עלי ארץ. . דאך בצלם</b>: איוב ח, ט [וראה גם ס' מאמרי אדהאמ\"צ בראשית ע' סח. רמג. שע. תלה. תנב. שמות ח\"ב ע' שמא. ויקרא ח\"ב ע' תרפג. תשמט. דברים ח\"ב ע' שפא. ח\"ד ע' א'שע]. תהלים לט, ז."]]],[1900420292,"חייו כו', ויום אחד שאינו מתקן מכח הצלם בגופו מאומה לא במוח ולב ולא במעשה כל היום נק' יומא דפגרא<sup data-n=\"1281\">339</sup> ל' פג\"ר כו' וכמ\"ש במ\"א בפי' ימים יוצרו<sup data-n=\"1282\">340</sup> ולא אח\"ד בהם כו' וד\"ל.\n[לח] <b>והנה</b> זהו כאשר יש ביכולת האור מקיף דצלם ומזלא לעורר הנשמה שבגוף לתקן כו', אך יש שלא יתוקן מצד חומר העון וגם אינו מתעורר כלל בתשובה כו', הנה יש עוד מדרגה שלמעלה מזה והוא למעלה מבחי' מזלא הנ\"ל, והוא מבחי' יחידה הנ\"ל שנק' יפ\"ת בעצם, כי ידוע שיש למעלה ב' מיני מקיפים א' שמאיר בגוף והוא הנק' מזלא והב' הדבוק תמיד למעלה ממש וכמ\"ש דיוקני אשתאר בך ממש כו', שע\"ז א' כולך יפה רעייתי וכן הנך יפה<sup data-n=\"1283\">341</sup> רעייתי כו' יפה בעצם בלי השתנות כלל, ונק' ברתא דמלכא ומאן דקטיל לחויא<sup data-n=\"1284\">342</sup> בתשובה שלימה כו' יהבין לי' ברתא דמלכא שהיא בחי' יחידה שמשם יכול להיות תיקון כל פגם וחסרון שמן העונות ממש למלאות כל חסרון כו' וכמ\"ש אם יהיו חטאיכם כשנים<sup data-n=\"1285\">343</sup> כו', וכמו ע\"י תשובה עמוקה כתשובת ראב\"ד כו' וכנתן<sup data-n=\"1286\">344</sup> כו' ונסלח העון ונעשה כולו יפה ונאה כו' וד\"ל. ושרש הענין למעלה היינו כשנמשך מבחי' סובב כל עלמין שלמעלה מבחי' אד\"ם כו', כמו ביו\"כ דכתיב אנכ\"י אנכי מוחה כו' וזרקתי עליכם<sup data-n=\"1287\">345</sup> כו' לפני ה' תטהרו שגם כל חסרון ופגם יתוקן וגם הטמא ממש יטהר כו' משום דקמי' ממש כחשכ\"ה כאורה וגם חושך לא יחשיך כו' וכמ\"ש מי יתן טהור מטמא לא אחד כו', ושם נאמר אם צדקת<sup data-n=\"1288\">346</sup> מה תתן לו ואם רבו פשעיך מה תעשה לו שאין כל הפגמים דעונות ופשעים תופסים מקום כלל דכולא קמי' כלא חשיבא כו', וזהו בשמים ממעל<sup data-n=\"1289\">347</sup> ועל הארץ מתחת שניהם שוין בלתי חילוק מדרגות כלל וכמשל העיגול שאין בו מעלה ומטה כלל כידוע, ע\"כ בהגלות נגלות האור עליון דעצמות א\"ס ב\"ה שבבחי' סובב הכללי משם נתמלא כל חסרון ופגם, וכמו בחי' יחידה שבאדם הנ\"ל וד\"ל.",[["1281","339","<b>יומא דפגרא</b>: ראה שבת קכט, ב, ומפרשים שם. וראה ס' מאמרי אדהאמ\"צ בראשית ע' תנב. שמות ח\"ב ע' שמא."],["1282","340","<b>וכמ\"ש במ\"א בפי' ימים יוצרו</b>: תהלים קלט, טז. ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשמט. לעיל ח\"א ע' רפ. ובהנסמן לעיל ע\"פ צל ימינו. ובכ\"מ."],["1283","341","<b>דיוקני אשתאר בך. . כולך יפה. . הנך יפה</b>: זח\"ב קיד, א [וזח\"א רמד, ב. רמה, א]. שה\"ש ד, ז. א, טו."],["1284","342","<b>ומאן דקטיל לחויא</b>: ראה תקוני זהר סוף תי\"ג (כא, ב). ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תפב."],["1285","343","<b>אם יהיו חטאיכם כשנים</b>: ישעי' א, יח."],["1286","344","<b>כתשו' ראב\"ד. . וכנתן</b>: ראה לעיל אות ל\"א. וש\"נ."],["1287","345","<b>אנכי אנכי מוחה. . וזרקתי עליכם</b>: ישעי' מג, כה. יחזקאל לו, כה."],["1288","346","<b>כחשכה כאורה וגם חושך. . מי יתן. . אם צדקת</b>: תהלים קלט, יב. איוב יד, ד. לה, ז."],["1289","347","<b>בשמי' ממעל</b>: ואתחנן ד, לט."]]],[1900420293,"<b>וזהו</b> כלה נאה וחסודה פי' חסוד\"ה ל' נפעל שהוי\"ו מורה דחסוד\"ה הוא שנמשך בה מבחי' רב חסד העליון וכמו באסתר שאמרו שחוט של חסד<sup data-n=\"1290\">348</sup> משוך עלי' כך חוט של חסד העצמות דא\"ס נמשך בכנ\"י שנק' כלה לכך נק' חסודה (והוא בחי' החסדים העליונים שנמשך לבנין המל' וכמ\"ש והוכן בחס\"ד כסא וכן אמרת\"י עולם חס\"ד יבנ\"ה<sup data-n=\"1291\">349</sup> כו'), ולא שנמשך בה חסד עליון פעם א' לבד אלא שתמיד נמשך בה החסד עליון דהיינו מצד חוט של חסד עליון דבתמידות הוא נמשך עלי' ע\"כ היא נק' חסודה שנתפעלת מקבלת אור חסד זה בתמידות עד שגם היא נק' חסודה בעצם להיותה בחי' מקבל מהחסד בתמידות, דחסד שם העצם והמקבל החסד בתמידות דוקא נק' חסוד\"ה כו', וענין הארת אור החסד הזה פועל בה להשפיע חסד למקבלים הימנה דהיינו שעושה חסד מצד עצמה תמיד והוא ח\"ס דלי\"ת לדלים כו' וד\"ל. והנה חוט של חסד זה נמשך מעצמות אא\"ס שלפני הצמצום כו' כנ\"ל, והיינו שמחמת אור זה דוקא נק' כלה נא\"ה שנעשית נאה בכל האיברים הרוחניים שבנפש הגם שכבר נפגמו הרבה מאד כנ\"ל, כמו גם אם נפגמה בעין שהוא ביו\"ד דחכמה ונק' סומא או ברגל הרוחני שהוא ההילוך בדרכי ה' במעשה דסור מרע כו' כנ\"ל ונק' חגרת וכה\"ג, כל הפגמים באיברים הכל יתוקן ויתמלא כל פגם עד שתקרא כלה נאה באיברי' ובפניה הגם שחשך תארה מן הפגמים אבל נעשית נאה בתואר ומראה, וכמו ומראך נאו\"ה וכן א' כנ\"י בגלות שחורה אני<sup data-n=\"1292\">350</sup> ונאו\"ה כו' משום שיאירו פניה מלמעלה, ונק' כלה נא\"ה למטה, שבאמת למעלה הרי נאמר כולך יפה רעייתי מום אין בך כלל והיופי הזה שמקבלת מלמעלה הרי שם היא יפה בעצם ונמשך גם למטה, והוא ע\"י גילוי אור העליון דעצמות כו', וזהו כלה נא\"ה באיברי' שהוא נר\"נ שבגוף ופנים בעצם וחסוד\"ה להיות מתפשט במעשה החסד לדלים והוא מצד שבחי' חוט של חסד משוך עלי' מלמעלה שמשם היא כלה נא\"ה דוקא כנ\"ל (וזהו מצד שב\"ה שרשם מבחי' החסדים דאור ישר ולכך א' כלה נא\"ה שמהללים ומשבחים ביופי' וההילול ושבח הזה בא מצד שכולך יפה למעלה כנ\"ל, וזהו בבחי' מקיף דמזלי' כנ\"ל, ואח\"כ נמשך בבחי' או\"פ והוא שחוט של חסד עליון משוך בה בתוך תוכה עד שנעשית בחי' משפיע למטה ונק' חסוד\"ה בעצם לעשות חסד וצדקה למקבלים כנ\"ל וד\"ל).\n<b></b>[טל] והנה מעתה יובן גם מה שפלפלו וטענו ב\"ש עם ב\"ה הרי שהיתה חגרת או סומא כו' הלא אמרו מדבר שקר תרחק והשיבו ב\"ה מי שלקח מקח מן השוק כו'. דהנה כל הנ\"ל בענין כלה בפרט בכל ניצוץ אלקי שבכאו\"א, כך יובן בבחי' כלה העליונה בכללות הנשמות דנק' נשמת כל חי כו' וכמא'",[["1290","348","<b>שחוט של חסד</b>: מגילה יג, א."],["1291","349","<b>והוכן בחסד כסא. . אמרתי עולם חסד יבנה</b>: ישעי' טז, ה. תהלים פט, ג."],["1292","350","<b>ומראך נאוה. . שחורה אני</b>: שה\"ש ב, יד. א, ה."]]],[1900420294,"מה הנשמה<sup data-n=\"1293\">351</sup> כו' כך כו' ונק' ממלא כ\"ע, והוא בחי' מל' דאצי' שמתצמצם להחיות רוח שפלים והן נשמות ומלאכים דבי\"ע עד עוה\"ז השפל כו', ובחי' סובב כ\"ע שהוא בחי' ז\"א דאצי' נק' חתן העליון, וע\"ז הוסדו כל ענין שה\"ש שזהו כאהבת חו\"כ למטה וכמו לבבתני אחותי כלה<sup data-n=\"1294\">352</sup> כו', וכל ענין מחלוקת דב\"ש וב\"ה אם כלה כמות שהיא או כלה נאה וחסודה הכל הם מדברים בבחי' כלה העליונה, דבש\"א לפי ערך הבירורים והעלא' דרפ\"ח ניצוצי' ומלאכים ונשמות דבי\"ע (שזהו כמו התלבשות הנפש בגוף) שנק' אתדל\"ת כך הוא אופן אתדל\"ע לא פחות ולא יותר, וע\"כ כלה כמו שהיא דוקא (ולפעמים פוגמים בה ביותר כשהחיצונים מתגברים מצד העונות למטה ויורדת המל' בגלות בע' שרים ונק' שחור\"ה וכידוע בענין פגימת הלבנה<sup data-n=\"1295\">353</sup> כו') וכנ\"ל בענין השם אורחותיו כו' כך הוא בכללות נש\"י כו' וד\"ל. ובה\"א כלה נאה וחסודה מצד הארת אור עצמות א\"ס שבבחי' סובב הכללי ששם נק' כלה נא\"ה וחסוד\"ה, והוא כנ\"ל בנשמ' פרטי' ממש וד\"ל. ומה שטענו ב\"ש מדבר שקר תרחק אין זה דבר שקר דגם שבחי' המל' מצד ירידתה בהיכלות הנוג\"ה לברר ברורים דרפ\"ח כו' יכול להיות שנפגם אורה עד שתקרא חגרת או סומא כו' אין זה מצד עצמה כלל דכמו שהיא למעלה הרי א' כולך יפה רעייתי מום אין בך כלל כנ\"ל. וזהו שהשיבו להם ב\"ה ברמז לתרץ זה דזהו כמו מי שלקח מקח מן השוק, פי' מן השוק הן הנה בחי' היכלות דנוג\"ה כו' שנק' שו\"ק וכמו אמצא\"ך בחו\"ץ אשקך וכן חכמות בחו\"ץ תרונ\"ה<sup data-n=\"1296\">354</sup> שהוא רפ\"ח ניצוצי' שנפלו בקליפת נוג\"ה וחכמה תתאה דבחי' המל' הוא שם ב\"ן יורד למטה מטה לברר וכו', וכאשר עולה למעלה זהו מק\"ח שלקח מן השו\"ק כו', וכמשל אדם שלקח מקח מן השוק שמוכרח זולתו לשבח אותו כו', שזהו ידוע בסוחרים במסחר שלא יפול לב אדם על הסחורה כי יוכל להיות בה ריוח גדול גם שהיא רעה ושפלה (משא\"כ כליו וחפציו אינו מוכרח לשבח ולומר שקר, אבל מה שלוקחים דרך מו\"מ יכול לשבח באמת דכן דרך התגרים שמשבחים לכל סחורה אחר שיקנו מטעם זה, וכך הוא בענין בירור הרפ\"ח שנק' מו\"מ ע\"י המל' שנק' אשת חיל וכמ\"ש אשת חיל מי ימצא<sup data-n=\"1297\">355</sup> כו' דרשה צמר ופשתים כו' סדין עשתה כו', ולע\"ל יבורר בתכלית כל הניצוצות וכמ\"ש ואת רוח הטמאה<sup data-n=\"1298\">356</sup> אעביר כו' הרי יהי' מזה ריוח גדול מאד וד\"ל (וא\"כ יפה השיבו ב\"ה דמטעם זה אין זה שקר כלל לומר כלה נאה וחסודה אע\"פ שהיא חגרת עכשיו כמו שלע\"ל נאמר אז ידלג כאיל פסח",[["1293","351","<b>מה הנשמ'</b>: ראה ברכות י, א. ובהנסמן עוד לעיל אות ה."],["1294","352","<b>לבבתני אחותי כלה</b>: שה\"ש ד, ט."],["1295","353","<b>וכידוע בענין פגימת הלבנה</b>: ראה גם סה\"מ תקס\"ו ע' צו. ביאוה\"ז לאדהאמ\"צ עח, א ואילך. ביאוה\"ז להצ\"צ ע' קלה ואילך. ובכ\"מ."],["1296","354","<b>אמצאך בחוץ. . חכמו' בחוץ תרונה</b>: שה\"ש ח, א. משלי א, כ."],["1297","355","<b>אשת חיל מי ימצא</b>: משלי לא, י ואילך."],["1298","356","<b>ואת רוח הטומאה</b>: זכרי' יג, ב."]]],[1900420295,"ותרנן לשון אלם דמה שעכשיו נאמר נאלמתי דומי'<sup data-n=\"1299\">357</sup> כו' תרנ\"ן לשון אל\"ם וידלג הפסח דעכשיו וכן ועינינ\"ו מאירו\"ת ורגלינ\"ו קלות כו' וד\"ל).\n[מ] <b>והנה</b> עדיין יש להבין ביאור ברייתא זו דכיצד מרקדין מה שאמר מרקדין ל' מפעיל ולא אמר כיצד רוקדין, ועוד מ\"ש לפני הכלה ולא עם הכלה ומשמעות לפני לשון למעלה הימנה כו'. אך הנה באמת יש להבין תחלה בענין החופה שע\"ג החו\"כ יחד מהו, להיות שיחוד זה דחו\"כ דבר פלא הוא לכאורה שזהו היפוך הטבע בכל יחוד והתכללות שאינו אלא בדברים המשתווים במהות א' ונמשכים זע\"ז יתכללו כאחד, והרי החו\"כ המה ב' הפכים בטבעם כידוע דמשפיע ומקבל המה ב' הפכים ממש כאש ומים, שכמו שטבע המים להתפשט ולירד מגבוה לנמוך כך טבע המשפיע לצאת מעצמו להמשיך ולהתפשט למטה מגבוה לנמוך, וכמו טבע האש לעלות מלמטה למעלה דוקא כך טבע המקבל לעלות ולקבל בבחי' התשוקה והוא לצאת מעצמו לקבל השפע כו' וכמו ואל אישך תשוקתך<sup data-n=\"1300\">358</sup> כו', ולכך נק' כלה ל' כלת\"ה נפשי כו', והנה עם היותם ב' הפכים כאש ומים אנו רואים שתשוקתם זה לזה להתכלל ולהתחבר זע\"ז היפך טבע כל שני מנגדים כאש ומים שא\"א שיתכללו יחד שהרי תאובתא דדכורא לגבי נוק' דוקא להתייחד ולהשפיע בה וטבע הנוק' תאובתא לגבי דכורא לקבל כו', ואדרבה מה שזה טבעו להשפיע וזה טבעו לקבל הוא הגורם חשק יחודם כו', ולא עוד אלא שביחודם יחד מולידים מאמצעות שניהם ולד בדומה להם והם בעצמם ובטבעם ב' הפכים מן הקצה כו' כאש ומים כנ\"ל.\n<b>אך</b> הנה זהו ענין החופה שקודם היחוד דכלה וחתן שזהו בחי' המקיף שלמעלה מן המשפיע ומקבל שמשם יבא כח ומקור ליחודם תמיד כל ימיהם כו'. דהנה ידוע בטבע כל עילה ועלול שהוטבע בטבע העילה שירצה ויחשוק להשפיע לעלול, וכמ\"כ יש טבע מוטבע בעלול שיחפוץ ויחשוק לקבל מעילה שלו, וכדמיון מה שא' יותר משהעגל רוצה לינק<sup data-n=\"1301\">359</sup> הפרה רוצה להניק כו', וכדמיון תלמיד ורב ועשיר ועני שזהו נק' עו\"ע דטבע הטוב והחשק יש ברב להשפיע לתלמיד וכן יש חשק בתלמיד לבקש אור שפעו כו'. אך ידוע שיש הפרש גדול בין כל עו\"ע לענין הזווג דחו\"כ דכר ונוק', שבעו\"ע אין בזה תולדה חדשה מאי\"ן האלקי רק מה שיש בעילה לבד נמשך לעלול ואין לעלול מציא' שפעו בלעדו, אבל הנקבה מהות בפ\"ע רק שצריכה להתייחד בזכר ולקבל מ\"ד להוליד והתולדה מבחי' מ\"ן שלה כידוע בענין אשה כי תזריע<sup data-n=\"1302\">360</sup> וילדה כו', א\"כ אין זה כשאר עו\"ע אלא שיהי' ביחודם כח עליון משניהם שימשיך בהם כח התולדה בחיבורם, והוא מה שיומשך זה לזה ויתכללו כא' כנ\"ל זהו מבחי'",[["1299","357","<b>אז ידלג כאיל פסח. . נאלמתי דומי'</b>: ישעי' לה, ו. תהלים לט, ג."],["1300","358","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1301","359","<b>יותר משהעגל רוצה לינק</b>: פסחים קיב, א. ראה גם להלן ד\"ה לה\"ע שמחת חו\"כ אות ל. וש\"נ."],["1302","360","<b>כידוע בענין אשה כי תזריע</b>: תזריע יב, ב. ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תר. וש\"נ."]]],[1900420296,"המקיפים דשניהם שמתכללים כאחד ע\"י שעומדים חו\"כ יחד תחת החופה כו'. והענין הוא דבחי' מזלי' דחתן ומזלי' דכלה כמו שהן בשרשן למעלה זה מעלמא דדכורא וזה מעלמא דנוק' מתבטלים לבחי' אי\"ן ומתרוממים ומוגבהים במקום הנעלה משניהם שהוא החופה החופפת עליהם יחד ומתייחדים ומתכללים כאחד שם, והוא שרש ומקור ליחודם אח\"כ להוליד בנים וגם בחיי ומזוני כל ימיהם דבמזלא תליא הכל ממה שהי' בעמדם תחת החופה יחד שהי' כל א' בבחי' ביטול לאי\"ן האלקי שבשרש נשמתו למעלה שנק' מזלא, ויחוד ב' מזלות הללו דדכר ונוקבא הוא העושה בהם התשוקה ליחודם ואע\"פ שהמה ב' מנגדים בטבעם אדרבה זו הגורם תשוקת כ\"א לזולתו שיוציאו תולדה מבין שניהם יחד דוקא (וזהו כמו שידוע בשרש של יחוד דאו\"א הוא תלוי ביחוד עליון דב' מזלות דונוצר ונקה מזל העליון דמשפיע ומזל התחתון דונקה שמתכללים כא' בחופה שלמעלה משניהם יחד, והוא כמו מבחי' ת\"ת דא\"א שנעשה כת\"ר לאו\"א<sup data-n=\"1303\">361</sup> כו' וכה\"ג, וכידוע בענין כי על כל כבוד חופה דקאי גם בכבוד עליון דאבא כו', וכמ\"כ מת\"ת דאימא כתר לזו\"נ נק' חופה לגבי זו\"נ כו' וד\"ל).\n[מא] <b>וזהו</b> כי על כל כבוד חופה, משמע על כל כבוד יש חופה בפ\"ע, והיינו על כבוד דחתן המשפיע יש חופה בפ\"ע ועל כבוד דכלה יש חופה בפ\"ע, וא\"כ יש כאן ב' חופות (זה עולה מלמטה למעלה וזה יורד מלמעלה למטה ומתחברים יחד כנ\"ל), ובאמת הרי חופה אחת על החו\"כ יחד כו', אך שניהם אמת, דחופה של כל א' הוא בחי' המזל, וכת\"ר דחתן נק' מקיף דאור ישר וחופה דהיינו מזל וכת\"ר דכלה נק' מקיף דאור חוזר, ושני המזלות מתייחדים כא' מצד בחי' ביטול של כל א' לאי\"ן שזהו במקור הנעלה משניהם שזהו בחי' אור אלקי שנעלה משרש המשפיע ושרש המקבל והוא החופה האחת שמוגבהים ומתרוממים שם חו\"כ בבחי' ביטול לאי\"ן ממש כנ\"ל, וכדוגמא הידוע בב' הפכים דמיכאל וגבריאל שר של אש ושר של מים לגבי אור האלקי הנעלה מהם שמתבטלים ממציאותם לגמרי אין מכבין<sup data-n=\"1304\">362</sup> זא\"ז, כך יחוד והתכללות דחו\"כ אע\"פ שהן ב' הפכים כאש ומים כנ\"ל מתבטלי' לאי\"ן האלקי שבמקיף דחופה הנעלה משניהם ואחר שנתבטל כל אחד לאין ישרה אור האלקי ביחודם להוליד תולדה חדשה יש מאין כו' וא\"ל לא הי' כח ביחודם להוליד נשמות כו' וד\"ל. ושרש הדברים הוא להיות שחופה זאת באה מבחי' מקיף העליון דהיינו בחי' סובב הכללי הנ\"ל שלמעלה מגדר משפיע ומקבל כו', וכאשר חו\"כ עומדים שם מוגבהים ומתרוממים כ\"כ במקום ומדרגה גבוה מכל עיקר מקור חוצבם במזלות שלהם למעלה בע\"ס דבי\"ע וגם בשרש שרשן בע\"ס דאצי' (עד",[["1303","361","<b>מבחי' ת\"ת דא\"א שנעשה כתר לאו\"א</b>: ראה ע\"ח שער מוחין דצלם רפ\"ה ורפ\"ז. שער דרושי הצלם דרוש ד' וה'. שער מיעוט הירח פ\"א."],["1304","362","<b>דמיכאל וגבריאל. . אין מכבי'</b>: במדב\"ר פי\"ב, ח. ראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שסג."]]],[1900420297,"בחי' מזלות דאו\"א ששם שרש הראשון לכל הנשמות שמיחוד או\"א וזו\"נ כידוע) שאינו אלא בבחי' או\"פ דקו\"ח שממנו מקור הראשון לאורות דאצי', ע\"כ מתבטלים גם מקור מציא' מזלות דחו\"כ שם לאי\"ן האמיתי דבחי' סובב הכללי ואז יוכלו להתאחד זע\"ז ולהוליד כו' (וזהו כי על כל כבוד דחו\"כ יש חופה והוא החופה א' לשניהם כא' דוקא ולא שיש לכל א' חופה בפ\"ע כי מעלין ומגביהי' אותם למקום הנעלה ממקור חוצבם כדי שיוכלו להיות ביחוד אח\"כ כו' (וז\"ש הכל תלוי במזל<sup data-n=\"1305\">363</sup> אפי' ס\"ת בהיכל שהוא יחוד או\"א היינו ג\"כ מאור א\"ס שבבחי' מקיף על שניהם יחד כו' וכידוע בכונות דיחוד או\"א שבתיבת ה' אלקינו שבק\"ש, וכך הוא עד רום המעלות בכל יחוד משפיע ומקבל גם לפני האצי' לכולם יש חופה החופפת בבחי' אור מקיף שמעלין לשם המשפיע ומקבל כו' וד\"ל).\n[מב] <b>וזהו</b> כיצד מרקדין לפני הכלה ולא אמרו כיצד רוקדין כו' וגם מ\"ש לפני הכלה ולא אמרו לפני החתן ולא אמרו למעלה אלא לפני כו'. דהנה מה שמבואר למעלה בענין החופה היינו רק בחי' עליי' וביטול במציאות דחו\"כ לאי\"ן הנעל\"ם שבחופה שהוא בבחי' סובב הכללי הנ\"ל, אך מה שיוכל לבא בהמשכה ממקום הנעלה הזה ליחוד דחו\"כ בבני חיי ומזוני כו' הוא ענין הריקוד הזה לפני הכלה, וזהו מרקדין כו' לשון מפעיל. ותחלה יש להבין גוף ענין הריקוד שהוא ברגל, דלכאורה אנו רואים עיקר התגלות השמחה בתוקף הוא בידים ולא ברגלים, דכאשר יתפעל לב האדם בשמחה יתירה שלא יכילנו כלי מוחו ולבו יספק בידי'. אך יש ב' מיני שמחות א' בבחי' מקיף דנר\"נ שבמוחא ולבא כו' (ונק' מקיף דחיה) והב' שמחה שבמקיף דיחידה שהיא ע\"ג הראש וגלגלתא שלא בא לגוף כלל היינו לנר\"נ שבמוח ולב כלל כו', וזהו ענין הריקוד שכאשר יתפעל בנקוד' דבחי' יחידה דנפשו העצמיות שזהו גם ביתר מכפי המקיף דנר\"נ לא יספיק הסיפוק בידיו שלא יכילנו גם הוא אז יכריחנו הריקוד ברגל והוא מה שיגביה הרגל שבהגבהה זו הוגבה הראש למעלה. והענין הוא דגם שזהו בחי' חיצוניות לבד להגביה הרגל, אבל שרשו הוא הגבהת המקיף שע\"ג הראש, שידוע דמקיף הראש הוא ערך הגובה של פישוט הידים למעלה הגבה מראשו וזהו ערך הדילוג ממש ברגל לא יוסיף ולא יגרע שהוא כערך אמה ואם יוסיף זהו למעלה ממדת המקיף שע\"ג הראש וכידוע בענין נשיאת כפים דכהנים<sup data-n=\"1306\">364</sup> כו', והנמשל מזה יובן למעלה דהדילוג ברגל שזהו לא לפי ערך ההדרגה דאו\"מ ופנימי היינו להגיע לבחי' המקיף דיחידה שנעלה ונבדל בערך לגמרי, והאות לזה הוא מה שאנו רואים דכל חדוה ועונג נפלא שלא יכיל המוח והלב יכילנו הריקוד ברגל שהוא הגורם הריקוד ברגל מפני שלא יכילנו כלי המוח והלב, וא\"כ ודאי שזהו מבחי' מקיף",[["1305","363","<b>הכל תלוי במזל</b>: שבת קנה, א."],["1306","364","<b>וכידוע בענין נשיאת כפים דכהנים</b>: ראה גם לעיל ד\"ה אשר ברא (הראשון). וש\"נ."]]],[1900420298,"דיחידה שלמעלה גם ממקיף דנר\"נ כו'. וז\"ש כיצד מרקדי\"ן ל' פועל יוצא להיות שההמשכה בריקוד זה אינו המשכה נגלית אלא המשכה נעלמת והיא מקור להמשכה נגלית. והענין הוא דהריקוד הוא חיצוני רק בבחי' נה\"י אבל שרשו מצד<sup data-n=\"1307\">365</sup>* יכילוהו גם המקיף דנר\"נ ולזאת נק' המשכה נעלמת, והוא מבחי' סובב הכללי שא\"א להמשיכו רק בבחי' חיצוני' דוקא כריקוד ברגל ולא בשום תענוג פנימי שבמקיף ופנימי שברצון ושכל כלל וד\"ל. וזהו מרקדין מפעיל הריקוד, דגם הריקוד שלמעלה מן הדעת צריך שיהי' נעשה ממקור א' המפעיל הריקוד בלתי בחירה כלל, וכמו בדוד שהי' מרקד מכרכר בכל עוז שלא בדרך בחירה כלל כאילו נעשה מעצמו, והוא ע\"י אור המקיף הכללי דסובב שהי' בחופה כנ\"ל וד\"ל.\n[מג] <b>ובזה</b> יובן ענין הכבוד שעושין לחו\"כ והעיקר לכלה שמגביהים ומרוממים אותה לבחי' מקיף הכללי כדי שיוכלו להתייחד ולהוליד נשמות כו', וכמו שמרקדין לפני הכלה היינו לפניה לכבודה ולנשאות אותה עי\"ז שזהו ביתר מכפי מעלתה בעצם, וכך למעלה מרקדין אנשים גדולים לפני הכלה עליונה שתהי' בחי' מקבל, ולא אמרו לפני החתן שהחתן א\"צ התרוממות כ\"כ כי הוא בחי' משפיע ושרשו במקיף דנר\"נ כו', אבל בחי' המקבל שיוכל לקבל ולהוליד כו' צריך שירוממוהו למקיף היותר עליון שהוא מקיף דיחידה שנעוץ סופן בתחלתן ולכך אמרו לפני הכלה דוקא וד\"ל.\n<b>והנה</b> בהתנשאות ורוממות זאת להכלה נחלקו ב\"ש וב\"ה אם כלה כמות שהיא כו', ויש להבין דברישא משמע דעיקר מחלוקתם כיצד מרקדין לבד דהיינו רק בגוף הריקוד ובסיפא משמע דעיקר מחלוקתם בשבח והלל שישבחו ויהללו לכלה זה או' כלה כו'. אך הענין הוא דהיינו הך ממש להיות דע\"י השבח וההילול מתרוממת הכלה בעצמותה ביתר מכפי מדתה בעצם והוא לבחי' המקיף דיחידה הנ\"ל, וזהו שרש המחלוקת באיכות אופן שיעור השבח וההילול כדי להמשיך המקיף שתוכל לקבל ולהוליד כו'. בש\"א כלה כמות שהיא למטה וכמות שהיא למעלה בשרשה לבד לא יוסיפו להלל אותה ביתר מכפי מדתה בעצם למעלה ולמטה בכדי שיהי' מכוון אופן ההעלאה דהילול שלמטה רק לכמות שהיא למעלה ויבא המקיף לשכון על אור וכלי שלם כפי שהוא, משא\"כ אם יהללוה ביתר מכפי המדה שלה כמו אם היא חגרת או סומא עכ\"ז יאמרו לה כלה נאה הרי יבא או\"מ לשכון על חסרון ופגם וע\"ד שקר שלא יכון<sup data-n=\"1308\">366</sup> שם כלל, ולבד מצד עצם החסרון ופגם שלא יוכל המקיף לשכון שם כידוע הנה השקר שלא אמרו האמת כמו שהוא זה רע ביותר. ובה\"א כלה נאה כו' שאין זה שקר כלל דנאה היא באמת למעלה כנ\"ל וגם למטה נתמלא",[["1307","365","<b>מצד</b>: תיבה אחת טושטשה כאן בהכת\"י, ולא ניתנה לקריאה."],["1308","366","<b>יכון</b>: כ\"ה בגוכי\"ק."]]],[1900420299,"וניתקן כל פגם כנ\"ל (ומ\"ש שקר החן<sup data-n=\"1309\">367</sup> והבל היופי כו' לזה כיונו ב\"ה שלא אמרו כלה נאה לבד שע\"ז יכול ליפול לומר שקר החן והיופי אך כשאומרים וחסודה שזהו אשה יראת ה' דוקא תתהלל ובזה תלו ב\"ה עיקר ההילו\"ל דחס\"ד ח\"ס דלים<sup data-n=\"1310\">368</sup> היינו אשה יראת ה', וכמו ברבקה שזה הי' האות אם תאמר שתה<sup data-n=\"1311\">369</sup> וגם לגמליך אשקה היא האשה<sup data-n=\"1312\">370</sup> * להיות ב\"ה שרשן מבחי' רב חסד (וכמ\"כ ב\"ש להיפך במדת הדין לרק<sup data-n=\"1313\">371</sup>ד לפני הכלה ל' כלה כמצות שהיא כמו ענין השם אורחותיו כו' שבזה דוקא מעוררים בחי' המקיף דיחידה כי שקר החן והיופי בתואר העבודה במוח ולב כו' רק* אה\"ר דוקא, ואמנם א\"א להוציא בה ההעלם כ\"א ע\"י מדה\"ד להשפיל א\"ע להיות נבזה בעיניו נמאס כו' שזהו מרה שחורה הטבעית ועצמית דנשמה האלקי' כידוע וד\"ל. ובה\"א שמעלת הנשמה כמות שהיא ביתר מעצם ההתקשרות להודות ולהלל ע\"כ אומרים כלה נאה וחסודה שניהם כאחד נאה ולא מצד עצמה, והוא להיותה חסוד\"ה אשה יראת ה' היא תתהל\"ל פי' תתהל\"ל ביתר מכמו שהוא מטעם הנ\"ל דנעוץ סופן כו' ואין להלל זה שיעור למעלה ולמטה כלל וכמ\"ש ישראל אשר ב\"ך אתפא\"ר<sup data-n=\"1314\">372</sup> כו' וד\"ל.",[["1309","367","<b>שקר החן</b>: משלי לא, ל."],["1310","368","<b>דחס\"ד ח\"ס דלים</b>: ראה אגה\"ק ס\"י [תניא קטו, ב]."],["1311","369","<b>אם תאמר שתה</b>: ע\"פ חיי\"ש כד, יד. מד."],["1312","370","<b>האשה</b>: תיבה אחת קרועה כאן בגליון הגוכי\"ק."],["1313","371","<b>רק</b>: תיבה אחת אינה ברורה כאן בגוכי\"ק."],["1314","372","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."]]],[1900420300,"<h3>להבין ענין שמחת חו\"כ הרה תקריב</h3>\n<b>להבין</b> ענין שמחת חתן וכלה<sup data-n=\"1315\">1</sup> יש להקדים פי' הפסוק כמו הרה תקריב ללדת<sup data-n=\"1316\">2</sup> תחיל תזעק בחבלי' כו'. הנה בזמן הגלות נק' כנ\"י הרה, והגאולה נמשל בבחי' לידה, וכמו בגלות מצרים דכתיב ואעבור עליך כו' ואומר לך בדמיך חיי כו', וגם לע\"ל בגאולה אחרונה נאמר במשיח אני היום ילדתיך וזהו הרינו חלנו<sup data-n=\"1317\">3</sup> כו', וכמו סמוך ללידה כאשר תקריב ללדת תחיל תזעק בחבלי' שנק' חבלי לידה כך הוא ענין חבלי לידה ברוחניות שהוא קודם ללידה דוקא והוא שנק' חבלי משיח כידוע וד\"ל. וביאור הענין יש להקדים תחלה ענין יחוד קודב\"ה ושכינתי' שזהו יחוד ב' שמות דהוי' אלקים, וכמו כי שמש ומגן ה' אלקים ששם אלקים מגן ומסתיר לשם הוי' ולע\"ל כתיב ונגלה כבוד הוי' (וכמאמר לע\"ל מוציא חמה מנרתקה<sup data-n=\"1318\">4</sup> כו'), וענין הסתר דשם הוי' בשם אלקים נמשל כמו בחי' עיבור הולד שמוסתר ונעלם בבטן כו', ולכך נק' כנ\"י בזמן הגלות בשם הרה, וז\"ש כמו הרה תקריב ללדת כו'. כי הנה ידוע שכל תכלית העבודה בתו\"מ ועבודה שבלב ומוח בתפלה אינו רק שיהי' בכל נפש מישראל בחי' גילוי אור דשם הוי' דוקא כמ\"ש כי אתה נרי הוי'<sup data-n=\"1319\">5</sup> כו', כי כל עיקר אור וחיות אלקי הפנימי' לנשמה האלקית הוא כאשר מאיר משם הוי' בגילוי ולא משם אלקים לפי שהנשמה שרשה במקור חוצבה הוא מפנימיות שם הוי' ולא משם אלקים המסתיר על שם הוי' (שנא' נר הוי' נשמת אדם אך המלאכים נק' בני האלקים דוקא כידוע), וז\"ש לך אמר לבי כו' את פניך הוי' אבקש ובכמה מקומות אמר כן כמו הללי נפשי את הוי' דוקא בה' תתהלל נפשי דרשו הוי' כו' אברכה את הוי'<sup data-n=\"1320\">6</sup> ברוך כבוד ה' כו', וכידוע שזהו בחי' ההמשכה דסובב כ\"ע שנק' שם הוי' הי' הוה ויהי' שלמעלה מבחי' זמן ומקום שבלתי בא עדיין בבחי' גילוי אור ושפע בשביל התהוות העולמות מאין ליש, כי התהוות העולמות מאי\"ן האלקי לבחי' יש נפרד היינו דוקא מבחי' שם אלקים המצמצם ומסתיר לעצם אור האצי' כשמש במגן ונרתק כנ\"ל, ולזאת כל עיקר הברכות באמרו ברוך אתה הוי' היינו שיבא ויומשך מלמעלה אור דהוי' דאצי' בלתי הסתר דשם אלקים למטה בתוך כל עלמין שנבראו ע\"י צמצום דשם אלקים להיות מתגלה למטה בצמצום דשם אלקים כמו שהוא למעלה באצי' ממש, וכמו לע\"ל",[["1315","1","<b>לה\"ע שמחת חו\"כ</b>: מיוסד על ד\"ה זה בתו\"א שמות (בהוספות) קו, א ואילך [שם הנחת אדהאמ\"צ ממאמר אדה\"ז, עם הגהות מאדמו\"ר הצ\"צ]. ונוסח נוסף בסה\"מ תקס\"ג ח\"א ע' קב [הנחת הר\"מ בן אדה\"ז]. ובשינויים והגהות באוה\"ת שמות (כרך ז') ע' ב'תקטז. ותוכן קצר מהמאמר [וכמה הגהות] באוה\"ת על סידור [דרושי חתונה] ע' רלה."],["1316","2","<b>כמו הרה תקריב ללדת</b>: ישעי' כו, יז: כמו הרה תקריב ללדת תחיל תזעק בחבלי' כן היינו מפניך ה'."],["1317","3","<b>ואעבור עליך. . אני היום ילדתיך. . הרינו חלנו</b>: יחזקאל טז, ו. תהלים ב, ז. ישעי' שם יח: הרינו חלנו כמו ילדנו גו'. וראה גם תו\"א וארא נז, ד. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רעא. ועוד."],["1318","4","<b>כי שמש ומגן. . ונגלה כבוד ה'. . לע\"ל מוציא חמה מנרתקה</b>: תהלים פד, יב. ישעי' מ, ה. נדרים ח, ב."],["1319","5","<b>כי אתה נרי ה'. . נר ה' נשמת אדם</b>: שמואל-ב כב, כט. משלי כ, כז."],["1320","6","<b>לך אמר לבי. . הללי נפשי. . בה' תתהלל. . דרשו ה'. . אברכה את ה'</b>: תהלים כז, ח. קמו, א. לד, ג. קה, ד. לד, ב."]]],[1900420301,"שנאמר ונגלה כבוד ה' וראו כל בשר כו' וכתיב כי כולם ידעו<sup data-n=\"1321\">7</sup> אותי ממש כו', ולא כעכשיו שמצמצם אור האלקי בכל עולם כפי מדת הצמצום דבחי' שם אלקים שהן ק\"ך צירופים עד שבעולם העשי' מוסתר ביותר כמ\"ש אתה אל מסתתר כו', ומאחר שא' וראו כל בשר הרי יהי' בחי' הגילוי דהוי' למטה כמו למעלה ממש כו', שהרי א' ובאו במערות צורים<sup data-n=\"1322\">8</sup> מפני פחד הוי' וכל פחד אינו אלא כשהוא מקרוב דוקא בבחי' ראי' חושיית כו' וכמ\"ש כולם ידעו אותי בידיעה והכרה חושיי', ולא כמו עתה שמרחוק מאד ה' נראה גם בנשמות הגבוהות שנקראים עובדי הוי' ממש בהתפעלות אהבה ויראה שכליים בעבודה תמה שבמוח ולב, כי עיקר ההתבוננות וההשגה אלקית שבנשמות לא יגיע כלל בהשגת המהות דהיינו לבחי' הוי' דאצי' רק השגת מציאות הוא בחי' התפשטות אור האלקי שמוגבל בעולמות להוות מאי\"ן לי\"ש שנקרא כח הפועל האלקי בנפעל לבד שזהו ענין בשכמל\"ו כידוע ובהשגה זו ידבקו נפשם להכיר בוראם ויתפעלו באה\"ר כו', אבל בחי' שם הוי' שמובדל ומרומם לבדו ומתנשא מימות עולם לגמרי מרחוק נראה להם לפרקים ועיתים רחוקים כמו בכל שבת ויו\"ט שנק' מועדי הוי' שהוא העת שמתגלה שם הוי' באלקים למעלה ע\"כ בא גילוי קצת מזה גם לנשמות בג\"ע שמדי חדש ושבת יבאו להשתחוות לפני הוי' וגם בנשמות שבגופים ליחידי סגולה בשעת הכושר לבד כו' וד\"ל.\n[ב] <b>ואע\"פ</b> שאין איש מישראל שלא קיים מצוה א' ובכל מעשה המצוה יש יחוד עליון דהוי' באלקים כידוע בענין יחוד קודב\"ה ושכינתי' שאו' על כל מעשה המצוה, וכן אומרים בכל יום ברוך כבוד ה' ובפרט כל הברכות שאו' בכל יום ברוך אתה הוי' שיבא בגילוי העצמות למטה כנ\"ל, ולפ\"ז ראוי הי' שע\"י קיום מצו' בכל יום וע\"י הברכות שיהי' בא בגילוי למטה כל בחי' יחוד עליון דקודב\"ה שהוא שם הוי' באלקים שנק' שכינתי' ששוכן בתחתונים כידוע ולמה זה א' לע\"ל דוקא ונגלה כבוד הוי' ולא עתה וכמא' גלה כבוד מלכותך כו' ובכן תן פחדך כו' שזהו לע\"ל שיקוה לראות בתפארת עוזו ותמלוך אתה ה' לבדך כו'. הנה הענין הוא דשניהם אמת, דודאי עיקר הגילוי דשם הוי' למטה מטה כמו למעלה בראי' חושיי' בהשגת כל אדם כמ\"ש וראו כל בשר כו' וכולם ידעו אותי ממש כנ\"ל (כהתגלות אור הנבואה בנביאים בגופם ויותר מזה שהנבואה הי' בלתי טבעית כי הי' הגוף בטל מכל חושים הגשמיים כי לא יכיל הגשם לקבל האור האלקי ולע\"ל יזדככו הגופים ויכילו אור האלקי' כמו שהן שנק' כל בשר כו' וד\"ל), היינו דוקא לע\"ל אבל היא גופא מה שיהי' גילוי הוי' באלקים לע\"ל אינו בא אלא מחמת הקריאה שהיו קוראים וממשיכים למעלה יחוד דשם הוי' באלקים ע\"י המצות מעשיות דעכשיו ובכל הברכות שאו' ברוך אתה הוי' כו', ואע\"פ שאין גילוי יחוד עליון זה בא למטה",[["1321","7","<b>כי כולם ידעו</b>: ירמי' לא, לג."],["1322","8","<b>אתה א-ל מסתתר. . ובאו במערות צורים</b>: ישעי' מה, טו. ב, יט."]]],[1900420302,"ממש רק שמתעורר למעלה עכ\"פ ונעשה יח\"ע זה למעלה רק שצועקין ומבקשין שיתגלה למטה ג\"כ כמו למעלה, הנה זאת הבקשה וההתעוררות למעלה גורם בחי' ירידת גילוי אור שם הוי' למטה לע\"ל שיתגלה לעין כל בכל בשר כנ\"ל, ואם לא הקריאה וההתעוררות דכנ\"י ביח\"ע שעושין למעלה עתה לא הי' בא לע\"ל גילוי דהוי' למטה ממש והא בהא תליא ממש וע\"כ שניהם אמת וד\"ל (וכמ\"ש בע\"ח דכל יח\"ע דמצות הוא עתה להוסיף אור באצי'<sup data-n=\"1323\">9</sup> לבד ולע\"ל יתגלה האור למטה כו').\n[ג] <b>ובכל</b> זה יובן ענין מה שכנ\"י נק' בזמן הגלות בשם הרה כמ\"ש כמו הרה תקריב ללדת כו' כמו עד\"מ הולד שמוסתר בעיבור בבטן כו' ואח\"כ יוצא לגילוי במהות בפ\"ע כו' כך ע\"ד משל ודוגמא כל עיקר בחי' גילוי הוי' לע\"ל במשיח דכתיב בי' ונחה עליו רוח ה'<sup data-n=\"1324\">10</sup> כו' וכל בשר יראו כנ\"ל נק' למשל הולד הנולד כו' שבא בגילוי מהות שלו בלתי מוסתר ונעלם כלל וכמ\"ש אני היום ילדתיך כו', אך כל זמן הגלות נמשל לבחי' עיבור שהולד מוסתר כו' היינו ששם הוי' מוסתר מאד ומצומצם בשם אלקים כשמש ומגן המסתירו כו' והיינו שמוסתר בבחי' קטנות מאד, והוא כמו במעשה המצות ועבודה שבלב בתפלה שמרחוק ה' נראה להם כנ\"ל הוא שנק' בחי' עיבור וקטנות כי לא נגלה בנשמתם ממהות ועצמות אור הוי' רק כמו שהוא בא בבחי' הסתר בשם אלקים כו', אבל לע\"ל יוציא חמה מנרתקה ויתגלה כבוד ה' כמו שהוא בלי הסתר כנ\"ל נמשל בבחי' לידה והוא מ\"ש אני היום ילדתי\"ך כו' וד\"ל.\n<b>אך</b> הנה כל מה שישראל קוראים וממשיכים לשם הוי' ועושין התעוררות יח\"ע במצות וברכות כל זמן הגלות שהוא בבחי' עיבור דקטנות גורמים בזה דוקא קירוב זמן הלידה דגאולת משיח שאז יתגלה שם הוי' לכל כנ\"ל. וזהו כמו הרה תקריב ללדת כו' דכנ\"י בגלות נק' הר\"ה (כמו שא' במשנה אע\"פ שאתה מתמלא עליהם עבר\"ה כאשה עובר\"ה יהיו כל צרכיהם לפניך וכמ\"ש ביאור זה במ\"א<sup data-n=\"1325\">11</sup>), ותקריב ללד\"ת הוא קרוב וסמוך לזמן הגאולה שנק' לידה כנ\"ל שאז תחיל תזעק בחבלי' כו' כן היינו מפניך הוי' פי' כדי שנהי' מפניך הוי' שיתגלה פנימי' דשם הוי' כמו שהוא למעלה באצי' למטה מטה ג\"כ שזהו בחי' הלידה בגאולה דלע\"ל כו', היינו תחלה הרינו חלנו בבחי' עיבור וקטנות שהוא בחי' הסתר וצמצום גדול דהוי' באלקים שבכל עבודה דכנ\"י בכל ימי הגלות וכך הם המשך הדברים עד שנהי' מפני\"ך הוי' בימות המשיח היינו כמו",[["1323","9","<b>בע\"ח. . להוסיף אור באצי'</b>: ע\"ח שער מ\"ן ומ\"ד (של\"ט) דרוש י\"א כלל טז. וראה לעיל ח\"א ע' קנו. וש\"נ. ולעיל סוד\"ה שמח תשמח (השלישי)."],["1324","10","<b>ונחה עליו רוח ה'</b>: ישעי' יא, ב."],["1325","11","<b>במשנה אע\"פ שאתה מתמלא. . ביאור זה במ\"א</b>: ברכות כט, ב. ראה תו\"ח שמות צו, ב. קס, ב."]]],[1900420303,"הרה תקריב ללדת בזמן הגלות דהא בהא תליא כנ\"ל (וזהו עד יעבו\"ר עמך הוי' יעבו\"ר אותיות עיבו\"ר כמ\"ש במ\"א<sup data-n=\"1326\">12</sup>).\n[ד] <b>והנה</b> ידוע דעיקר זמן חבלי לידה אינו אלא בסמוך וקרוב ליום הלידה דוקא שזהו מצד שקרוב זמן הלידה ע\"כ מתעוררים חבלי לידה שהן המקרבים סיבת הלידה כידוע שאם לא החבלי לידה אין כח ללידה כלל, וזהו כמו הרה תקריב ללדת תקריב בסמוך לזמן הלידה אז דוקא תחיל תזעק בחבלי' ולא קודם לזמן הלידה הרבה ימים ומכ\"ש באמצע חדשי העיבור אין חבלים כלל שתזעק כו' רק צער העיבור לבד מצד עצמו כו' כידוע. והנמשל מזה יובן ג\"כ בבחי' חבלי לידה הרוחניות למעלה בכנ\"י שנק' הרה בזמן הגלות. דהנה ידוע בענין החבלי לידה שהן רוחות הבטן המתעוררים כחבלים ממש שמושכים את הולד למעלה בל יצא לחוץ ומונעים את הלידה כו', אך זה עצמו היינו עיקר הסיבה אל קירוב הלידה דכל שמתעוררים חבלים אלו לעכב הולד חוזר וניעור תיכף בכח גדול לצאת במהירות גדולה ביותר, כמו דבר שמעכבים אותו תחלה יותר יצא בכח גדול אח\"כ, כעיכוב המים בעבים או בכיסוי שמעכב המים דכשיתחזק ההילוך אח\"כ ביותר, וכמו הקלע באבן כל שמונעים בדוחק יותר יותר יצא בכח כו', וכך הוא עיקר ענין החבלים למנוע ולעכב הולד כדי שיציאתו מן הדוחק ועיכוב הזה יהי' בכח גדול עד שיפתח הרחם מיד מחמת ריבוי כח גדול בדחיקתו ויציאתו כנ\"ל. והדוגמא מזה יובן בענין חבלי לידה בזמן הגלות שזהו דוקא קרוב לזמן הגאולה ולא קודם לכן הרבה שאז ימצאו מונעים רבים שמעכבים ומונעים לבחי' גילוי זה דשם הוי' ונקראים חבלי משיח כו' שהוא גודל עוצם הצרות ודוחק הגלות ועוני הדעת מכל צד ברוחניות וגשמיות עד שיוסתר יותר אור האלקי בכל א' בתכלית כו' עד שתחיל תזעק בחבלי', והזעקה הוא מחמת כאב גדול שיכאב ביותר לעוצם המניעה מכל צד עד שתקצר הרוח מאד, וכמ\"ש ויצעקו<sup data-n=\"1327\">13</sup> בנ\"י כו' ותעל שוועתם כו' כקול הצעקה דחבלי לידה ממש, וזהו כי באו בנים כו' וכח אין ללידה מפני המונעים, אך היא גופא גורם קירוב זמן הלידה כנ\"ל בחבלי לידה שמצד עוצם הכאב בעיכוב הולד יגרום היציאה בכח ללידה כו' (כידוע), וז\"ש תחיל תזעק בחבלי' והוא הגורם עיקר כח הלידה, משא\"כ כשאין חבלים כו' שזהו בלי מונעים ומעכבים אין כח לידה כלל וד\"ל, וז\"ש כן הרינו חלנו כו' כשקרוב זמן הגאולה להיות מפניך הוי' כנ\"ל אבל קודם זמן הגאולה הרבה אין חבלי לידה כלל רק צער העיבור לבד כנ\"ל. והענין הוא כמו אשה כי תזריע שבעיבור יש גידול לאיברי הולד כל זמן העיבור ע\"י החום הטבעי שבא בזרע האשה לגדל",[["1326","12","<b>עד יעבור. . אותיות עיבור כמ\"ש במ\"א</b>: בשלח טו, טז. ראה תו\"ח שם. שער האמונה פס\"ו. סידור רצג, ב."],["1327","13","<b>ויצעקו. . ותעל שועתם. . כי באו בנים</b>: בשלח יד, יו\"ד. ועוד. שמות ב, כג. מלכים-ב יט, ג: כי באו בנים עד משבר וכח אין ללידה."]]],[1900420304,"הבשר וגידים שנק' אוד\"ם שממנו בשר<sup data-n=\"1328\">14</sup> כו', ולמעלה זהו הנק' בחי' מ\"ן דנוק' שמגדל הולד כו', ובכנ\"י הוא בחי' רשפי אש התשוקה האלקית בהשגת כל א' בבחי' סובב כו' שהוא שם הוי' מרחוק בקטנות שזהו בחי' עיבור כנ\"ל, אך ע\"י התשוקה לגילוי שם הוי' כמו כלתה נפשי<sup data-n=\"1329\">15</sup> כו' בזה נגדל האור דשם הוי' בכל נשמה כמשל גידול הולד בבטן כו' ובזה אין חבלים שזהו מניעה ועיכוב כלל כי קרוב ה' כו', רק בהגיע עיקר הגילוי דשם הוי' לע\"ל בכללות נש\"י שנק' לידה אזי ימצאו בחי' חבלי לידה כנ\"ל, אבל צער העיבור יש והוא בחי' התשוקה מרחוק כו' בצמצום וכווץ גדול שמיצר ע\"ז מאד כמ\"ש הרינ\"ו חלנ\"ו כו' וד\"ל.\n[ה] <b>והנה</b> לאחר בחי' לידה הנ\"ל הוא זמן בחי' היניקה מאחר שאמר במשל עיבור ולידה כמו הרה תקריב ללדת כנ\"ל א\"כ יש גם בחי' יניקה ומוחין דגדלות שאח\"כ כידוע. וביאור הענין הנה מבואר למעלה בבחי' עיבור שהוא בבחי' הקטנות מאד, ואע\"פ שגם הוא בא בבחי' הגדלה בט' חדשים וגידול זה בא מן המאכלים שאמו אוכלת כו' ונהפך בשינוי המהות להיות מזון לולד לגדילו באיבריו בט' חדשים באופן שאין גידול הקטן לפי שניו מתגדל כ\"כ במהירות בט' חדשים ולא בב' וג' שנים, אך הנה זהו רק הגדלת החומר בלבד והוא גידול האיברים לבד ע\"י הדם שבא בבחי' שינוי המהות בבטן אמו בחום הטבעי כנ\"ל (שנק' ה\"ג דאודם שממנו בשר כנ\"ל), אבל בחי' הגדלת הצורה בחומר היינו כללות ענין היניקה בחלב לולד אחר שנולד, והאות ע\"ז הוא מה שהחלב נעשה מחמת עיכור הדם אחר יציאת פסולת הדמי' בלידה אז מתהפך בחי' החיות הנפשיות שבדם האיברים למיץ חלב ועולה למעלה בכלי המוח ומשם יורד בהגשמה למקום בינה שבלב שהן הדדים שיונק מהם הולד, ועיקר ענין יניקה זו הוא להגדיל הצורה הנפשית בחומר האיברים, והגם שנקרא קטנות הצורה עדיין לגבי הגדלות המוחין שאחר היניקה ב' שנים אבל מ\"מ גידול זה למעלה הרבה מגידול החומר של האיברים בעיבור ט' חדשים כו' וד\"ל (וע\"כ עיכוב הגידול הזה הוא עכ\"פ בב' שנים יותר מט' חדשים דעיבור, אמנם הגידול הזה בב' שנים הוא מתגדל יותר מגידול הט' חדשים בעיבור לפי ערך רק שמתעכב זמנו יותר (וכן הוא ענין גידול המוחין שאחר היניקה מתעכב זמנו יותר והוא מב' שנים עד בן ה' אבל מתגדל יותר, וכן מבן ה' עד",[["1328","14","<b>הבשר וגידים שנק' אודם שממנו בשר</b>: ע\"פ נדה לא, א. ושם בשינוי: אביו מזריע הלובן שממנו עצמות וגידים כו' אמו מזרעת אודם שממנו עור ובשר דם ושערות. אמנם כהלשון כאן מובא בכ\"מ, ראה לעיל ח\"א ע' קעז וע' רפה [ונסמן ע\"ז באורך בהמ\"מ בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'רעח]. וראה ע\"ח שער פנימיות וחיצוניות [ש\"מ] דרוש י\"ב: הגידין שזכרו רז\"ל אינן אותן הלבנים כו' רק הגידין כו' שבהם מתפשט הדם או חיות הלב הדופקים. ועוד ע\"ד כמה סוגי גידים בביאוה\"ז שופטים קכב, א. [ובהנסמן עוד במאמרי אדהאמ\"צ שם]."],["1329","15","<b>כלתה נפשי</b>: תהלים פד, ג."]]],[1900420305,"בן י\"ג מתגדל יותר והעיכוב יותר, ומבן י\"ג עד עשרים נשלם קומתו ולא יגדל עוד, והגידול הנוסף בזה הזמן אינו בערך הגידול שבקטנותו מה' שנים לי' וי\"ג, וגם גידול זה אינו בערך הגידול במהירות דב' שנים דיניקה וד\"ל).\n[ו] <b>וביאור</b> ענין הגדלת הצורה בחומר הוא מה שנעשה בחי' התפשטות אור התענוג הרוחניות בדם הוא הנפש ע\"י החלב דוקא רק שבא בהגשמה, והיינו סיבת התפשטות האיברים לאורך ורוחב יותר בימי היניקה כי בחלב הגשמי יש מבחי' התענוג הגשמי שנתגשם בחלב בירידתו וכל תענוג גשמי שבא בהגשמה טבעו לגדל ולהתפשט כבשורה טובה תדשן עצם וכמו שמנת עבית<sup data-n=\"1330\">16</sup> כו' כך התפשטות עובי האיברים בא מן התענוג הגשמי שבחלב הגשמי להיות לו למזון להחיות גופו כמזון הלחם ממש, ובזה תגד\"ל הנפ\"ש בבחי' צורה הרוחניות שבה מעט מעט בב' שנים אלה עד שנעשה מוכן אח\"כ לקבל צורת אור השכל במדות שנקרא גידול המוחין ובלעדי ימי היניקה לא הי' צורת הנפש מוכן לזה כלל, כי הנה אנו רואים שאחר היניקה מיד מתחיל לדבר מעט מעט בהשגת והבנת ענין דבר מה הרי יש בו דעת קצת וכמו שיודע לקרות אבא ואימא מצד הכרת הדעת שלא הי' בו קודם שיטעום טעם דגן דוקא, וגם מדותיו הטבעיי' מתחיל להאיר בהם מקצת מאור השכל והדעת היינו שיאהוב הדבר הטוב שיבחור בו מצד הכרתו בדעתו וימאס בדבר הרע שיכיר הרע עפ\"י קצת דעת ושכל עכ\"פ הגם שהוא בבחי' הקטנות עדיין אבל יגדיל אור השכל והדעת במדותיו וטבע גופו מעט מעט במשך זמן שבין היניקה עד היותו בן ה' ווי\"ו שיהי' לו דעת במדות למעלה מכפי טבעם לאהוב השנאוי עפ\"י טבעו אם צריך לו ולשנוא האהוב אם יכיר בדעתו שצריך שיתרחק הימנו כו', וזהו הפעוטות מקחן מקח<sup data-n=\"1331\">17</sup> שעפ\"י דעת הן ולאו שלו עד שיגדל שכלו יותר בהיותו בן י\"ג שנה שנשלם גידול כל הדעת ששייך למדותיו עכ\"פ ונקרא זה גידול המוחין בכלל (אך זהו גידול ראשון דאימא ומי\"ג עד עשרים מתחיל גדלות שני דאבא כמ\"ש במ\"א ע\"פ מרא\"ש צור\"י'<sup data-n=\"1332\">18</sup> כו'). אך כל בחי' הכנת צורה זאת הרוחניות דמוחין במדות הטבעיים דבהמה וכיודע לקרות בדיבור בדעת או\"א כו' היינו מחמת ימי היניקה דחלב שנתגשם בו התענוג שבמוח וירד אל מקום בינה דוקא שבלב בשדי אמו שיונק אדם שם שהוכן בזה בחי' חומר רוחני לצורה הרוחניות דמוחין שיהי' בבחי' צורת אדם נבדל מן הבהמה רק שהוא אדם קטן והולך וגדל בשכלו ומדותיו כנ\"ל, ולא",[["1330","16","<b>כבשורה טובה תדשן עצם. . שמנת עבית</b>: ע\"פ משלי טו, ל. וגיטין נו, ב. האזינו לב, טו. וראה לעיל ח\"א ע' מג."],["1331","17","<b>הפעוטות מקחן מקח</b>: גיטין נט, א. ועוד. וראה גם סה\"מ תקס\"ח ע' שצב [ע\"פ ע\"ח שער הכללים פ\"ח. שער דרושי הצלם דרוש ג]. ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תקא. נ\"ך ע' תקיט. אמרי בינה ח\"ג קי, ג ואילך. ולהלן קרוב לסוף המאמר."],["1332","18","<b>במ\"א ע\"פ מראש צורי'</b>: ראה גם להלן סוף אות ח'. אמ\"ב ח\"ג קי, רע\"ד."]]],[1900420306,"מצד בינה הרוחנית שבלב כמו בהשגת השכל שבלב שנקרא בינה לבא<sup data-n=\"1333\">19</sup> הלב מבין כו' אלא בינה הגשמית שבלב שנתגשם בה אור התענוג שבמוחין כנ\"ל בחלב זה הוא העושה הכנה זאת בהעלם גדול, והוא ענין התפשטות אורך ורוחב באיברים בהכנה דחומר רוחניות שיוכל לקבל צורת המוחין דאדם מיד אחר היניקה (וזהו שמתגדל ביניקה במהירות יותר מגידול המוחין דאח\"כ להיותו גידול מוחין דקטנות עדיין שנקרא חומר לגבי צורה דמוחין דגדלות אדם שאח\"כ כמו שגידול עיבור דקטנות ביותר כנ\"ל מתגדל במהירות יותר מגידול היניקה מפני שבעיבור אין הגידול רק בחומר לבד כנ\"ל וד\"ל).\n[ז] <b>ויובן</b> כל ג' אלה דעיבור ויניקה ומוחין בבחי' הרוחניות דנשמת אדם בפרט ומזה יובן בנש\"י בכלל. דהנה מבואר למעלה דבחי' עיבור דקטנות ביותר היינו שמרחוק מאד בקטנות נראה ונגלה בנפשו האלקית אור דהוי' בצמצום דבחי' הקטנות מאד, והיינו כולד גשמי שראשו מקופל ומונח בין ברכיו בעיבור והוא בחי' תלת גו תלת<sup data-n=\"1334\">20</sup> כו' כידוע. והענין הוא דבחי' אוי\"ר בחומר טבעיות באלקות הוא העיקר בו ואשר נראה בו התפעלות מדות ושכל בשם הוי' הוא בא בהעלם אחר העלם כראשו שמונח בין ברכיו כו', אך בחי' הגדלת החומר דאוי\"ר אלקי' טבעיים מתגדל דוקא בט' חדשים כנ\"ל והיינו כמו כל זמן הגלות שנק' עיבור כנ\"ל כך בכל נשמה בפרט כאשר הוא בגלות בטרדת עומק המוח והלב בדאגת פרנסה עד שתקצר רוחו מאד, וכמו ולא שמעו<sup data-n=\"1335\">21</sup> מקוצר רוח כו' בגלות מצרים קוצר רוח אדם זה היינו ע\"י בחי' ההסתר והעלם דאור ה' שמאיר בנשמתו ורוחו עד שתקצר רוחו רק בהעלם דאוי\"ר טבעיים לבד אבל מתגדלים מעט מעט ונשלם הגידול דחומר אוי\"ר טבעיים לסור מרע ולעשות טוב כטבע הבהמה במדותי' ולא יכיר אבי\"ו ואמ\"ו כלל בהשגה דהוי' רק בהעלם כנ\"ל שאוכל מה כו', עד שנולד נעשה ברי' בפ\"ע והיינו שנגלה בנפשו האלקית בבחי' גילוי דאור ה' באלקים בבחי' דו\"ר שכליים בהשגה, אך גם הוא בא בבחי' ההגשמה עדיין והיינו בחי' החלב הנ\"ל שזהו בחי' התענוג האלקי שבא במוחין שבמדות בהגשמה, והוא הנקרא בינה שבלב דאימא דבחי' אם הבנים היינו בחי' ההתבוננות וההשג' בשם הוי' דוקא אך לא ירד האור הזה ברוחניות ההשגה שבלב דבינה שנקראת אימא רק ירד בהגשמה, והוא ענין עונג אלקי הנרגש באוי\"ר שכליים כשהוא בבחי' הקטנות עדיין היינו בלי השגה שכליים דאלקות בבחי' התפשטות, וזהו כמו תינוק הנולד שיפקחו עיניו ואינו רואה כלום ואזנו שומעים ואינו שומע כלום כו' רק שבימי היניקה נגדלים חוש הראי' ושמיעה שיהי' חומר מוכן לקבל ראי'",[["1333","19","<b>בינה לבא ובה הלב מבין</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["1334","20","<b>שראשו מקופל. . תלת גו תלת</b>: נדה ל, ב. ראה גם תו\"ח שמות צו, ב ואילך. קס, א ואילך. ביאוה\"ז קג, ב ואילך. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תצג ואילך. ובכ\"מ."],["1335","21","<b>ולא שמעו</b>: וארא ו, ט."]]],[1900420307,"ושמיעה דחו\"ב במדות הטבעיים אחר תשלום היניקה כנ\"ל, כך ענין בחי' מוחין דיניקה שנק' הגדלת החומר דצורה השכליים שאח\"כ אמנם גידול חומר המדות דאוי\"ר שכליים מתגדל מעט מעט בימי היניקה כמו שמתגדל צור' הנפשיות בחומר הולד שיהי' בצורת אד\"ם ממש אח\"כ כנ\"ל וד\"ל, והיינו מה שאנו רואים שיתענג על ה' במעט התבוננות כשהיא בהגשמה מלובש במשלים ושכל אנושי, אך עונג שבא בהגשמת השכל מגדל בחי' צו\"ר' אדם שיהי' מכיר לבוראו כתינוק שיודע לקרות אבא בקצת דעת כו' וזהו גידול המוחין שאחר היניקה עד שיגדל בדעת שלימה וכמ\"ש כולם ידעו אותי ממש מקטנם כו', וכל זה הגידול דמוחין דאדם מקטנות לגדלות המוחין אינו רק מחמת גידול דחלב בימי היניקה כנ\"ל (וזהו שמתעכב ב' שנים זהו הוראה על היותו גידול רוחני יותר וגידול המוחין מתעכב יותר להיותו גידול רוחני יותר, וכן יובן בנשמה האלקית שנקרא נער בהיותו בהיותו בן ו' שנים שאין בה רק אוי\"ר בדעת ומוחין דקטנות בצמצום גדול והולך וגדל במוחין עד ע' שנה שקנה חכמ\"ה, וכל זה בא רק לפי ערך הכנת חומר גשמי בעיבור והכנת חומר רוחני דיניק' דוקא שאין הצורה הפנימית באה רק לפי אופן הכנת חומר הגשמי והחומר הרוחני (והעיקר הוא גידול חומר הגשמי בעיבור וכמאמר שמלמדין אותו כל התורה שישיג בהיותו בן ע' כו' וכן א' בדמי\"ך חי\"י<sup data-n=\"1336\">22</sup> דוקא וד\"ל).\n[ח] <b>והנה</b> מעתה יובן ג\"כ בבחי' נשמה הכללית דכנ\"י, דהנה כתיב בשוב ה' שיבת ציון היינו כחולמים כו' אז יאמרו בגוים הגדיל הוי' לעשות עם אלה כו'. דהנה לאחר שישוב ה' לכנ\"י בימות המשיח יכירו אז שהי' כל עבודתם בתו\"מ באוי\"ר כו' כל זמן הגלות שנמשל לבחי' עיבור דקטנות מאד שזהו הי' הכל כמו החלומ\"ו' בשעת השינה שהגלות נק' שינה כעורה למה תישן<sup data-n=\"1337\">23</sup> ה' כו', והיינו בחי' מיעוט והעלם אור הגילוי דהוי' ביח\"ע דמצוה הנעשית בגשמיות בהבדלה שבין טו\"ר בפ\"מ שזהו רק מחמת אוי\"ר טבעיים כמו ע\"י האמונה לבד שמרחוק ה' נראה כו' רק שמאמין באמונה פשוטה, ואמנם יש בזה אוי\"ר בלתי יעשה רע מצד היראה ויעשה טוב מצד האהבה וכמו טבע היא ממש בנפשותינו בכאו\"א מישראל כו', אך מה שהיינו בגלות שהוא הסתר אור הוי' כחולמ\"י' לבד הוא שבא בגילוי אור הדעת בשם הוי' בימהמ\"ש שנאמר ומלאה הארץ דיעה<sup data-n=\"1338\">24</sup> את הוי' ממש כו'. וז\"ש הגדיל הוי' לעשות עם אלה שיהי' בחי' גידול דשם הוי' בכללות נש\"י שנק' אל\"ה (כשהי' בבחי' עיבור תלת גו תלת בזמן הגלות כו'), והוא מה שיתגדל ויתקדש שם הוי' בפי כל וגדול",[["1336","22","<b>שמלמדין אותו כל התורה. . בדמיך חיי</b>: נדה שם. יחזקאל טז, ו. וראה גם ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תקיד וע' תקיח."],["1337","23","<b>בשוב ה'. . אז יאמרו. . עורה למה תישן</b>: תהלים קכו, א-ב. מד, כד."],["1338","24","<b>ומלאה הארץ דיעה</b>: ע\"פ ישעי' יא, ט [ושם: כי מלאה. אבל בכ\"מ מובא ומלאה — ראה לעיל ח\"א ע' קנו, ובהמ\"מ שם]."]]],[1900420308,"ומהולל מאד בכל השגה והשגה אלקית בכאו\"א שלא בהסתר והעלם דלבוש גס דבחי' נוג\"ה כלל וכמ\"ש ונגלה כבוד הוי' וראו כל בשר כנ\"ל (כנשמות דעכשיו בג\"ע וכה\"ג או כמו שהי' באדה\"ר קודם החטא בעה\"ד שגם גופו לא הסתיר לו כלל וכאבו' שהי' בחי' מרכבה תמיד כו'), וגידול שם הוי' בנש\"י יהי' במהירות כערך גידול ב' שנים דיניקה כנ\"ל, והיינו בחי' גילוי אור העונג האלקי כמו שהוא למעלה בבחי' בינה דמל' דאצי' אך שירד בהגשמה לפי אופן הלבוש דנשמות בהשגותיהם שזהו כמו יניקת החלב במקום בינה שבלב כנ\"ל, והוא כמו בחי' אוי\"ר שכליים עכשיו שבא העונג אלקי בהגשמת שכל והתבוננות דשם הוי' בשכל אנושי, ואמנם בחי' הדעת והשגה בשם הוי' אז יהי' בדעת הרוחני אור האלקי כמו שהוא למעלה וכמו שהי' הנשמה אלקית בלא גוף כלל כך יהי' אור הדעת בעודנה בלבוש הגופים ג\"כ לפי שעה\"ד טו\"ר יבורר ויזדככו הגופים כמו שהי' קודם החטא דעה\"ד טו\"ר, וזהו אד\"ם אד\"ם דו\"ד משי\"ח<sup data-n=\"1339\">25</sup> כו', וזהו וגב\"ה מא\"ד שאע\"פ שתחלת הגילוי דשם הוי' בכנ\"י בביאת משיח יהי' בבחי' הקטנות כלידת הולד שנפקחו עיניו כו' כנ\"ל וכמ\"ש אני היום ילדתי\"ך, אבל יגד\"ל שם הו\"י' וכולם ידעו אותו כו' כמשל הגדלה דימי היניקה שהוא גידול הצורה בחומר כו' וד\"ל. אך כל זה רק בחי' הכנה דצורה האלקית בנש\"י שנק' גם זה בשם קטנות לגבי הגידול דמוחין אח\"כ כנ\"ל, וזהו ישכי\"ל עבד\"י תחלה ואח\"כ<sup data-n=\"1340\">26</sup>* עד וגב\"ה מא\"ד שזהו גידול המוחין דאד\"ם האלק\"י בבחי' גדלות המוחין דאדם כשיגדל מאד (וזה הגידול יתעכב יותר להיותו גידול רוחני יותר כנ\"ל, והיינו בתח\"ה שלפני עוה\"ב שהוא באלף הז' שנשמות בגופים לא יהיו מאב ואם כלל אלא ונח\"י' לפני\"ו ממש כו', וכל עבודה בתו\"מ האלקי' שבימהמ\"ש לא יהי' רק ביניקת הולד שנעשה מוכן לקבל צורה דאד\"ם בגדל\"ו' כנ\"ל, והיינו שיהיו בגופים כמו שעלו במחשבה תחלה שלפני יצירת אדה\"ר בג\"ע, וזהו מא\"ד למעלה מאד\"ם כו' וד\"ל. וזהו כן היינו מפניך הוי' עד שנהי' מפני\"ך הוי' ממש בעוה\"ב שהיינו כבר במחשבה הקדומה הרינו חלנו כו' הי' תחלה בחי' עיבור ויניקה שזהו בחי' הגלות והגאולה שנמשל לעיבור ולידה כנ\"ל וד\"ל (וידוע דחבלי לידה נפסקים בגמר הלידה והוא קוצר רוח שע\"י עבודה קשה המונעים ומעכבים כנ\"ל שלא יהי' בזמן הגאולה שנק' לידה כנ\"ל, אך יש כאב שמרגשת אחר הלידה ברוחות הבטן כידוע וזה יהי' גם לאחר הגאולה מיד, אבל יהי' מיד גידול שם ה' כו' עד שגם בגוים יאמרו הגדי\"ל ה' לעשות עם אל\"ה דוקא, והוא מ\"ש עד דוד הגדי\"ל<sup data-n=\"1341\">27</sup> שזהו בתח\"ה ועוה\"ב שאינו בא רק מחמת בחי' הגידול דעיבו\"ר ויני\"ק' דוקא שהוא הכנת חומר וצורה לפנימי' הצורה האלקי' דהיינו שכר המצות בחיי העוה\"ב, וכמ\"ש יחיינ\"ו",[["1339","25","<b>אד\"ם אדם דוד משיח</b>: ראה לעיל ד\"ה שמח תשמח (הראשון) אות כ\"ב. וש\"נ."],["1340","26","<b>ואח\"כ</b>: תיבה אח\"כ נקרעה בגליון הכי\"ק. ואוצ\"ל: ואח\"כ ירום."],["1341","27","<b>עד דוד הגדיל</b>: שמואל-א כ, מא."]]],[1900420309,"מיומי\"י' בימהמ\"ש וביום הג' יקימנו בתח\"ה ונחי' לפני\"ו ממש, וכמ\"ש חדש ימינ\"ו כקד\"ם<sup data-n=\"1342\">28</sup> כמו שהיינו מפניך ה' כשעלו במחשבה כנ\"ל, וז\"ש מראש צור\"י' ארא\"נו כו' דקאי על משיח כמ\"ש בזוהר<sup data-n=\"1343\">29</sup> וד\"ל).\n[ט] <b>וזהו</b> ענין ארץ זבת חלב ודבש. דהנה הארץ הוא ג\"כ בבחי' אד\"ם בגידול דיניקה ומוחין כנ\"ל, וזהו שכל ענין כניסתם לארץ הי' לעבודה בגילוי שם הוי' בתו\"מ בפ\"מ כמו כי תבאו אל הארץ כו' שרוב המצות תלויין בארץ<sup data-n=\"1344\">30</sup> דוקא (ומשיח יבא לא\"י דוקא ויבנה בהמ\"ק שם, וכמו שמבקשים ולירושלים עירך כו' את צמח דוד כו' וכן והביאנו לציון כו'), וכל יח\"ע דקודב\"ה ושכינתי' שבמצות מעשיות שהי' בארץ ישראל בזמן בהמ\"ק ראשון ושני הגם שהי' יותר בגילוי מבזמן הגלות מ\"מ לא הי' גילוי גמור דשם הוי' באלקים רק בהיכל ק\"ק לבד ע\"י צמצום שצמצם שכינתו בין בדי הארון<sup data-n=\"1345\">31</sup> כו' כידוע, אבל בשוב ה' שיבת ציון לע\"ל אז הגדיל ה' לעשות כו' שיהי' בבחי' גדלות דשם הוי' שיתגדל ויתקדש לעין כל כנ\"ל אז נק' ארץ זבת חלב ודבש, ובחי' חלב היינו בחי' גידול דמוחין דיניקה שהוא בחי' המשכת עונג העליון שבמצות שבא בגילוי בימהמ\"ש אחר בירור דעה\"ד טו\"ר לגמרי כו' וד\"ל (וכמ\"ש במ\"א בפי' מ\"ש ושם נעשה<sup data-n=\"1346\">32</sup> לפניך כמצות רצוניך כו' דהיינו מצות מעשיות כעכשיו שמלובשים בגשמיות רק שלא יהי' בדרך בירור דטוב ורע כו' כי אין בין עוה\"ז<sup data-n=\"1347\">33</sup> כו').\n[י] <b>ומעתה</b> יש להבין בחי' הדבש שלמעלה מבחי' חלב וכמ\"ש דבש וחלב<sup data-n=\"1348\">34</sup> כו' דקאי על פנימי' התורה שנק' חלב ודבש כו'. וענין הדבש יובן עפ\"י הקדמה בתחלה במהות הדבש הגשמי<sup data-n=\"1349\">35</sup>, להיות שיש בדבש ב' דברים במה שהמתיקות שבו כלול מבחי' החריפות ג\"כ (ובל' המקובלים נק' בחי' גבורות שבחסד שבכחו להמתיק הגבורות כמשי\"ת) וע\"כ יש שני דברים בדבש, א' שבטבעו לכווץ ולקמוץ הדבר הנטמן בו לבל יקולקל לעולם. דהנה ידוע שיש בטבע הדבש להעמיד ולקיים הדבר הנטמן בו שיתקיים אותו הדבר ימים רבים",[["1342","28","<b>יחיינו מיומיי'. . חדש ימינו כקדם</b>: הושע ו, ב. איכה ה, כא."],["1343","29","<b>מראש צורי' אראנו. . משיח כמ\"ש בזוהר</b>: בלק כג, יט. זח\"ג רג, ב. ראה ביאוה\"ז קה, א ואילך."],["1344","30","<b>שרוב המצות תלויין בארץ</b>: ראה גם ספרי מאמרי אדהאמ\"צ: ויקרא ח\"א ע' תטו. במדבר ח\"ב ע' תשסט. ח\"ג ע' תתקצא [ובארוכה בהמ\"מ שם ע' א'רעט]. ח\"ה ע' א'תתמב. דברים ח\"א ע' ה. תו\"ח בראשית ה, א. תולדות כא, ב."],["1345","31","<b>שצמצם שכינתו בין בדי הארון</b>: ראה תנחומא ויקהל ז: בתוך הארון כו' צמצם שכינתו. ועד\"ז בכ\"מ."],["1346","32","<b>במ\"א בפי' מ\"ש ושם נעשה</b>: ראה תו\"ח ויחי צה, א."],["1347","33","<b>אין בין עוה\"ז</b>: ברכות לד, ב."],["1348","34","<b>דבש וחלב</b>: שה\"ש ד, יא. וראה חגיגה יג, א: במעשה מרכבה כתיב בהו דבש וחלב תחת לשונך."],["1349","35","<b>יובן ע\"פ הקדמה תחלה במהות הדבש הגשמי</b>: בהבא להלן ראה גם: ס' מאמרי אדה\"ז הקצרים ע' תנד ד\"ה דבש הוא גבורות וד\"ה לה\"ע אכילת הדבש. סה\"מ תקס\"ז ע' רלב ואילך. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תפד. תפח. ח\"ג ע' א'יט [ובהמ\"מ שם]."]]],[1900420310,"בלתי יקולקל ויופסד עצם טעמו ולא תוארו ולא יפרדו חלקיו רק יהי' בתקפו ומעמדו כמו שהי' הדבר בתחלת חידוש הוייתו חזקו וקיים כו', והטעם הוא כי כל הפסד וכליון דבר מה מן הדומם והצומח וחי כי מרוב ימים ושנים יתפרדו חלקי הד' יסודות המורכבים בדבר ע\"י שינוי אויר והרוח וילך כל א' למקור יסודו כו', וזהו סיבת הרקבון והעיפוש בתבואה וכל צומח וחי, וגם הדומם יכלה ויפסד בשינוי האוירי' ברוב ימים ושנים כידוע, אך כאשר יטמין הדבר בדבש יקויים בקיום חזק בלי יכלה ויפסד כלל גם ברוב ימים (כמו שמטמינים לקיום בדברים היותר חריפים שמחזקים ביותר כידוע). וא\"כ ודאי מוכרח שיש תוקף כח הכיווץ והקימוץ בדבש להצמית ולכווץ הדבר שידובקו חלקי ד\"י שמורכבים בדבר לבלתי יפרדו לעולם ולא יופסדו משינוי אוירי' כלל, וראי' מן ההיא תינוקת שהורדס טמנה בדובשנא<sup data-n=\"1350\">36</sup> כו', וכמו טבע החומץ וכל דבר חריף שמצמית ומכווץ ומעמיד ומקיים כל דבר הכבוש בו כמ\"ש בפוסקים בכמה דוכתי, ונמצא שיש כח החריפות בדבש המתוק שאין זה בשאר דבר מתוק (כי הגם שהמתיקות מורה על בחי' החסדים והחריפות מורה על בחי' הגבורות כידוע, אבל יש חריפות בדבש גם שהוא מתוק שהרי משקה דבש שורף הלב ומשכר מאד כו'). והדבר הב' יש בדבש שטבעו לפעול היפוך הדבר הנטמן בו שיתהפך להיות כמוהו ממש, דהיינו ברוב הימים מאד יהופך הדבר הנטמן בו לדבש ממש כמ\"ש בפוסקים ביו\"ד בענין היתר רגלי הדבורים הנמצאים בדבש<sup data-n=\"1351\">37</sup> (וגם בענין חתיכת חלב שנפל בדבש כמ\"ש באשרי במס' חולין<sup data-n=\"1352\">38</sup>), מלבד מה שיש בכחו להפוך גם מרירו למיתקא דהיינו דבר מר ביותר שיוטמן בו יהפכנו למתיקות, שאין כח היפוך כזה בשאר דבר מתוק זולתו (כמו הצוקע\"ר וכה\"ג שמערבין בדבר מר וחריף הגם שנהפך למתיקות זהו רק מצד התפשטות הטעם מתיקות של הצוקע\"ר וכה\"ג עד שאין המרירות נרגש אבל ישנו במהות ולא שנהפך גוף דבר המר והחריף להיות מתוק בעצם כמוהו, אבל הדבש מהפך מהות דבר המרירות להיות גם הוא כמוהו מתוק בעצם כו'). וכל זה מוכיח שיש ב' ענינים בדבש, א' שמכווץ ומצמית חלקי דבר הנטמן בו עד שיהפכנו להיות כמוהו ברוב הימים, והב' הוא העיקר שיש בדבש בחי' הגבורות דוקא דהיינו בחי' כח ההתגברות לעמוד על דבר היפוכו שהוא מר להפוך אותו למתיקות כמוהו, והוא בחי' עוצם החריפות כח",[["1350","36","<b>ההיא תינוקת שהורדס טמנה בדובשנא</b>: ב\"ב ג, סע\"ב: הורדוס עבדא דבית חשמונאי הוה נתן עיניו באותם תינוקת כו' וההיא ינוקתא נפלה מאיגרא לארעא טמנה שבע שנין בדובשא."],["1351","37","<b>בפוסקי' ביו\"ד בענין היתר רגלי הדבורי' הנמצאי' בדבש</b>: טור יו\"ד סוס\"י פ\"א. וראה טור או\"ח סי' רט\"ז. ובתוס' ע\"ז סט, א ד\"ה ההוא: יש לתמוה היאך אנו אוכלים דבש דבורים והלא רגלי הדבורים מעורבים בדבש כו'. וראה להלן הע' הבאה."],["1352","38","<b>חתיכת חלב שנפל בדבש כמ\"ש באשרי במס' חולין</b>: במאמר המקביל לכאן בתו\"א קו, ד. מציין: וכמ\"ש בי\"ד בענין היתר רגלי הדבורים שבדבש כו' ובענין חתיכה של איסור שנפלה בדבש עיין בהרא\"ש פ' כיצד מברכין בשם הר\"ר יונה ובטוא\"ח סי' רי\"ו ובטויו\"ד סי' פ\"א דיעות בזה."]]],[1900420311,"שבמתיקות שלו עד שיוכל להמתיק המרירות היפוכו להיות כמוהו בעצם המתיקות (שאין זה בשאר מתיקות כמתיקות הצוקע\"ר שאין בו כח החריפות וההתגברות כ\"כ להפוך דבר המרירות היפוכו להיות כמוהו רק שלא יורגש בלבד כנ\"ל) (וזהו הנקרא בחי' גבורות שבחסד שהוא בחי' התגברות הכח הגדול שבמתיקות שנקרא חסד להמתיק גם לבחי' הגבורות שנקרא דין להיות כמוהו ממש משא\"כ בחסד שבחסד עצמו כמו דבר המתוק בעצם כצוקע\"ר וכה\"ג אע\"פ שמתוק יותר כו').\n[יא] <b>ובאמת</b> עיקר ענין זה התוקף והכח החזק להפוך המרירות למתיקות כמוהו ממש אין זה רק מצד בחי' כח הכיווץ שיש בדבש שמכווץ ומצמית כל דבר כנ\"ל ע\"כ בדבר מר היפוכו ג\"כ יכווץ אותו ויצמית חלקיו עד שברוב הימים יתגבר עליו עד שיהפכנו להרכבת עצמו. וזהו עיקר ענין ובחי' הגבורות שהוא רק כח של הצמצום והכווץ בעצמותו דוקא היפך ההתפשטות כו' וד\"ל. ויובן זה במה שאנו רואים ההפרש בין קור לחום בקיץ וחורף או בדרום וצפון שטבע קרירות לכווץ הכל בגלדי קרח המים שנקשרו ונגלדו מפני הקור שמכווץ חלקי המים שלא יתפשטו כלל, וע\"כ אמרו גבי ריאה בקרירי לא דמטרשי<sup data-n=\"1353\">39</sup> כו' שמחזקים ומכווצים הקרום וסותם הנקב כו', וטבע החום הוא בבחי' ההתפשטות דוקא היפך הכיווץ כחום היום בדרום שמפריש כל שלג וקרח גם אשר בראשי ההרים ומה שכל חום מוליד בא ג\"כ מבחי' גבורה שבחסד, אך הוא מבחי' גבור' ההתפשטות שבא ע\"י תוקף החום דוקא וכן בדם הוא הנפש, משא\"כ גבורות הכיווץ כגבור הכובש רוחו וכל כח חזק הוא רק ענין תוקף כח הכיווץ כמו כח הגבהת משא כו'). וזהו טעם ההפרש בין כח הדבש שיכול להפוך מצד כח הכיווץ שיש בו לשאר דבר מתוק שאין בו כח הכיווץ אע\"פ שמתוק יותר אין זה רק בבחי' התפשטות המתיקות ולא שיהפוך המר למתוק לפי שאין בכחו לכווץ אל עצמו חלקי הדבר היפוכו להיותו רק בבחי' ההתפשטות לחוץ ולא הכיווץ לעצמו, וע\"כ אין בכחו לקיים כל דבר שלא יופסד כי הא בהא תליא והכל הולך אל טעם ושרש א' שהגבו' שבדבש הוא בבחי' גבורות דקרירות שמכווץ וע\"כ מעמיד ומקיים כל דבר ומהפך כח היפוכו להיות כמוהו ממש, עד שנקרא בשם גבורות ממותקות דהיינו שגם הדין בעצם מהותו נהפך לחסד, כענין קטיגור עצמו שנעשה סניגור וכהיפוך הקללה עצמה לברכה וכה\"ג א' ויורהו עץ<sup data-n=\"1354\">40</sup> וישלך כו' וימתקו",[["1353","39","<b>גבי ריאה בקרירי לא דמיטרשי. . וסותם הנקב</b>: בגמ' חולין מו, ב: מייתינן מתיכולתא דמיא פשורי ומותבינן לה בגווה בחמימי לא דכווצי בקרירי לא דמטרשי [וכ\"ה שם מז, ב]. ובר\"ן שם: דמטרשי — שמקשין אותה וסותמין הנקב. ובפירש\"י שם מפרש ג\"כ מטרשי לשון טרשים שמקשין אותה, אך לא משום סתימת הנקב כ\"א פירוש אחר ע\"ש. ובש\"ך יו\"ד סל\"ו סק\"ח ועד\"ז בפסקי דינים שם מכ\"ק אדהאמ\"צ מביא דעיקר כפי' הר\"ן. וראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' כט."],["1354","40","<b>ויורהו עץ</b>: בשלח טו, כה. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תצז."]]],[1900420312,"המי\"ם המרי\"ם בעצ\"ם וד\"ל (והוא הנקרא בשם מיתוק הדין בשרש\"ו<sup data-n=\"1355\">41</sup> בבחי' גבורות שזהו דוקא הנקרא גבורות ממותקו\"ת ולא כאשר בלתי פועלים פעולתם מצד ריבוי שפע החסדים לבד שאין זה נקרא מיתוק בעצ\"ם עדיין כו' וד\"ל).\n[יב] <b>והנה</b> הדוגמא מכל זה יובן למעלה בבחי' הדבש, ותחלה יש להבין בנשמת האדם בדרך פרט. דהנה אנו אומרים נשמה שנתת בי אתה בראתה כו' ואתה נפחת בי ואתה משמרה בקרבי, ויש להבין בשימור זה שמשמרה בקרבי מהו מאחר שהנשמה היא באה בגוף בבחי' בריאה מאי\"ן ליש כמ\"ש אתה בראת' כו' ויצרת ונפחת בי כו' למה צריכה שימור לשמור אותה בגוף כו'. אך הנה ידוע דשרש מחצב הנשמות בא מאי\"ן ליש מבחי' שם הוי' דוקא כמ\"ש נר הוי' נשמת אדם<sup data-n=\"1356\">42</sup> כו' כניצוץ קטן מן השלהבת כו', רק שירד אור הנשמה האלקית בבחי' צמצום גדול בקטנות מאד ובשינוי המהות כו' עד שבהיותה נתונה בחומר הגופני מוסתר אור שם הוי' בכל נשמה מאד, וכנ\"ל בבחי' עיבור כמו בגלות שמרחוק ה' נראה כו' אע\"פ שיאיר אור ה' ע\"י עסק התו\"מ היינו למעלה ולא למטה כו', אך בבחי' יניקה דחלב הנ\"ל הוא שהגדיל האור דשם הוי' בכל ניצוץ בפרט, וכמ\"כ בדרך כלל בכללות נש\"י בבחי' מוחין שבמדות אוי\"ר שכליים לחזות בנועם ה' כמו ששם הוי' הוא למעלה מאיר למטה מקצת אורו העצמי כו', והוא בחי' לידה דגאולה שכולם יידעו אותי כו' וראו כל בשר<sup data-n=\"1357\">43</sup> כו' כנ\"ל באריכות. ולהיות כן הי' כל ניצוץ אור האלקי שמלובש בגוף יוצא בכליון הנפש ליכלל במקור חוצבו שהוא שם הוי' כי משם לוקח בשרשו בעצם קודם בואו לגוף בבחי' בריאה ויצירה מאי\"ן ליש וכמו ואתה נפח\"ת בי כענין ויפ\"ח באפיו נשמת חיים שהוא נשמה הכללית דאדה\"ר ולא יוכל הניצוץ האלקי להשאר כלל בחומר גופו מאחר שנגלה עליו כבוד שם הוי' למטה כמו שהוא למעלה גם בעיני כל בשר ג\"כ וכמ\"ש וראו כל בשר כו', ושם הוי' זה הרי הוא מקורו העצמי ממילא נמשך מיד אחריו כניצוץ הנמשך אחר השלהבת מאחר שמשם הוי' נלקח קודם שנמשך למטה בבחי' זריעה דאור הזרוע לצדיק עליון כו' וכמ\"ש כי חלק הוי'<sup data-n=\"1358\">44</sup> ממש כו', וע\"כ מיד שישיג ויראה כל ניצוץ אור גילוי דשם הוי' כמו לע\"ל לא יוכל להשאר בחומר גופו כלל, ובפרט כשהגדיל ה' לעשות עם אלה בעת הגילוי הגדול דלעתיד כו'. ולזה הוא אומר ואתה משמרה בקרבי ענין שימור זה היינו לאחר שנפחת בי משמרה שתשאר בחומר הגוף ולא תפרד לצאת מן הגוף בהפשטת הגשמיות ליכלל",[["1355","41","<b>מיתוק הדין בשרשו</b>: ראה פע\"ח שער השופר פ\"א. לקו\"ת להאריז\"ל וישב לט א. תניא פל\"א. ובכ\"מ. וראה בכ\"ז בארוכה בס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תצז ואילך."],["1356","42","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["1357","43","<b>ויפח באפיו. . וראו כל בשר</b>: בראשית ב, ז. ישעי' מ, ה."],["1358","44","<b>כי חלק ה'</b>: האזינו לב, ט."]]],[1900420313,"במקורה כו', והיינו ואתה משמרה בקרבי שישמור אותה להיות מתקיימת בקרבי ולא תצא במס\"נ, ואע\"פ שאין עכשיו בחי' גילוי הגדול דשם הוי' דלע\"ל מ\"מ יש מקצתי' ודוגמתו בכל שבת ויו\"ט ובכל יום בק\"ש בכל אדם רק שמרחוק נראה ה' ולא בקירוב כ\"כ כמו לע\"ל כו' (וכנשמות בג\"ע שעולין מדי חדש ושבת יש להן שימור מלמעלה שלא יתבטלו במציאות). אך מהיכן יבא בחי' שימור זה מלמעלה, הענין הוא שנמשך מבחי' גבורות שבחסד עליון כמו בחי' הגבורות שבדבש הנ\"ל שמכווץ ומצמית ומקיים כל דבר שלא יפרדו חלקיו כו' עד שיתקיים בחומר הוייתו כמו שהוא בתחלת הוייתו ממש כנ\"ל, כך עד\"מ נמשך מבחי' תוקף כח הגבורות שבח\"ע לכווץ ולהעמיד ולקיים כל ניצוץ האלקי שבתוך חומרו שיתקיים בחומר הוייתו ולא יתבטל ויכלה במקור חוצבו בשם הוי' שנגלה עליו כנ\"ל (וכענין רצוא ושוב שמיד שתרוץ הנפש ליכלל למעלה ישוב לאחור כו'), ובחי' כח אלקי זה הוא שמשמר את הנשמה בחומר גופה לבלתי תפרד לצאת מנרתקה, וזהו כח חסד אלקי שבא בתגבורת גדולה לגבור על הניצוץ להעמידו בחומרו ונקרא גבורה שבחסד. וזהו בחי' הדבש למעלה שנז' בא\"י שנקרא ארץ זבת חלב ודבש לפי שע\"י בחי' יניקה דחלב בא בחי' אור הגילוי דשם הוי' ע\"כ צריך מיד לשמירה לקיים ולהעמיד הנשמות שלא תוכלל במקורה כנ\"ל שז\"ש ואתה משמרה בקרבי אחר שאתה נפחת בי כו' וד\"ל.\n[יג] <b>אך</b> הנה עדיין יש להבין מהו המעלה דשימור זה שמשמרה בקרבי שלא תפרד הנשמה מן הגוף ליכלל במקורה בשם הוי', ודאי זהו תכלית העילוי לנשמה שתדבק במקור חיי החיים לאשתאבא בגופא דמלכא ממש משתפרד בבחי' יש בפרט בחומר גופני שתתרחק מאור פני מלך חיים כו', ולא עוד אלא שזה הכח ועוז האלקי להעמידה ולקיימה בחומר גופני הוא בא מכח הגבורה שבחסד עליון כנ\"ל. אך הענין יובן בהקדים ענין והחיות רצוא ושוב וכמאמר אם רץ לבך<sup data-n=\"1359\">45</sup> שוב כו', וזה פלא גדול אם המרוצה היא מרוצת הנפש עד כלותה כמו כלתה נפשי צמאה לך נפשי<sup data-n=\"1360\">46</sup> וכה\"ג מהיכן יבא לה היפוך זה ממש שהוא בחי' שוב לאחור שתבא אל עצמותה להתקיים בגוף חומרי כו', והיינו קושיא דלעיל. אמנם הנה ידוע בפי' על כרחך אתה חי<sup data-n=\"1361\">47</sup> כו' שאחר המס\"נ דנשמה ע\"כ אתה חי כדי לקיים תו\"מ וזהו מעלה גדולה יותר מגוף ענין המס\"נ, והיינו הנקרא בזוהר דעייל ונפיק (דג' שנסתלקו<sup data-n=\"1362\">48</sup> מחמת הפלאת דביקות נשמתם לא יכלו לחזור בבחי' שוב לא נק' דעייל ונפיק כמו זולתם שגם המה",[["1359","45","<b>והחיות רצוא ושוב. . אם רץ לבך</b>: יחזקאל א, יד. ס' יצירה פ\"א מ\"ח. וראה לעיל ח\"א ע' שנג."],["1360","46","<b>כלתה נפשי צמאה לך נפשי</b>: תהלים פד, ג. סג, ב."],["1361","47","<b>ידוע בפי' על כרחך אתה חי</b>: אבות ספ\"ד. ראה תניא פ\"נ."],["1362","48","<b>בזוהר דעייל ונפיק. . דג' שנסתלקו</b>: זח\"ג קמד, א—ב: נפקא נשמתייהו [הג' סבות] בנשיקה כו' משום דעלאן ולא נפקו זמנא אחרא כו' וכולהו אחריני עאלו ונפקו."]]],[1900420314,"פרחה נשמתם מעוצם התענוג ועריבות מתיקות אבל עיילו ונפקו לחזור למטה בבחי' שוב כענין ע\"כ אתה חי כו' וד\"ל). ודבר זה אנו רואים בצדיקים הגדולים כי כאשר תכסוף הנפש בהתענגה על ה' בגודל עריבות מתיקות ידידות עוז ההתקשרות באלקים חיים עד כלות\"ה ממש, הנה במה תחזור הנשמה להתקיים בגוף, אין זה אלא שתבחור יותר בקיום רצון העליון בתו\"מ בפ\"מ יותר משתתענג על ה' בעונג נפלא האלקי בעריבות מתיקות כו', כי אותו עונג אלקי שבקיום רצון ה' בתו\"מ תערב לנפש יותר משתהנה מזיו אור האלקי שמאיר בנשמתו, וכמאמר דיפה שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב וכן א' תחת אשר לא עבדת<sup data-n=\"1363\">49</sup> כו' שהשמחה וטוב לבב בעבודה פשוטה במצות מעשיות בעוה\"ז שנקרא שמחה של מצוה הוא הרבה יותר מעונג העליון שברו\"ב כ\"ל דעוה\"ב כו' וד\"ל. ולהיות כן הרי יש כח בנפש לעמוד ע\"ע לבלתי תצא במס\"נ עד כלותה ותחזור ותרד מן דביקותה הנפלאה להיות בבחי' שוב והוא בתענוג ושמחה של מצוה בפ\"מ כו'.\n[יד] <b>אך</b> היא גופה יש להבין למה יש כח גדול כזה בתענוג ושמחה של מצוה בפ\"מ עד שמחמת זה תחזור הנשמה מדביקותה לבא בגוף החומרי היפך המס\"נ ממש מן הקצה כו', הענין הוא לפי שהתורה נמשלה לדבש שיש בו בחי' הכיווץ והצמצום לעצור הדבר בכל חלקיו שלא יכלה כו' והיינו מבחי' הגבורות שבחסד כנ\"ל, כך התו\"מ שרשם מבחי' גבורה שבחסד עליון כמ\"ש מימינו אש דת<sup data-n=\"1364\">50</sup> כו', והיינו בחי' תגבורת כח החזק שבחסד לכווץ ולעצור רוח האדם בקרבו שלא תכלה הנפש האלקית במקור יסודה במס\"נ אלא תתקיים במעמדה בחומר וצורה בגוף בתענוג ושמחה של מצוה כענין ואתה משמרה בקרבי כנ\"ל להיות ע\"כ חי בגופו ימים רבים ויחי' בקיום התו\"מ בבחי' שוב כנ\"ל, וזהו כח גדול יותר מגופו של אור חסד עליון שיורד להאיר בנשמה בימין מקרבת באה\"ר עד שתכסוף הנפש במס\"נ כנ\"ל דיפה שעה א' כו' וד\"ל. ועוד יובן בנמשל זה שהוא כמו הדבש שמהפך הדבר להיות כמוהו גם המר למתוק בעצם כנ\"ל, כך בחי' התו\"מ בעוה\"ז ששרשם בגבורות עליונות שבח\"ע יש בכחם להפוך מהות וטבע הנשמה שמתקשרת בתוכם להיות כמוהו, והוא בבחי' שוב שהוא ירידת העונג העליון למטה שבתו\"מ מלובש בגשמיות בבחי' ירידה דאו\"י היפך בחי' ההעלאה דאו\"ח כו', וזהו ג\"כ הכח ועוז לאהפכא מרירו למיתקא כו' שזהו בחי' בירור דעה\"ד טו\"ר לעשות מחושך דק\"נ אור ע\"י תשובה ומע\"ט בעוה\"ז דוקא וד\"ל (והיינו להמתיק גם הגבורות קשות כו' לחסדים שאין מיתוק הדין אלא בשרשו כנ\"ל, וזהו למעלה עונג עליון הרבה יותר מעונג האלקי' שבנשמות בג\"ע או בדביקות הנפלא' דצדיקים הנ\"ל וד\"ל).",[["1363","49","<b>דיפה שעה א'. . תחת אשר לא עבדת</b>: אבות פ\"ד מי\"ז. תבוא כח, מז."],["1364","50","<b>מימינו אש דת</b>: ברכה לג, ב."]]],[1900420315,"[טו] <b>וזהו</b> למען אחיי וריעיי כו', שאותן נשמות דעיילו ונפקו בבחי' שוב ע\"י כח ועוז דתו\"מ לעמוד על נפשם בגבורה לחפוץ יותר בקיום תו\"מ כו' נקראים גבורי כח<sup data-n=\"1365\">51</sup> עושי דברו בגבורה ועוז תורה כו' נקראים אחים וריעים להקדב\"ה או אחותי כו' לפי שהן בדומה לו בבחי' אד\"ם וכמו זאת תורת האד\"ם<sup data-n=\"1366\">52</sup>, ופי' אד\"ם אדמ\"ה לעליון<sup data-n=\"1367\">53</sup> שנעשה בצלמ\"ו כו' שהוא באמיתי' דשם הוי' כמו שהוא בעצם שאין זה בענין מס\"נ היותר נפלא (שהרי גם האבות שהיו בחי' מרכבה א' ושמי הוי' לא נודעתי<sup data-n=\"1368\">54</sup> להם ששם הוי' בעצם אינו אלא בקיום התו\"מ בגשמיות דוקא כמ\"ש אלה המצות<sup data-n=\"1369\">55</sup> כו'), וע\"כ נק' אחי\"ם ממש וכן א' כנ\"י מי יתנך כאח לי כו', אבל בבחי' מס\"נ דנשמות כמיכאל מקריב נשמות<sup data-n=\"1370\">56</sup> ע\"ג המזבח כו' זהו רק כניצוץ העולה לשלהבת כו' אז נק' כנ\"י ברתא דמלכא שתכסוף וגם כלת\"ה נפשה ליכלל כו' ואינו נק' אחים או אחותי רק בבחי' שוב דע\"י תו\"מ. וזהו עיקר ענין דאתה משמר\"ה בקרבי שבא מכח אלקי עליון הרבה יותר ממדרגה דאתה נפחת בי מטעם כל הנ\"ל (והוא בחי' המקיפים העליונים שלמעלה מנר\"נ דבי\"ע כו') וד\"ל.\n[טז] <b>ואחר</b> כל זה יובן שרש ענין שמחת חתן וכלה. דהנה יש בתיבת כלה ב' פי', א' כמו כלת\"ה נפש\"י במס\"נ בעריבו' מתיקו' ידידו' עד כלותה כנ\"ל, והפי' הב' ל' כל\"א שהוא העיכוב והמניעה והעדר ההתפשטות לצאת חוץ כו' והיינו כענין ואתה משמרה בקרבי הנ\"ל שבבחי' שוב דתו\"מ שהוא בחי' גבורות שבדבש לכווץ כו', והיינו כח המעכב שיש בדבש דתו\"מ שיותר ישמח ויתענג במצוה בפ\"מ מעונג שבדביקות הנפש ובזאת תתנחם הנפש יותר ותהי' עצור וכלו\"א בגוף כדי לקיים המצות כנ\"ל. וזהו עיקר ענין שמחת כלה מל' כל\"א ומניעה כו' היפך דכלת\"ה נפשי בדביקות כו', והוא מה שתשמח בשמחה של מצוה בטוב לבב הרבה יותר מרוב כל דעוה\"ב כנ\"ל. ומבואר למעלה דכח זה שתשאר הנפש בגוף שהוא בא מכח שימור העליון שמשמרה כו' הרי הוא הרבה יותר נעלה ממדרגה זו דעונג אלקי שבנפש בדביקות. ויובן זה במה שמצינו ההפרש בין נבואת משה לשאר הנביאים שבשעה שרוח ה' דיבר בם נתבטל חושי חומר גופם ולא יכלו לעמוד ונפלו על פניהם וכידוע, אבל משה הי' שכינה מדברת מתוך גרונו<sup data-n=\"1371\">57</sup> והי' עומד בגופו בלי שינוי כו', כי מה שצריך",[["1365","51","<b>גבורי כח</b>: תהלים קג, יט."],["1366","52","<b>זאת תורת האדם</b>: שמואל-ב ז, יט. ראה לעיל ח\"א ע' קע. וש\"נ."],["1367","53","<b>אד\"ם אדמ\"ה לעליון</b>: ע\"פ ישעי' יד, יד. ראה לעיל ד\"ה שמח תשמח (השני) אות י\"ב."],["1368","54","<b>ושמי ה' לא נודעתי</b>: וארא ו, ג."],["1369","55","<b>אלה המצות</b>: בס\"פ בחוקותי: אלה המצות אשר צוה ה' את משה אל בנ\"י בה\"ס. וראה לעיל ד\"ה קול מצהלות, סוף אות י\"ד. וש\"נ."],["1370","56","<b>כמיכאל מקריב נשמות</b>: ראה זח\"א פ, א. מנחות קי, א בתוד\"ה ומיכאל."],["1371","57","<b>שכינה מדברת מתוך גרונו</b>: ראה זח\"ג רלב, א. מכילתא שמות יח, יט. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשמט. וש\"נ."]]],[1900420316,"הפשטת הגשמיות היינו כשגופו מסתיר לו צריך להפשיטו ולצאת מחומר גופו המחשיך כו' ואמנם לא קם נביא כמשה שידעו ה' פא\"פ<sup data-n=\"1372\">58</sup> כו' שלא הי' גופו מסתיר לו כלל כו'. וכדוגמא זו יובן ההפרש בין שמחה של מצוה שהוא בחי' עונג העליון שירד למטה כמו שהוא למעלה ונק' עונג היורד ונשפל אל עצמותו היינו שמשתעשע בעצמו בעונג העליון שבמעשה המצוה בפ\"מ למטה, וזהו שמחת כלה שלמעלה ממס\"נ בכליון הנפש שאינו רק מצד שצריך להפשיט עצמו מגופו המחשיך כו' ע\"כ נק' דביקות הנפש בעונג נפלא עד כלות\"ה היינו עד שתופשט מחומר גופה המחשיך כו' וד\"ל. וזהו הטעם שנקרא בשם שמחת כלה לפי שהשמחה היא בחי' עונג היורד ונשפל מלמעלה למטה שמתעדן ומתענג בעונג זה דמצוה אל עצמותו דוקא, וע\"כ נק' שמחה של מצוה שהשמחה בכל מקום היא בחי' ירידה והשפלה מגבוה לנמוך שהרי כל גילוי ההעלם הוא ע\"י השמחה והמלך המרומם ישפיל עצמו לכל בהיותו בשמחה, ובחי' ירידת העונג הזה אל עצמותו שבשמחת כלה היינו היפך העונג העולה בהתכללות למעלה שבכלות הנפש אע\"פ שזהו מחמת רוב התענוג (בל\"א פו\"ן זיך ארויש) והעונג היורד בשמחה (בל\"א צו זיך אריין בהשבת נפש כו') למעלה מזה אשר ע\"כ גזרו אומר דיפה שעה אחת כו' כנ\"ל וד\"ל.\n[יז] <b>והנה</b> ע\"ד הנ\"ל בשמחת כלה כך הוא ממש ענין שמחת חתן העליון מלמעלה למטה, לפי שמבואר בזוהר דעלמא תתאה דנוקבא לגבי עלמא עילאה דדכורא כהאי אבן טבא כו' וכמ\"ש אבן ספי\"ר<sup data-n=\"1373\">59</sup> כו', ונק' המל' מרא\"ה דמו'<sup data-n=\"1374\">60</sup> כו', וכמו עד\"מ המראה שמראין בה דמות כפי מה שמראין בה כך יתראה בה, וכך הוא בבחי' המל' שנק' מרא' שכפי שמראין בה שמחת כלה הנ\"ל עד\"ז ממש בא לראות מלמעלה ג\"כ בשמחה כזאת דוקא דהיינו בבחי' עונג הנשפל ויורד אל עצמותו כנ\"ל, והוא הנק' בחי' שמחת חתן העליון חו\"ת דרג\"א וכמ\"ש והוא כחתן יוצא מחופתו<sup data-n=\"1375\">61</sup>, ועד\"מ המלך המרומם שעושה משתה וסעודה מזמין להשרים הקרובים אליו בהיכלו דוקא וכאשר תגדל השמחה בלב המלך אזי יצא מהיכלו הפנימי אל העם השמחים בחצר המלך וישב עמהם בפתח השער ויתגלה לעין כל דוקא גם לפחותי הערך ויראוהו הכל וישמחו עמו נמצא שכפי אופן שמחת העם כך יבא המלך לשמוח בשמחה כזו דוקא, כך יובן שכאשר כנ\"י שמחים בשמחה של מצוה דוקא אזי גם שמחה עליונה דחתן באה בבחי' ירידה והשפלה למטה בבחי' גילוי גדול לעין כל כו' שזהו",[["1372","58","<b>שידעו ה' פא\"פ</b>: ברכה לד, יו\"ד."],["1373","59","<b>בזוהר דעלמא תתאה. . כהאי אבן טבא. . אבן ספיר</b>: ראה זח\"ב קפד, ב: עלמא תתאה קיימא לקבלא תדיר והוא אקרי אבן טבא ועלמא עלאה לא יהיב לי' אלא כגוונא דאיהו קיימא כו'. ראה גם תו\"א קז, ב. סה\"מ תקס\"ב ח\"ב ע' שעו."],["1374","60","<b>מראה דמו'</b>: יחזקאל א, כח."],["1375","61","<b>והוא כחתן יוצא מחופתו</b>: תהלים יט, ו."]]],[1900420317,"ג\"כ שישמח במעשה המצות במה שאמר ונעשה רצונו למטה דוקא, והוא בחי' עונג היורד ונשפל למטה שלמעלה מעונג העליון שבהיכלו עם הקרובים אליו כו' וד\"ל. וזהו והוא כחתן יוצא מחופתו בגילוי גדול לעין כל לשמוח בשמחת כלה שהיא שמחה של מצוה דוקא שזהו בחי' דבש הנ\"ל וד\"ל (ולפי פי' הב' דכל\"ה כלתה נפשי בעונג העולה ליכלל למעלה כו' בודאי באופן כזה דוקא יבא שמח\"ת חת\"ן, והוא בחי' יניקה דחל\"ב הנ\"ל שהגדיל ה' לעשות עם אלה כו' לפי שכלת\"ה נפש\"ם ברשפי אש התשוקה ליכלל בגילוי אור דהוי' הבא בגילוי שהוא עצם שרשם, ובבחי' לידה שהוא הגאולה יבא כבוד ה' בגילוי כנ\"ל (משא\"כ בגלות שאין שמחה בחתן וכלה לפי שאין היחוד עליון רק בצמצום והסתר כו' כנ\"ל).\n<b>וזהו</b> ההפרש בין משמח חתן וכלה שזהו בבחי' עונג העולה בכליון הנפש כו' דאשה בעלה משמחה<sup data-n=\"1376\">62</sup> שתשוב רוחה ותשמח בבעלה ע\"כ משמח חתן תחלה ומשמחת החתן בא שמחת הכלה בחתן כו', אבל משמח חתן עם הכלה שהכלה עיקר היינו שמחה של מצוה שבבחי' עונג היורד בבחי' שוב בדבש דתו\"מ שאתה משמר\"ה בקרבי כנ\"ל הרי החתן יורד מלמעלה לקבל שמחה משמחת הכלה ג\"כ בדוגמא זאת דוקא כנ\"ל, וזהו משמח חתן עם הכלה בשביל הכלה דסוף מעשה עלה במחשבה תחילה כו', וזהו קול חתן וקול כלה שניהם בגילוי השמחה של מצוה ולא בהיכלו בסתר כו', וכענין קול גדול כו' וכמ\"ש במ\"א<sup data-n=\"1377\">63</sup> וד\"ל.\n<b></b>[חי] ולהבין כל הנ\"ל בתוס' ביאור ענין הנ\"ל בבחי' חלב ודבש, הנה יש להקדים תחלה במ\"ש כל שאור וכל דבש<sup data-n=\"1378\">64</sup> לא תקטירו כו' הרי הזכיר דבש עם שאור שהמה כשני הפכים בטעמם השאור הוא חמוץ בטעמו והדבש הוא מתוק ושניהם כא' בלאו א' דלא תקטירו, מזה מובן דגם הדבש משום איסור השאור נאסר בהקטרה ע\"ג המזבח אע\"פ שהוא מתוק מפני שיש בדבש מבחי' הגבורות שבשאור, והוא הנקרא בחי' דין דגדלות בל' המקובלים וכמ\"ש בס' הקבלה בפי' שופ\"ר ש\"ו פ\"ר<sup data-n=\"1379\">65</sup> דדב\"ש גי' ש\"ו שהן שרש הגבורות דחכמה כו'. וגם יש להבין מה שנחלקו המקובלים דלפעמים אמרו דהחכמה בבחי' החסד כמו קו הימין חח\"נ כו' ולפעמים אמרו דהחכמה בבחי' דין<sup data-n=\"1380\">66</sup>, וכידוע",[["1376","62","<b>דאשה בעלה משמחה</b>: ר\"ה ו, ב."],["1377","63","<b>וכענין קול גדול כו' וכמ\"ש במ\"א</b>: ראה לעיל ד\"ה קול מצהלות סוף אות י\"ח ואות כ', ע\"פ קול גדול ולא יסף."],["1378","64","<b>[חי] ולהבין כל הנ\"ל. . כל שאור וכל דבש</b>: ויקרא ב, יא. מכאן מיוסד על ביאור ד\"ה לה\"ע שמחת חו\"כ בתו\"א קז, ב ואילך. ובשינויים בסה\"מ תקס\"ג ע' קמו ואילך. וראה בהנסמן עוד לעיל בתחילת המאמר."],["1379","65","<b>בס' הקבלה בפי' שופר ש\"ו פ\"ר</b>: פע\"ח שער השופר פ\"א."],["1380","66","<b>מה שנחלקו המקובלים. . דהחכ' בבחי' החסד. . דין</b>: ראה להלן ריש אות כ\"ו. וש\"נ."]]],[1900420318,"דבחי' גבורות דע\"י מלובש בחסדים דא\"א ובחי' חסד דע\"י מלובש בגלגלתא דא\"א שנקרא כת\"ר דכת\"ר כו'. והנה להבין כל זה יש להקדים טעם איסור כל מיני מתיקות בריבוי דכל דבש בהקטרה כנ\"ל, דמשמע מזה שדבר המתוק הוא מבחי' הגבורות כמו השאור כנ\"ל, והלא ידוע שהמתיקות מורה על בחי' החסדים דוקא והגבורות הוא בחי' הדין והצמצום היפך החסדים ואיך יקרא דבר המתוק בשם דין דבחי' הגבורות כו'.\n<b>אך</b> הענין הוא שיש כמה מיני גבורות, הא' בחי' גבורות קשות שטבעם לכלות שנק' מדת הדין בעצם עד שאין מרחמין בדין כלל, ופעולת מדה זאת לשיצא' ולכלות עד שלא יצדק כל חי כו', וה\"ז כמו האש שטבעו לכלות כל דבר כמו שטבעו בהסתלקות ועלי' למעלה באש היסודי ע\"כ פעולתו ג\"כ הכליון לכלות כל דבר כו', וזהו בחי' דינא קשיא שאין בו מיתוק כלל. והמדרגה הב' יש בבחי' הגבורות היפך זה ממש ונק' גבורות ממותקות או דינא רפיא כידוע שמבחי' גבורות הללו שרש כל המשכת אור ושפע וחיות שבא דרך ירידה והמשכה למטה להשפיע ולהחיות למקבלים היפך הכליון וההסתלקות דגבורות קשות הנ\"ל, ושרשם בבחי' גבורות שבחסד, וכמבואר למעלה בבחי' הדבש כו' שגם יש בכח הגבורות אלה להעמיד ולקיים המציאות שלא יכלה ויופסד כדבש המכווץ ומקיים כנ\"ל. והנה מה שימצא אור המשכה ושפע בכל העולמות עד עוה\"ז השפל עפ\"י הרוב הוא מבחי' הגבורות דוקא יותר מבחי' החסדים, וכמו שאנו מוצאים בכמה דברים, הא' בענין שפע המזונות שאמר שולחן בצפון<sup data-n=\"1381\">67</sup> דוקא הרי מקור חיות כל חי בטרף מזונו בא מן הצפון ששם השולחן אשר לפני ה' כמ\"ש בזוהר, והיינו שא' דבני חיי ומזוני לאו בזכותא תליא<sup data-n=\"1382\">68</sup> שהוא בהיכל הזכות דבחי' החסד אלא במזלא תליא שהוא מבחי' הגבורות דמזל העליון ונוצ\"ר כו' כידוע. וביאור הדברים הנה אנו רואים בבני וחיי שבאים מבחי' הגבורות, להיות שחום הטבעי שרשו ודאי ביסוד האש שבוער כאש ממש בתאוה החומרית וא\"כ זהו מבחי' הגבורות דאש, ואנו רואים שכל בחי' הולדה שהוא ענין שפע וירידת המשכה להוליד ולד בא ע\"י חום התאוה ואם אינו יורה כחץ מפני מיעוט החום אינו מוליד כלל, וכמו שמצינו כשנתבטל החום הטבעי בכל הבריות שהוא היצה\"ר לא מצאו ביצה<sup data-n=\"1383\">69</sup> של תרנגולת ג' ימים וכה\"ג לפי שכל חום מוליד דוקא, הרי מבחי' הגבורות נמצא עיקר החסדים שהוא שפע בתולדה שנקרא ברכת פרי הבטן כו'. וכמ\"כ אנו מוצאים בחיי האדם שבא מדם הוא הנפש דוקא וכל סיבת אורך ימים תלוי",[["1381","67","<b>שולחן בצפון. . כמ\"ש בזוהר</b>: זח\"ב קנד, ב. סידור סא, ד. ס' מאמרי אדה\"ז על מארז\"ל ע' שצח. ס' מאמרי אדהאמ\"צ: במדבר ח\"ב ע' תפו. דברים ח\"ג ע' תשעה [וש\"נ]. נ\"ך ע' קכב. קכח."],["1382","68","<b>דבני חיי ומזוני לאו בזכותא תליא</b>: מו\"ק כח, א. וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תצח. תתה. דברים ח\"ב ע' תקא."],["1383","69","<b>שמצינו כשנתבטל. . היצה\"ר לא מצאו ביצה</b>: יומא סט, ב."]]],[1900420319,"בגבורת כח שבדם הוא הנפש אם עומד בתקפו כו' והדם הוא בבחי' הגבורות וע\"כ הוא אדום במראהו. ונמצא מובן מכל זה וכיוצא בו (כמעיין הזרע שלא נפסק לעולם מפני היותו מבחי' הגבורות ע\"כ יוצא טיפין טיפין, וכגבורות גשמים שיורדים בהתחלקות כו', וכך חיי הנפש בדפיקו דלבא, שכל זה בחי' הגבורות), דאע\"פ שנקראים בשם גבורות שהוא בבחי' הצמצום והוא באמת עיקר המחי' ומשפיע הרבה יותר מבחי' החסדים, וזהו בחי' גבורות ממותקות שנקראים גבורות שבחסד כנ\"ל וד\"ל.\n<b>והנה</b> עד\"ז יובן שרש ענין הדבש וגם כל מיני מתיקה שנאמר וכל דבש לא תקטירו כו', דאע\"פ שהמתיקות הוא מבחי' החסדים שרשו מבחי' הגבורות דוקא, אלא שהוא בבחי' גבורות ממותקות הנ\"ל שנקרא גבורה שבחסד ע\"כ נמשך טעם המתיקות שמחי' לנפש הטועמו כנ\"ל שמבחי' הגבו' יבא עיקר השפע והחיות, ובפרט בבחי' העריבות שבמתיקות (שכלול ממתיקות וחמיצות יחד שנקרא בל\"א וויינערליך) כמרקחת הדבש והצוקער בדברים חמוצים שעריבים לנפש הטועמן ביותר (שנקרא בל\"א קוויקעט) מן המתיקות, זהו ודאי מבחי' גבורות ממותקות, אך גם כל הטעמים שטועם בחיך עד שיחי' נפשו ותשוב רוחו ממש נקרא בחי' גבורה שבחסד והיינו כל הטעמים שבמאכלים הנרגשים בעונג לנפש הטועמם גם הטעם הרוחני כחיך יטעום אוכל דחכמ' וכמשי\"ת הוא מבחי' הגבו' וע\"כ מחי' ומשיב נפש כנ\"ל שהגבו' עיקר המחי' ומשפיע כו' וד\"ל.\n[יט] <b>ומעתה</b> יש להבין בשרש ענין הדבש למה נקרא בחי' דין דגדלות כו', ותחלה יש להבין ענין ב' מדרגות שבתענוג העליון שנקראים חו\"ג דע\"י וחסד דע\"י מלובש כו' כנ\"ל. ויש להקדים תחלה שיש ב' מדרגות בבחי' התענוג הא' בחי' התענוג הפשוט העצמי ותענוג המורכב<sup data-n=\"1384\">70</sup>, או שנקרא עונג הנעלם ועונג המורגש והכל א' כידוע. וביאור הדברים הנה עונג המורגש שהוא עונג המורכב היינו כאשר האדם מתענג בדבר מה שזהו בחי' צמצום הרגשת העונג כאשר יתצמצם מבחי' עצמות התענוג להרגיש עונג בדבר מה ואז נעשה בבחי' כלי קבלה לקבל בעצמו את העונג ההוא, ונמצא יש כאן ב' דברים, הא' צמצום בשפע התענוג הפשוט במה שמרגיש העונג המצומצם הזה שהוא רק כמו חלק קטן מאד שהובדל והופרש מכח עצמות התענוג הפשוט שבבחי' יחידה כו' שאינו בבחי' ההרגשה כלל ונקרא עונג הנעלם או עונג הפשוט ועצמי (בבחי' כח היולי ופשוט כו'), כי ההרגשה באה בבחי' צמצום גדול ובשינוי המהות מעונג הפשוט הרוחני, כי מאחר שמרגיש את העונג הרי בא לכלל הגשמה ומצומצם ביותר, וגם ממילא יבא לכלל שינוי ותמורה וחילוף",[["1384","70","<b>שיש ב' מדרגות. . תענוג הפשוט העצמי ותענוג המורכב</b>: ראה גם ביאוה\"ז ג, סע\"ב ואילך. עטרת ראש ס\"ע לב ואילך. תו\"ח שמות מו, א. רכ, ב. ובכ\"מ. וראה להלן בסמוך פיסקא ”בתענוג הפשוט\"."]]],[1900420320,"משעה לשעה לפי העת והזמן באופן הכנת הנפש לזה התענוג גשמי היינו לפי אופן גילוי אורה והשראתה בחיי חומר הגופני שבא בדילוג המהות מרוחניות לגשמיות, כידוע שתענוג גשמי שבמעדנים וטיול וציור נחמד וכה\"ג אין זה ערך לתענוג הרוחני שבנפש כלל, רק שמ\"מ מתענוג הרוחני שבנפש בא בדילוג מרוחניות לגשמיות להתפעל בעונג גשמי כו' אבל זה בא בשינויים רבים לפעמים כך ולפעמים כך, שלפעמים במיעוט ובאופן זה ולפעמים בהתרחבות והתפשטות ובאופן אחר, וזהו לפי העת והזמן בהכנות הנפש להתלבש בגוף כו', וע\"כ יש לפעמים תמורה וחילוף שמתבטל התענוג ואינו חפץ בו אלא בהיפוכו דוקא כו', אבל בחי' התענוג הפשוט העצמי שבעצמות הנפש בלתי מקבלת שינוי ותמורה כלל מאחר שבלתי מתלבשת בשינוי תוארי גשם תענוגי הגוף כלל כי מעצמות הנפש תחשב וע\"כ אינה בכלל הרגשה כלל ונק' עונג הנעלם בעצמות וד\"ל.\n[כ] <b>והצמצום</b> הב' הוא לבד בחי' הרגשת העונג בגשמיות, והוא במה שבא העונג במורכב דהיינו באופן פרטי ובדבר פרטי, עד\"מ אם מתענג אדם באיזה דבר נאה ונחמד למראה כבנין נאה או כסף וזהב ואבנים טובות יקרים מכל הון כו' שנפשו של אדם מחמדתן או מעשה רוקם בציור נאה באופן פרטי הנאות לו שיקבל מכל זה תענוג ושעשועים גדולים מאד, הנה התענוג המורגש הזה מורכב בדבר פרטי כמו הבנין או האבן טוב או הציור המרוקם ביופי והידור, ולא ראי זה כראי זה כו' שיש לכל א' תענוג מיוחד לפי אופן אותו הדבר שמורכב בו התענוג ויש טבעיות מחולקות בבנ\"א שזה טבעו להתענג מדבר זה וזולתו לא יתענג כלל מדבר זה כו', כמו במיני מטעמים זה אוהב ומתענג מטעם מתיקות וזה מטעם עריבות ודבר קיוהא, וכך בתענוגי הבנין והלבושי יקר וחפצי יקר יש מתענג מאופן זה דוקא וזה מאופן זה דוקא, וכך גם בתענוג הרוחני שבשכל ומדות יש שתענוג שלו באהבה יותר ובחסד יותר ויש שטבעו להתענג בבחי' הדין והיראה יותר, וכן בשכל שבמוח יש שתענוג שלו בחסד שבחכמה להטות כלפי זכות ויש שטבעו להתענג בדין שבחכמה להטות כלפי חוב כו' לפי שרש הנפשות מבחי' חו\"ג וענפיהן רבים מאד כו', וכן בעבודה שבלב באוי\"ר ודעת יש ס\"ר דיעות בכלל וענפיהן כו' בכפלי כפלים ובכל א' התענוג שלו מורכב באופן פרטי ובדבר פרטי כך וכך דוקא ולא באופן אחר זולתו. וא\"כ מובן עכ\"פ שהעונג המורגש הזה יצא לחלק פרטי דהיינו באופן ובדבר פרטי דוקא וגם זה הדבר שהוא מתענג בו הוא נעשה בחי' כלי ומכון שישרה בו התענוג הזה וכל כלי הוא המגביל כו'. ולפ\"ז יש ב' מיני גבול א' גבול הכלי שבו התענוג מורכב והב' הגבול בנפש במה שבא לכלל בחי' הרגשת העונג ובדבר פרטי ובאופן פרטי דוקא כנ\"ל וד\"ל.\n[כא] <b>והנה</b> מדרגה הב' בבחי' התענוג היינו בחי' כח התענוג הפשוט הנ\"ל שאינו בכלל הרגשה עדיין ונקרא עונג הנעלם כנ\"ל שאינו בא"],[1900420321,"בגילוי מורכב בדבר פרטי כלל שיגבילנו ויפול בו שינוי כו' כי אינו בא בבחי' כלי קבלה שיקבל ויכילנו כו', ויש להבין א\"כ למה נקרא בשם מציאת תענוג עכ\"פ אחר שאינו במציאת מהות תענוג כלל בשום דבר ולא בכלי קיבול כו', ועוד שהרי יש מציאות לכח התענוג הפשוט ג\"כ בכלי קיבול במורגש ובמורכב כמו שעשועים העצמיים דאב לבנו יחידו שאהבת נפשו אהבו או כאהבת יונתן ודוד וכה\"ג שבא בגילוי גמור ובבית קיבול שמקבל עצם התענוג הזה מבנו או אוהבו כנפשו וגם בא במורגש ביותר עד שתכלה נפשו אליו מרוב עוז התקשרות נפשו בו וכמו בנימין שא' ונפשו קשורה<sup data-n=\"1385\">71</sup> כו' וכה\"ג וכן באה\"ר בתענוגים העצמיים בכנ\"י ומכנ\"י למעלה כמ\"ש מה יפית<sup data-n=\"1386\">72</sup> כו' אהבה בתענוגים וזהו בכל א' בחי' התפעלות כל הנפש בתענוג הפשוט שבעצמות הנפש כידוע ומבואר במ\"א<sup data-n=\"1387\">73</sup>.\n<b>אך</b> הנה ודאי זה אמת, אמנם גם בזה התענוג הפשוט יש ב' אופנים א' בבחי' הירידה וההמשכה חוץ מן העצמות שבבחי' או\"י (שהוא ענין עונג היורד ונשפל כנ\"ל בבחי' השבת נפש אל עצמו כו') והב' בבחי' עלי' והסתלקות מן העצמות בכוסף הנפש כמו נכספ\"ה וגם כלת\"ה נפש\"י<sup data-n=\"1388\">74</sup> והוא תענוג בבחי' או\"ח למעלה. ויובן ב' הפכים אלה דאו\"י ואו\"ח הכל בעצמות התענוג, עד\"מ הידוע כאשר אדם עושה משתה לחתונת בנו יחידו שמצד אהבת נפשו לבנו ישמח ויגיל בעצם הנפש ממש והיינו בבחי' כח התענוג שבעצמות ממש ואז הוא מוגבה ומרומם מאד בפנימיות ועצמות הנפש מרוב התענוג העצמי עד שנהפך לאיש אחר בטבעו כמו להפריז על המדה מן הקימוץ שבטבעו אל הפיזור לכל אשר לו ממש שלמעלה מגדרי טבעו במדותיו ג\"כ וגם יוכל לקבל ולשמוח עם השונא כאוהב בשוה וכה\"ג, וכל זה מצד עוצם רוממות העונג אשר בעצמות ממש שבלתי מורכב בדבר מה כלל רק כמו שהוא בפנימיות עצמותו לבד כו'. והנה לכאורה אין זה תענוג במורגש ולא במורכב כלל, ואמנם ממנו מקור גילוי כל תענוג שבמורגש ומורכב עד שיהפוך מדותיו מן הקצה לקצה שזהו רק מחמת ירידת העונג למטה בפרטי מדותיו שאם לא הי' זה התענוג המרומם לא הי' מפזר אפי' פ\"א או כשהוא חכם גדול בסודות עמוקות יגלה כל מצפוני חכמתו וכמו רב יהודה דהו' בדיחא דעתי'<sup data-n=\"1389\">75</sup> אמר שישיב לשואלו כל חללי דעלמא וכה\"ג. ולפ\"ז יש כאן תכלית העלי' והרוממות של העונג בעצמותו ותכלית ירידת העונג למטה חוץ מעצמותו (וכמו דוד הי' מפזז ומכרכר בכל",[["1385","71","<b>ונפשו קשורה</b>: ויגש מד, ל."],["1386","72","<b>מה יפית</b>: שה\"ש ז, ז."],["1387","73","<b>בתענוג הפשוט שבעצמות הנפש כידוע ומבואר במ\"א</b>: ראה ס' מאמרי אדהאמ\"צ בראשית ע' רלו. שמות ע' רפב ואילך. נ\"ך ע' תסז ואילך. לעיל ח\"א ע' ט ואילך."],["1388","74","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["1389","75","<b>ר' יהודה דהו' בדיחא דעתי'</b>: ע\"פ שבת עז, ב. וראה לעיל ד\"ה שמח תשמח (הראשון) אות י\"ז."]]],[1900420322,"עוז וזהו ירידת והשפלת התענוג הנגלה בתנועת הפיזוז בכל כחו כו' וזה הי' רק מצד רוממות התענוג העצמי בה' וזהו שא' ושחקתי לפני ה' וזה עצמו גורם הירידה והשפלות העצום וכמ\"ש ונקלותי עוד מזאת<sup data-n=\"1390\">76</sup> והייתי שפל בעיני כו' בהגלות נגלה כאחד הריקים, משום דהא בהא תליא ממש דעוצם הרוממות בתענוג העצמות גורם עוצם הירידה בעונג הנשפל, וכרב ברונא דלא פסיק חוכא<sup data-n=\"1391\">77</sup> מפומי' בשחוק גשמי שהוא עונג הנשפל ביותר וזה בא לו רק משום דסמיך גאולה לתפלה שנתענג על יח\"ע זה בפנימיות ועצמות התענוג דהא בהא תליא כנ\"ל וד\"ל).\n[כב] <b>ומעתה</b> יתורץ ענין הנ\"ל דשניהם אמת והא בהא תליא, דודאי עצם התענוג שבנפש בלתי בא במורגש ומורכב כלל רק הוא תענוג מרומם בפנימיות ועצמות הנפש לבד כמשלים הנ\"ל במי שמתענג בתענוג המרומם בעצמותו כו', אך יש בו ב' אופנים. א' כשיורד ונשפל למטה כמו בשחוק לגלות עצמו בשפלות כדוד שהי' מפזז כו' ורב ברונא דלא פסיק חוכא מפומי' וכה\"ג, והשחוק אינו נקרא מורכב בדבר מה כי מפולש הוא מכל צד כמו עצם התענוג המרומם שמפול\"ש הוא בבחי' העצמות ע\"כ עיקר הכלי לו הוא השחוק וקלות עצמו. וגם בבואו בבחי' מורכב כמו במדותיו כנ\"ל יהי' גם הוא בלתי גדר כלל והוא שיהפוך מקימוץ לפזרונות ומכל גדרי טבעים יהופך לאיש אחר, הרי אינו תענוג מוגבל בכלי הטבע אלא אדרבה זהו התענוג בהיפוך הכלי המוטבע שיהי' פרוץ ומפולש בלי גדר כו'. וכל זה בבחי' או\"י שיורד ונשפל מעצמות התענוג למטה מטה עד אין שיעור לעוצם השפלתו בלי מעצור כלל, וכמ\"כ יש בו בחי' העלי' והסתלקות וכליון שזהו כליון כל עצמו' הנפש בתענוג ושעשועים כתענוג האב בבנו עד שתכלה נפשו אליו (פון זיך ארויש כו') יבא ג\"כ בלי גבול כלל רק הוא בבחי' או\"ח למעלה, ואע\"פ שבא בגילוי ובמורגש בבית קיבול אבל הוא בלתי מוגבל, כאה\"ר בתענוגים שנכספה וגם כלתה נפשו כו' בהתפעלות כל הנפש בפנימיות עצמותה ממש, והא בהא תליא דהיא הנותנת ירידת העונג העצמי הזה בשפלות עצמו בשחוק וקלות עצמו עם בנו יחידו ואוהבו כנפשו בוש לא יבוש גם בשוקים ורחובות לעין כל כנ\"ל בעונג דאו\"י וד\"ל.\n[כג] <b>ונמצא</b> מובן מכל זה שיש ג' מדרגות בכלל בתענוג, א' תענוג המורגש ובא במורכב בגבול וצמצום כנ\"ל שהן ב' צמצומים כו', והב' בחי' עצמות התענוג הפשוט כמו שהוא בבחי' הרוממות בתענוג עצום כעושה משתה לבנו יחידו (או כבשורה טובה ונפלאה שמגעת בכל עצמותו, כבשורה",[["1390","76","<b>ונקלותי עוד מזאת</b>: שמואל-ב ו, כב. וראה לעיל שם סוף אות ט\"ז."],["1391","77","<b>וכרב ברונא דלא פסיק חוכא</b>: ברכות ט, ב."]]],[1900420323,"דיוסף ליעקב דכתיב ותחי רוח יעקב<sup data-n=\"1392\">78</sup> כו' שבלתי מוגבלת כלל), ובזה יש ב' אופנים א' בבחי' או\"ח בכליון וכוסף כל העצמות כנ\"ל והב' בבחי' או\"י בירידה והשפלה בשחוק וריחוק או במדות וגם בדיבור ומעשה יהי' בלתי מוגבל כלל כנ\"ל וד\"ל.\n<b>והדוגמא</b> מכל זה יובן למעלה בבחי' תענוג העליון בעצמות המאציל שנק' שעשועי המלך בעצמו שהוא בבחי' א\"ס ממש והוא בחי' עונג הפשוט הנעלם בעצמות שלא בא במורגש בגילוי ולא במורכב דבר מה כלל כנ\"ל. והנה כאשר עלה ברצונו להאציל כו' בחי' הרצון העליון הזה נקרא בחי' הכת\"ר בכללות ונקרא בחי' ע\"י וא\"א, היינו בחי' התענוג שברצון זה נק' ע\"י והוא נחשב מסוף עולם הא\"ס ובחי' הרצון נק' א\"א והוא שרש וראש לנאצלים כידוע. והנה בחי' התענוג הזה שנמשך מתענוג העצמות ברצון זה מצד מקורו שנמשך משם נחשב מבחי' עצמות התענוג דבעצמות המאציל ומצד בחי' התלבשותו ברצון וחכמה כו' נקרא עונג מורכב ברצון באופן ודבר פרטי כנ\"ל דכלא חשיב לגבי אור תענוג העצמות כנ\"ל שיש בזה ב' צמצומים א' מצד ההרגשה כו' והב' מצד הכלי המגביל כו', ואמנם מבחי' עצמות התענוג שיש בעונג זה שירד ברצון הוא בחי' ג\"ר דע\"י ומובדל ומרומם בערך מהיות מקור וראש לנאצלים מטעם הנ\"ל וד\"ל. והנה התענוג המלובש ברצון בבחי' פנימיות נקרא חפץ כמו ארץ חפץ חפצי בה<sup data-n=\"1393\">79</sup> שלמעלה גם מטעם כמוס לרצון נקרא כתר דא\"א וטעם הכמוס לרצון נקרא חכמה סתימאה דא\"א כמ\"ש במ\"א<sup data-n=\"1394\">80</sup>, ובחי' כת\"ר דא\"א גם הוא מובדל בערך מהיות מקור לנאצלים רק מבחי' ח\"ס בחיצוניות שבו הוא שנחלק משם לג' קוין חח\"נ בג\"ה כו' כמ\"ש בפרדס<sup data-n=\"1395\">81</sup>, וזהו ענין בחי' חו\"ג דע\"י שמלובשים בכתר וחכמה דא\"א בחי' החסד שבתענוג העליון הנ\"ל שירד מן עצמות התענוג הפשוט מלובש בגלגלתא כת\"ר דא\"א וגבו' שבע\"י מלובש בח\"ס דא\"א כנ\"ל.\n[כד] <b>וביאור</b> הענין יובן עפ\"י הנ\"ל בבחי' עונג הנעלם ועונג המורגש שגם בתענוג המרומם בעצמות יש ב' מדרגות דאו\"י ואו\"ח שהן בחי' חו\"ג דע\"י כו'. והענין הוא דבחי' התענוג המרומם בפנימיות עצמותו הנ\"ל זהו בבחי' ג' ראשונות דע\"י כנ\"ל שנחשב ודאי מבחי' העצמות כנ\"ל, אך בחי' המדות שבו שמסתעפים הימנו שנק' חו\"ג הוא שיורדים ומתלבשים ברצון כנ\"ל, ועד\"מ הנ\"ל בהיותו מרומם בעצמות בתענוג מסתעף מזה מקור כל עונג",[["1392","78","<b>ותחי רוח יעקב</b>: ויגש מה, כז."],["1393","79","<b>ארץ חפץ חפצי בה</b>: מלאכי ג, יב. ישעי' סב, ד [וראה לעיל ח\"א ע' רל]."],["1394","80","<b>וטעם הכמוס. . ח\"ס דא\"א כמ\"ש במ\"א</b>: ראה ס' מאמרי אדהאמ\"צ בראשית ע' לו. תג. ויקרא ח\"ב ע' תקג. תתטז. דברים ח\"א ע' רכז. וש\"נ."],["1395","81","<b>חח\"נ בג\"ה כו' כמ\"ש בפרדס</b>: ראה ש\"ו פ\"א [ע\"פ זח\"ג קנג, ב. וראה ע\"ח ש\"א ענף ב']."]]],[1900420324,"המורגש, כמו שאנו רואים שמתעורר ברצון טוב להטיב בלי גבול כי חפ\"ץ חס\"ד הוא מצד רוממות תענוג העצמות ע\"כ עלה ברצונו להאציל כו', ונקרא בחי' עתיקא רעוא דכ\"ר שהוא בלתי מורגש ומורכב עדיין להיות נקרא מקור לנאצלים רק עלה ברצונו כו', וזהו נקרא כת\"ר דא\"א שמלובש בו בחי' חפץ חסד העצמי' דתענוג העצמות המרומם כו', וכאשר יבא עוד במורגש בטעם כמוס לרצון העליון הזה שנקרא ח\"ס דא\"א זהו כבחי' טוב טעם ותענוג הנרגש בטעם זה הכמוס הנה זהו בא מבחי' הגבורות דע\"י כו', וכנ\"ל בבחי' עונג המורגש שבא מצד ירידת עצמות התענוג המרומם כשיורד שהוא בלתי מוגבל בגדר כלי בבחי' עוצם הירידה בשפלות השחוק וריקוד ובמדו', אדרבה יהפוך טבע השכל והמדות כו' כנ\"ל (משא\"כ עונג המורגש הבא בבחי' הגבול והצמצום מורכב בדבר פרטי הנ\"ל שזהו בבחי' חיצוניות דח\"ס שבא לגילוי בדבר מה בשכל ומדות שנחלק לקוין ימין ושמאל כמשי\"ת), וכאשר הוא בבחי' עלי' והסתלקות כהתפעלות אה\"ר בתענוג מורגש לאו\"נ ולבסוף בכוסף כל הנפש ג\"כ בלתי מוגבל כלל כנ\"ל. ונמצא בבחי' גבו' דתענוג בהתלבשותו בטוב טעם כמוס לרצון יש בו ב' מדרגות שהן א' והיינו בחי' הירידה והמשכה למטה בגדר בלתי מוגבל באין מעצור כלל ובחי' העלי' והסתלקות בכליון כו' למעלה בבחי' או\"ח בלי שיעור כלל וד\"ל.\n[כה] <b>וזהו</b> שלפעמים בחי' הטעמים בכת\"ר ולפעמים בחכמה כידוע בענין טנת\"א<sup data-n=\"1396\">82</sup> דשניהם אמת לפי שהטעמים היינו בבחי' כת\"ר שבחכמ\"ה והוא טוב טעם ותענוג העליון הנעלם שברצון הפשוט שנקרא ח\"ס דא\"א (שהטע\"ם לפי פשוטו היינו בחי' תענוג כמו טוב טעם גשמי במתיקות וטעם הנרגש שבמאכל כמו חי\"ך יטע\"ם אוכל שהוא עונג הנרגש, אך טוב טעם ודעת למדני הוא ענין הב' בטעמים שהוא טעם אור השכל והחכמה כמו מ\"ט דר' כו' ונקרא טעם כמוס לרצון הפשוט וכמו טעמו וראו<sup data-n=\"1397\">83</sup> כו', ושניהם ענין א' רק שזה מורגש בחיך הטועם כו' וזה נעלם בטעם ושכל כמוס כו', וכלולים שניהם בנגינות וטעמים דאורייתא שהרי השיר וניגון בטעמים דזרקא כו' נק' עונג מורגש רק שהוא בלתי מוגבל בכלי שהרי נעלם מן השכל וחכמה עד שאין דרש נדרש בתשבע\"פ מן הטעמים כמ\"ש בגמ' ע\"פ ויבינו במקרא<sup data-n=\"1398\">84</sup> כו' שלזה הן",[["1396","82","<b>שלפעמי' בחי' הטעמי' בכתר ולפעמי' בחכמה כידוע בענין טנת\"א</b>: ראה לעיל ד\"ה אשר ברא (השני). וש\"נ."],["1397","83","<b>חיך יטעם אוכל. . טוב טעם ודעת למדני. . טעמו וראו</b>: איוב יב, יא. תהלים קיט, סו. לד, ט."],["1398","84","<b>בגמ' ע\"פ ויבינו במקרא</b>: נחמי' ח, ח: ויקראו בספר בתורת האלקים מפורש ושום שכל ויבינו במקרא. ובנדרים לז, ב: בספר תורת אלקים זה מקרא, מפורש זה תרגום, ושום שכל אלו הפסוקים, ויבינו במקרא זה פיסוק טעמים. ועד\"ז במגילה ג, א. ובס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תקפב: ולא מצינו שהי' דורש שום דרש על הטעמים ומ\"ש ויבינו במקרא ודרז\"ל אלו פסקי טעמים היינו שהבינו במקרא איך לפסוק הטעמים בקרא אבל לא טעם פיסוק הטעמים ואין בתושבע\"פ שום דרש ע\"ז כו' לפי שהטעמים הם בבחי' תענוג ושעשועי המלך בעצמותו כו'. ע\"כ. וראה גם לקו\"ת אמור לז, ב: ואין בתושבע\"פ שום ביאור על טעמים לבאר ולפרש לנו שירה זו מאי היא כו' [וע\"ש בציונים]. ובס' מאמרי אדהאמ\"צ שמות ח\"א ע' לב וע' ע [וע\"ש בהמ\"מ]. במדבר ח\"ב ע' תרלח הלשון ג\"כ כמו כאן."]]],[1900420325,"ע\"ג האותיות ומתחתיהם כו' בבחי' מקיף דחכמה והוא בחי' כת\"ר שבחכמה ונקרא טעם כמוס כו', ועכ\"ז השיר ורננה בטעמים בא בגילוי ובמורגש וכמו ויהי שיר\"ו<sup data-n=\"1399\">85</sup> כו' אע\"פ שהוא בבחי' ההעלם ומקיף דחכמה, וזהו טוב טעם ודעת שבהעלם החכמה למדנ\"י בגילוי כו' וד\"ל). וזהו שהטעמים בכת\"ר בבחי' העלם ומקיף דחכמה כנ\"ל ולפעמים בחכמה בבחי' גילוי טעם ועונג מורגש כשיר הנגינות כו' עד שנטעם בטעם ודעת בגילוי כמ\"ש טוב טעם ודעת למדני כו', והיינו ב' בחי' מדרגות דגבו' דתענוג העליון שבח\"ס א' בבחי' ירידה והמשכה למטה במורגש ובבחי' העלי' והסתלקות בבחי' העלם דמקיף כו', ושניהם א' וממקור א' באו והיינו בחי' התענוג הפשוט המרומם בעצמו שבא למטה בעונג מורגש בלי גבול בב' אופנים בירידה ועלי' שהן במשקל א' ממש כנ\"ל באריכות וד\"ל (אבל בחי' חסד שבתענוג הפשוט שנקרא חפ\"ץ חסד מצד הרוממות שבתענוג עצמותו כו' הוא מלובש בכת\"ר דא\"א שנקרא רעוא דכ\"ר כו' עת רצון שלמעלה מהיות בא במורגש בטעם כמוס או בשיר דטעמי הנגינות וכה\"ג רק שמחמת בחי' חפץ חס\"ד זה דוקא מסתעף מקור מוצא כל עונג ורצון לרצון דהיינו מה שמתעורר בכל רצון לטוב שזהו סיבת מה שעלה ברצונו להאציל כנ\"ל והיינו מה שמתלבש בכת\"ר דא\"א ולא בח\"ס כו' וד\"ל).\n[כו] <b>ובכל*</b> הנ\"ל יובן<sup data-n=\"1400\">86</sup> עכ\"פ כללות ההפרש בין חסד שבתענוג הפשוט שהוא נחשב מבחי' העצמיות דשעשועים העליונים שאינו בכלל ההרגשה כלל וכלל והוא מוגבה ומרומם בעצמותו רק מה שחפץ חסד הוא בעצמות התענוג הוא ששורה בכת\"ר דא\"א (שנחשב עדיין מבחי' עצמות המאציל כמ\"ש בפרד\"ס) אבל בחי' גבורה שבתענוג הפשוט הוא הבא בבחי' הרגש השעשועים (בחכמה שבכת\"ר שממנו שרש כל הנאצלים כידוע) רק שבלתי מוגבל בכלי וכלול מעלי' וירידה כנ\"ל וד\"ל, ובזה יובן טעם ענין המחלוקת של המקובלים אם החכמה בבחי' דין<sup data-n=\"1401\">88</sup> או בבחי' חסד [כמ\"ש בפרדס<sup data-n=\"1402\">87</sup>] והכריעו דשניהם אמת שלפעמים החכמה בבחי' דין וצמצום והיינו בבחי' עונג המורגש שבחכמה שבכת\"ר הנ\"ל שמלובש בו בחי' הגבורות שבתענוג הפשוט ואז דוקא נק' החכמה בשם עדן העליון כידוע והוא למעלה מבחי' התחלקות",[["1399","85","<b>ויהי שירו</b>: מלכים-א ה, יב."],["1400","86","<b>[כו] ובכל הנ\"ל יובן</b>: מכאן עד סוף אות ל\"ב, חסר בגוכי\"ק שלפנינו. ונשלם כאן ע\"פ כתבי-יד מעתיקים."],["1401","88","<b>המחלוקת של המקובלים אם החכ' בבחי' דין. . חסד (כמ\"ש בפרדס) והכריעו דשניהם אמת</b>: פרדס ש\"ח פ\"ה. ע\"ח שער א\"א (שי\"ג) ריש פ\"ו. ובתו\"א ה, ד: והחייט המציא שיש בה ג\"כ דין ושבחו האריז\"ל שכך מבואר בזוהר כו'. וראה בארוכה ביאוה\"ז להצ\"צ ע' תשיח ואילך. אוה\"ת שמות ע' ב'תקכד ואילך. ובכ\"מ."],["1402","87","<b>שנחשב עדיין מבחי' עצמות המאציל כמ\"ש בפרדס</b>: ראה ש\"ג פ\"א ואילך."]]],[1900420326,"הקוין דחח\"נ מימין כו' שמתחלק מחיצוניות דח\"ס כנ\"ל ולפעמים נק' החכמה בבחי' החסד כשיורד ונמשך בקו הימין חח\"נ בבחי' ירידה למטה דוקא וד\"ל.\n<b>ולהבין</b> ביאור הדברים הנה מבואר למעלה בענין הטעמים שלפעמים בכת\"ר ולפעמים בחכמה דשניהם אמת וכמו טעמים ונגינות שכלול מהעלם וגילוי עלי' וירידה כו', וכך יובן בענין חסד ודין שבחכמה בדרך כלל שהוא בחי' ירידה ועלי' והיינו כמ\"ש במ\"א ע\"פ פי' פתחה בחכמה<sup data-n=\"1403\">89</sup> ותורת חסד על לשונה שיש תורה של חסד ותורה של דין כמו שאנו רואים שיש בטבע החכמה להשכיל לחסד בכל מיני סברות עמוקות רק להטות כלפי חסד עד שיטהר גם הטמא כמו שטיהר בק\"נ טעמים כו', וזהו בחי' הירידה וההשפלה עד למטה גם בצמצום כח הדין שיותר למטה לעמוד לנגדו ולהפכו לזכות וחסד, וכמו\"כ יש בחכמה היפוכו להשכיל הכל בכל עמקות השכל רק למדת הדין עד שיחייב גם הזכאי ויטמא גם לטהור וכל אשר יטה השכל לחסד וזכות הכל יסתור וימצא חוב גם בדקות שבדקות ביותר עד שלא יצדק כלל כו', וזהו מבחי' הגבורות שבחכמה שהוא בבחי' העלי' דכח החכמה בעלי' והסתלקות היפך הירידה ושני הכוחות הללו נקראים תורה של חסד ותורה של דין, וז\"ש ותורת חסד דוקא דהיינו בבחי' הירידה למטה ביותר היא מפני שפי' פתחה בחכמה בפתיחה וגילוי דפתח בחכמה וקמץ בכתר כידוע<sup data-n=\"1404\">90</sup> ופי' פתחה בחכמה תתאה בדיבור זהו בבחי' ירידת אור החכמה עילאה שבא מבחי' החסדים שבחכמה שזהו הנקרא תורת חסד דוקא וד\"ל, ולהיפך בחי' הדין שבחכמה הוא ענין העלי' והסתלקות שהוא בסתימת* דמקיף דכת\"ר<sup data-n=\"1405\">91</sup> דחכמה בהעלם דמקיף דחכמה שלא בא בדיבור בפה ונקרא ח\"ס כידוע וכמשה שהי' כבד פה כו' והיינו ממש כמו ענין הנגינות שהן בהעלם דמקיף בסת\"ר המדריגה ובאים בגילוי הניגון כלול מעלי' וירידה במקום א', שנמצא מובן מזה שגם חו\"ג דחכמה שנקראים תורה של דין ותורה של חסד הם גם במקום א' והיינו בח\"ס רק שזהו בעלי' וסתימות וזה בירידה וגילוי והא בהא תלי' ואינם ב' הפכים כלל אע\"פ שנראים כמו חו\"ג הפכיים בהטי' כלפי זכות או חוב כנ\"ל אבל בשרשם מכח אחד באו דלפי ערך העלי' כך ערך הירידה ממש במשקל א', ואמנם זה מבחי' פנימיות דח\"ס שבלתי יורד אלא עולה וזה מחיצוניות דח\"ס שיורד ואינו עולה וכו' והא בהא תלי' והי' לאחדים ממש והיינו שמכריע במחלוקת הנ\"ל דשניהם אמת שהחכמה בבחי' דין בעלי' והעלם למעלה מבחי' התחלקות הקוין כו', וגם החכמה בבחי' החסד בירידה וגילוי למטה בהתחלקות",[["1403","89","<b>במ\"א ע\"פ פי' פתחה בחכמה</b>: משלי לא, כו. ס' פירוש המלות לכ\"ק אדהאמ\"צ קכח, א. וראה אמרי בינה ח\"ג קכח, סע\"א [ובהמ\"מ שם]."],["1404","90","<b>דפתח בחכמה וקמץ בכתר כידוע</b>: תקוני זהר ת\"ע (קכט, ב). ע\"ח ש\"ח פ\"א. סה\"מ תקס\"ב ח\"ב ע' שמא. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תקפה."],["1405","91","<b>בסתימת דמקיף דכתר</b>: בכת\"י ב: דסתימו דקמץ בכתר."]]],[1900420327,"קוין כו' ואינם ב' הפכיים כלל בעצם שרשם אע\"פ שנראים למטה מחולקים בחו\"ג כנ\"ל וד\"ל.\n[כז] <b>ולהבין</b> זה בתוס' ביאור הנה יש להקדים ענין א' והוא במה שחכמה נקראת עדן<sup data-n=\"1406\">92</sup> דוקא בהיותה למעלה מן ההתחלקות בקוין כו' שהוא בחי' הדין<sup data-n=\"1407\">93</sup>* שבחכמה סתימאה, דהנה לכאורה ענין זה סותר למ\"ש למעלה דבחי' גבורות שבתענוג בא בהרגש כו' וגבורה זו הוא שמתלבש בח\"ס<sup data-n=\"1408\">94</sup>* ואיך הוא בבחי' הדין שבחכמה שהוא בהעלם ועלי' כנ\"ל ואם הוא בבחי' ההעלם ודין וצמצום איך נקרא עדן במורגש העונג כו', אך י\"ל תחלה בשרש ענין ח\"ס הנ\"ל דהנה ידוע ומבואר במ\"א בביאור ענין ח\"ס שהוא מקור מוצא כל גילוי השכל והתחכמות בדבר מה שנקרא בשם משכיל לכל שכל כו', וזהו ודאי מבחי' החסד שיורד להשכיל שכל בגילוי הטעם כו' וא\"כ איך יקרא בלשון סתימות ח\"ס כו', אך הנה אנו רואים שינויים בכח המשכיל הזה שלפעמים ישכיל שכליי' ולפעמים לא יוכל להשכיל מהעלם לגילוי כו' וזה תלוי בבחי' אור התענוג שמתלבש במשכיל זה שאז ישכיל ויוליד שכל חדש אבל מצד עצמו הי' נשאר בבחי' העלם והסתימות<sup data-n=\"1409\">95</sup>*, וזהו מבחי' גבורות שבתענוג העצמי הנ\"ל דוקא שכל בחי' גבורות הוא משפיע ומוליד כו' כמו שטבע החמימות יוליד ולא מהקרירות דמים שלא יוליד וישפיע כו' לכך מבחי' החסד שבמשכיל לא הי' מוליד שכל חדש אע\"פ שהחסד יורד כו' אבל להוליד מושכל חדש צריך להיות מבחי' הגבורות דוקא (כמו שמבחי' הגבורות שבתענוג שבא בחמימות בטפה שבמוח דוקא יוליד ולא מחלק החסדים שבו<sup data-n=\"1410\">96</sup> שבא בקרירות לא יוליד וכמ\"ש במ\"א<sup data-n=\"1411\">97</sup>), וזהו ענין העונג הנרגש במושכל החדש שהמציא מכח המשכיל שמרגיש בו עונג נפלא מאד שאינו לפי ערך המצאות השכל בעצם כלל ועוד שהעונג מהות נבדל הוא ממהות השכל ומה שייך חיבור העונג בשכל עד שירגיש עונג גדול כשהמציא מושכל חדש אלא עונג זה הנרגש במציאות<sup data-n=\"1412\">98</sup> השכל הגבה למעלה הוא בעצם ממהות השכל רק שירד והושפל בהתלבשות בשכל כאילו מתענג רק מצד עצם טוב ההשכלה כו' ובאמת שרש עונג הזה הוא למעלה גם מבחי' המשכיל מקור שכל זה כי הוא נמשך מעצמות התענוג וירד והושפל בכח המשכיל שיוציא מושכל זה ויולד אותו מהעלם לגילוי מציאות*, וע\"כ אנו רואים במי שהמציא מושכל חדש שיאירו פניו מאד כענין חכמת אדם תאיר פניו<sup data-n=\"1413\">99</sup> פי' חכמת אדם בחי' ח\"ס שנק'",[["1406","92","<b>שחכמה נק' עדן</b>: פרדס שער ערה\"כ מע' עדן."],["1407","93","<b>הדין</b>: בכת\"י ב: הימין."],["1408","94","<b>בח\"ס</b>: בכת\"י ב: בחכ'."],["1409","95","<b>והסתימות</b>: בכת\"י ב: והתחלקות."],["1410","96","<b>שבו שבא</b>: בכת\"י ב: שהוא בא."],["1411","97","<b>בקרירות לא יוליד וכמ\"ש במ\"א</b>: ראה ס' מאמרי אדהאמ\"צ שמות ע' תא. וש\"נ."],["1412","98","<b>מציאות</b>: בכת\"י ב: עצמות."],["1413","99","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א. וראה גם לעיל ח\"א ע' צב ואילך."]]],[1900420328,"משכיל והיינו מה שהוציא חכמה חדשה מכח המשכיל שלו נק' חכמת אדם והוא שתאיר פניו בשעה זו מאד כמו ר' אבהו שמצא תוספתא חדשה וצהבו פניו<sup data-n=\"1414\">100</sup> כו', ואור פנים זה היינו רק מבחי' גילוי אור התענוג העצמי דוקא שהאיר בכח המשכיל להוליד החכמה וע\"כ יאירו פניו ולא מצד עונג זה הנרגש בשכל זה הפרטי שהרי יאיר פניו גם אחרי שלמד והשכיל כמ\"ש במ\"א בענין תיקון ואמת<sup data-n=\"1415\">101</sup> שזהו בחי' תרין תפוחין כו' שהוא הארת הפנים דחכמה היינו בחי' גילוי העצמיות והפנימיות כמו שהוא בלא לבוש וצמצום רק שמלובש האור התענוג העצמי והפנימי באור הפנים, וז\"ש באור פניך נתת לנו כו' דבשעת מ\"ת הי' בחי' גילוי אור התענוג ושעשועי המלך כמו שהוא בעצמותו בפנים העליונים מטעם חכמת אדם בהשכלתו המושכל מחכמה חדשה תאיר פניו כו' וד\"ל.\n[כח] <b>וזהו</b> שחייב להקביל פני רבו ברגל<sup data-n=\"1416\">102</sup> דוקא שמקבל אור פני המשפיע שבו מלובש עצמות התענוג להיות כח ועוז למשכיל להוליד שפע שכל חדש למקבלים והוא הטעם לעולי רגל לראות את פני ה' בהשתחוואה כו' דבקבלת אור פני מלך במועדי הוי' כו' יומשך ממילא כל אור ושפע דתורה ומצות בנש\"י כל השנה מטעם הנ\"ל, וכך הי' במ\"ת שראו אור פני מלך כו' כמ\"ש פב\"פ דיבר ה' עמכם באור פניו נסתכלו וקיבלו מעצמות השעשועים שבאור פניך כו' ואע\"פ שנאמר וירא וינועו שעל כל דיבור ודיבור פרחה נשמתן<sup data-n=\"1417\">103</sup> כו' מ\"מ זה הי' הגורם שיקבלו אור דתו\"מ בגילוי בכלים מכלים שונים בדיבור ובכתב לפי שמשם מקור מוצא כל אור חכמה הבא בתולדה מהעלם לגילוי והיינו ע\"י בחי' כח גבורה שבתענוג הפשוט שמאיר בחכמה סתימאה, וזהו בחי' התלבשות כח דגבורה שבתענוג בחכמה סתימאה שנק' משכיל הוא שנקרא בשם עדן דוקא שהוא עונג הנרגש כו' אע\"פ שהגבורות הוא<sup data-n=\"1418\">104</sup> בחי' התענוג הפשוט הרי הוא בחי' דין דחכמה כנ\"ל, דהנה מבואר למעלה דגבורות שבתענוג הוא הבא בבחי' הרגש השעשועים כך מעצמיות התענוג יורד ונשפל קצת מזה בבחי' ההרגש עונג והוא הנקרא עדן עילאה שהוא בבחי' פנימיות ח\"ס שבבחי' דין אע\"פ שלגבי עצמיות התענוג הוא בחי' צמצום ההרגש ונקרא בחי' דין וצמצום והעלם מקור שכל לגבי החכמה שלמטה אין זה בבחי' עלי' והסתלקות לגמרי אלא אדרבה ממנו מקור כל שפע ותולדה של השכל מן המשכיל (כמו כל בחי' גבורות שמפני שהן בבחי' רשפי אש וחום ע\"כ הן עיקר",[["1414","100","<b>ר' אבהו. . וצהבו פניו</b>: ראה לעיל סוד\"ה משמח חו\"כ, וד\"ה להבין מה שבברכה ראשונה (אות כ\"ז). וש\"נ."],["1415","101","<b>כמ\"ש במ\"א בענין תיקון ואמת</b>: ראה לעיל ח\"א ע' צג. וש\"נ."],["1416","102","<b>וזהו שחייב להקביל פני רבו ברגל</b>: ר\"ה טז, ב. וראה לעיל שם. וס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תמ. תנג. ויקרא ח\"א ע' קעח. במדבר ח\"ה ע' א'תתפב. דברים ח\"ב ע' תקג."],["1417","103","<b>פב\"פ דיבר ה' עמכם. . וירא וינועו. . פרחה נשמתן</b>: ואתחנן ה, ד. יתרו כ, טו. שבת פח, ב."],["1418","104","<b>הוא בחי'</b>: בכת\"י ב: בבחי'."]]],[1900420329,"הירידה להשפיע ולהחיות לזולתו כו') שהרי העונג הנרגש הזה מוליד שכל חדש מן המשכיל כנ\"ל וכל הולדה הוא שפע וירידת אור למטה (וכן במה שחכמת אדם תאיר פניו כנ\"ל שזהו עונג העצמות הנרגש בפנים אע\"פ שאינו רק צמצום הרגש עונג העצמי ואפס קצהו מ\"מ ממנו מקור כל מוצא שפע אור וחיות למקבלים וכמו באור פניך נתת לנו אך שבפנים הוא בלי לבוש מסתיר אבל דרך ירידה בא כמו שיורד להאיר בבחי' משכיל להוליד שכליים כנ\"ל. ונמצא דהרגש העונג הבא דרך ירידה וצמצום מן העצמות הוא בבחי' דין והוא הנקרא עדן מקור לכל המקבלים העונג אלקי כו' וד\"ל.\n<b>ובכ\"ז</b> יובן שדעת שניהם אמת שהחכמה נק' דין ונק' חסד והא בהא תליא כנ\"ל בענין תורה של דין ותורה של חסד כו', דלגבי עצמות המשפיע בעצמות העונג הרי זה העונג בא בבחי' הרגש וצמצום אבל מזה עצמו בא בחי' ירידת אור ושפע החסד שהוא כמו הולדת החכמה בגילוי מאין דחכמה הנק' משכיל ומשם נמשך לקו הימין חח\"נ מעילה לעילה עד שנמצא החכמה גם במדות ודיבור ומעשה כמ\"ש כולם בחכמה עשית<sup data-n=\"1419\">105</sup> כו' כמים שיורדים מגבוה לנמוך כו' וד\"ל, והיינו דרך כלל מבחי' גבורה דע\"י שבחכמה נמשך בחי' חסדים דאבא וכמו שמבחי' גבורות דאבא נמשך בחי' חסדים דאימא כו' מאחר שהמקבל אין לו ערך כלל עם העליון המשפיע א\"כ מה שנק' גבורה וצמצום בעליון הוא דוקא נעשה בחי' חסדים למקבל התחתון כי המקבל לא יוכל לקבל רק מבחי' הצמצום וההרגש שבעליון וגם להיותו עיקר בחי' המשפיע והמחי' לזולתו כנ\"ל ע\"כ מבחי' גבורות שבעונג העליון הנרגש בפנימיות ח\"ס כנ\"ל הוא שנעשה מקור כל קו הימין שהוא רב חסד דבי' אחיד אבא ומחכמה לחסד שבמדות עד חסד שבמעשה שזן ומפרנס כו' וד\"ל.\n[כט] <b>ועתה</b> י\"ל שרש ענין הדבש הנ\"ל שהוא בחי' דין דגדלות כו', פי' דין דגדלות היינו בחי' הצמצום והדין שאצל המשפיע שנק' גדלות נק' דין דגדלות והוא באמת עיקר מקור השפע וחיות לתחתון המקבל וכנ\"ל באריכות כמשל הולדת מושכל חדש מכח המשכיל שבא מחמת בחי' הדין והצמצום דגבורות דתענוג שבח\"ס כו' וד\"ל.\n<b>ולהבין</b> זה בתוס' ביאור יש להקדים תחלה במה שבחי' גבורות דע\"י שמלובש בח\"ס כנ\"ל הוא הנק' בשם מאמר קו המדה והוא הנק' בזוהר בשם משחתא והיינו בחי' בוצינא דקרדוניתא<sup data-n=\"1420\">106</sup> שהוא ה\"ג דע\"י שבפנימיות ח\"ס כנ\"ל, ויש להבין מהו ענין קו המדה הזה ולמה הוא דוקא",[["1419","105","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["1420","106","<b>מאמר קו המדה. . בזוהר בשם משחתא. . בוצינא דקרדוניתא</b>: ראה זח\"א טו, א. זח\"ב רלג, א [וביאוה\"ז לשם — נז, ד ואילך]. תקוני זהר תיקון ה' (בתחילתו)."]]],[1900420330,"בבחי' גבורות שבתענוג שבח\"ס כו', והנה יש בקו המדה זה ב' ענינים הפכיים א' הצמצום במה שהוא במדה ושיעור לא יותר והב' גוף השפע שנמשך עכ\"פ רק שנמשך במדה והיינו התכללות דחו\"ג במדה לא יוסף ולא יפחות כו', וכמו\"כ נאמר מי מדד בשעלו מים שהוא החכמה מי אסף רוח שהן המדות כו', דהחכמה שמאין תמצא בא ע\"י מדידה שנמשך במדה ושיעור לא יוסיף ולא יפחות כו' וכמו החכמה שבתורה שנמדדה במדה ושיעור לא יוסיף ולא יגרע כמו טעם וחכמה ושכל שבמצות תפילין שיהיו נעשים כך וכך ולא באופן אחר הרי נמשך חכמה זאת עפ\"י קו המדה ע\"כ בא בדקדוק כך ולא כך, וכך כל המצות נמדדו במדה עפ\"י החכמה שנק' חכמה ברורה בדקדוק ושיעור כמ\"ש כל אמרת ה' צרופה<sup data-n=\"1421\">108</sup> כו' וע\"כ לא תוסיף על דבריו ולא תגרע, וזהו שהזהירו בכמה מקומות שלא יסור ימין ושמאל שלא להוסיף בבחי' ימין דחסד ולא לגרוע בשמאל דדין ודרך כלל רמ\"ח מ\"ע הן ה\"ח במדה ושיעור בל יוסיף ושס\"ה ל\"ת בחי' ה\"ג במדה שכל ריחוק דסור מרע בא ג\"כ במדה כמו קירוב דוע\"ט בא במדה באופן כך וכך דוקא, וכ\"ז רק מצד בחי' המדידה דח\"ע שבתורה כו' וכן המדות דתורה כשר פסול חייב זכאי כו' הכל במדה ושיעור כו', וז\"ש מי מדד בשעלו מים דח\"ע ומי אסף רוח דמדות כו' ומי הקים<sup data-n=\"1422\">107</sup> כו' דהיינו שפע קיום העולמות בכללות כל ההשתלשלות דאבי\"ע הכל בא במדה ושיעור מעילה לעלול הימנו שנמדד במדה כמה ישפיע וכמה יעכב ולא יוסיף ולא יפחות כו', וכן בכל העלאה והמשכה שנק' העלאת מ\"ן והמשכת מ\"ד נק' יחוד וזיווג היינו כמו עילה ועלול שהעלול התחתון מעלה מ\"נ ואז יורד אליו ההמשכה כפי ערך ההעלאה לבד הרי יש בזה ג\"כ מדידה כמה יהי' ההעלאה וההמשכה כידוע, ושרש כל המדידות הללו בא מבחי' גבורות דע\"י שבח\"ס הנ\"ל שנק' קו המדה עד\"מ אמת הבנין שמודד באמה זו כמה אמות יהי' האורך וכמה אמות יהי' הרוחב כו' כמו אורך היריעה האחת כו' וכן בקרשים שזהו המדידה באורות מקיפים ופנימיים כו' וכמ\"ש<sup data-n=\"1423\">109</sup> בזוהר ומבואר במ\"א, וכן מודד לכל אור וכלי או היכלות ולבושים וכמו אמת הבנין שמודד כמה יהי' אורך ורוחב הבנין או החדר כו' והרי סיבת הקצבה וגבול בכל חדר ובכל היכל ולבוש ואו\"כ פנימים ומקיפים הכל מאמת הבנין דקו המדה שמודד את הכל והוא עצמו אינו מן המדה כ\"א שהוא מודד כל מדה ושיעור הצריך בכל ההשתלשלות מעילה לעלול ובאו\"כ והיכלות כו', וגם בח\"ע דתו\"מ ומדות דחו\"ג עד המעשה בפ\"מ כנ\"ל וד\"ל.",[["1421","108","<b>כל אמרת ה' צרופה</b>: ע\"פ משלי ל, ה."],["1422","107","<b>מי מדד בשעלו מים. . מי אסף רוח. . ומי הקים</b>: ישעי' מ, יב. משלי ל, ד: מי אסף רוח בחפניו מי צרר מים בשמלה מי הקים כל אפסי ארץ."],["1423","109","<b>אורך היריעה האחת. . וכמ\"ש בזוהר ומבואר במ\"א</b>: תרומה כו, ח. ראה זח\"ב רלג, א. ביאוה\"ז נח, ד. ס' מאמרי אדה\"ז על מארז\"ל ע' שכט."]]],[1900420331,"[ל] <b>והנה</b> הטעם לכל זה היינו לפי שבאמת י\"ל בגוף ענין ההשתלשלות דעו\"ע איך יושפל אור השפע מכל עילה לעלול מאחר שאין ערוך ביניהם ועוד שטבע כל עילה לידבק בעליון הימנו שנק' עלול לגבי', וכך עד\"ז כל עילה שנק' עלול וכל עלול בטל ונדבק למעלה הימנו ואיך יקרא משפיע לתחתון הימנו הרי טרוד למבלע לא פליט כלל כו', ועוד שהרי כל אורות הנאצלים מן המאציל המה במהות אור עכ\"פ והאור טבעו להסתלק וליכלל למעלה כאש שעולה ונכלל במקורו באש היסודי וא\"כ הי' כל אור הנאצל חוזר למקורו במאציל מאחר שנשפעים בבחי' גבורות כטבע האש כו', וא\"כ איך יהי' בטבע כל עילה להשפיע לעלול שזהו דרך ירידה והשפלה היפך העלי' וההסתלקות כו' וזה פלא גדול דמי הוא המעכב לאור הנאצל מלהסתלק למקורו ומה גם עוד זאת שיוכל להיות בהיפך מזה שהוא בהיפך טבעו להיות יותר יורד ונמשך בשפע מלמעלה למטה לעלול כו'. אך הנה הענין הוא שבאמת גם זה בא בכל אור הנאצל כמו טבע שיהי' בו העונג כטבע הטוב לירד למטה הימנו ולהשפיע ולהחיות כמו שיש בטבעו לעלות למעלה (כאור הנר שיורד ומתמשך למטה בפתילה ועץ להחזיקו ולכל דבר יתאחז ומכ\"ש בשמן כו') ובחי' טבע הטוב הזה שהוטבע בכל עילה להשפיע שרשו בבחי' גבורות דוקא ואע\"פ שבטבע הגבורה לעלות כאש אמנם אין זה עלי' והסתלקות לגמרי אלא אדרבה שמחמת זה בא יבא בירידה והמשכה מלמעלה למטה להשפיע ולהחיות לשלמטה הימנו (כענין יותר משהעגל כו' הפרה רוצה להניק כו' וכמ\"ש במ\"א<sup data-n=\"1424\">110</sup>) הוא בא במדה ושיעור דוקא ולא יוסיף ולא יפחות כנ\"ל, וזהו מבחי' גבורה שבתענוג העליון הפשוט שנק' גבורות דע\"י שנק' קו המדה היינו שמודד כל מדה ושיעור של כל עילה כמה יהי' בו חשק בחי' הירידה וההשפלה מן העצמות להשפיע אור וחיות לעלול התחתון כו' והוא המדה ושיעור בכל בחי' גבורות שבכל עילה כמה יומשך כו', ויש בזה ב' הפכיים ירידת השפע שהוא בחי' החסד עכ\"פ ומדתו של השפע להגבילו שלא יהי' יותר שכל זה בא ממקור כל הגבורות שהוא בחי' ה\"ג דע\"י שנק' קו המדה שמודד את הכל כנ\"ל שהוא מקור המדידות וכללות ההשתלשלות דע\"ס מכת\"ר לחכמה ומחכמה למדות כו' (ועד\"מ כמה יומשך מן הרצון שלמעלה מן הטעם להשפיע בחכמה שהוא הטעם לרצון לא יוסיף כו' וכמה יומשך מן השכל והטעם שלמעלה ממדת האהבה להשפיע במדת האהבה וחסד וכמה יהא הירידה מן המדות מזה לזה דהיינו עד נו\"ה ומנו\"ה ליסוד כו', וכמה יהי' נמשך מיסוד למלכות שהוא המחשבה ודיבור עד בחי' המעשה שכ\"ז דרך עו\"ע כידוע), והטעם שהוא בגבורה דע\"י בפנימיות ח\"ס דוקא היינו לפי שהוא בחי' גבורה שבחסד<sup data-n=\"1425\">111</sup>* כו' שהוא עונג הנרגש שממנו מקור כל גילוי אור דחכמה מאין",[["1424","110","<b>יותר משהעגל. . וכמ\"ש במ\"א</b>: פסחים קיב, א. ראה לעיל ע' שצד ואילך. וד\"ה קול מצהלות (קרוב לסופו). ובס' מאמרי אדהאמ\"צ: ויקרא ח\"ב ע' תרל. במדבר ח\"א ע' צז. דברים ח\"א ע' רפז [ובהמ\"מ שם]."],["1425","111","<b>שבחסד</b>: בכת\"י ב: שבח\"ס."]]],[1900420332,"דכת\"ר כנ\"ל אע\"פ שהוא בבחי' צמצום לגבי העצמות דתענוג, אמנם זה עצמו הגורם בחי' ירידתו לגבי התחתון וכנ\"ל דכל בחי' גבורות דוקא המשפיע ומחי'<sup data-n=\"1426\">112</sup>* היפך ההסתלקות כו' וד\"ל, אך עדיין י\"ל בזה דאם מבחי' הגבורות דוקא יבא אור ושפע להחיות לזולתו היינו מצד בחי' הלב* התגברות כחו בחסד<sup data-n=\"1427\">113</sup> אבל איך אפשר שסיבת ירידתו להשפיע יבא דוקא מבחי' הצמצום והדין שבו כנ\"ל דאיך יולד דבר מהיפוכו כו'.\n[לא] <b>אך</b> הנה יובן ע\"ד דוגמא מן המשפיע ומקבל דתינוק ואשה שגזרו אומר דצריך להיות שמאל דוחה וימין מקרבת כו' וי\"ל למה הקדים שמאל דוחה לימין מקרבת הרי הקירוב הוא עיקר השפע הל\"ל ימין מקרבת ושמאל דוחה דימין קודם לשמאל בכל מקום, אך צריך לומר דשמאל דוחה קודם כדי שיוכל להיות ימין מקרבת אח\"כ דוקא, והענין הוא דעיקר קיום השפע למקבל שיעמוד בה ולא יסוג אחור בימין שמקרבת אותו הוא ע\"י שמאל דוחה לרחק תחלה דהדחי' הוא בחי' הדין והצמצום שמצמצם ומעכב מהראות לו חיבה יתירה, הנה בזה יתקיים המקבל בשפע שיקבל ע\"י ימין מקרבת אח\"כ דאם לא הי' שמאל דוחה כלל יבעט המקבל בסיבת הקירוב דימין ביתר ממדתו ברוב עוז שלא יוכל לעמוד ברוב טובה זו שאינה לפי המדה וע\"כ לטובת המקבל דוקא כדי שיקבל ויעמוד ויתקיים בו הטוב והחסד ירחקנו תחלה בשמאל דוחה ואמנם הדחי' בא במדה ובשמאל<sup data-n=\"1428\">114</sup>* ולא בימין, ונמצא שאין השמאל דוחה רק בשביל ימין מקרבת ולזה הקדים שמאל דוחה לימין מקרבת לפי שערך קיום השפע דימין רק לפי אופן הדחי' דשמאל קודם והא בהא תלי' והרי עיקר החסד שבא בימין מקרבת הוא הדחי' דשמאל כו' ונק' גבורות שבחסד שהוא עיקר החסד כידוע וד\"ל, וא\"כ יובן דמבחי' גבורות דמשפיע שהוא כמו הדחי' בשמאל יבא קיום אור החסד למקבל, וזהו אינו מדבר והיפוכו כלל רק אדרבה ענין א' הוא ממש וזה גורם לזה כו', וכך יובן בענין הנ\"ל דמבחי' גבורות שבתענוג והוא הצמצום וההעמדה שנק' קו המדה הוא שבא סיבת ירידת החסד באופן הקיום בל ימוט כו' וד\"ל.\n<b>ובכ\"ז</b> יובן ענין המדידה שכלול מדבר והפוכו צמצום והתפשטות שהצמצום קיום ההתפשטות ושניהם כאחד נמשך מבחי' קו המדה הנ\"ל, וזהו שיש בכל עלול בחי' ההעמדה וקיום בעצמו ולא יוכלל במקורו ואדרבה משפיע למטה כו' דזהו בא מבחי' שמאל דוחה דמשפיע דוקא לפי שענין הדחי' הוא שהמשפיע דוחה למקבל מעצמותו בריחוק שמרחק למקבל וע\"י הריחוק זה יתקיים השפע במקבל שמקבל בימין כו' ולא יחזור למקורו היות שנתרחק",[["1426","112","<b>ומחי'</b>: בכת\"י ב: ובחי'."],["1427","113","<b>הלב התגברות כחו בחסד</b>: בכת\"י ב: רוב ההתגברות בחסד."],["1428","114","<b>ובשמאל</b>: בכת\"י ב: ושיעור."]]],[1900420333,"תחלה ע\"י שמאל דוחה, אבל אם הי' הכל בימין מקרבת הי' כל עלול נמשך ונדבק תמיד אל העילה ליכלל בו כבן לאב כו', וכך יובן שיש בחי' גבורות עליונות למעלה שנק' שמאל דוחה לעלול כדי שע\"י דחי' זו שמעצמות המשפיע יהי' קיום האור למקבל, וזהו בחי' דין דגדלות שקודם לחסד דמשפיע דוקא והוא עיקר המעמיד ומקיים השפע במקבל שלא יכלה בעליון הימנו כו' וד\"ל. וזהו ענין הדבש שמכווץ הדבר ע\"י בחי' הגבורו' שבו לבלי יכלה במקורו וכנ\"ל בענין ואתה משמרה בקרבי באריכות שזהו רק בחי' הכיווץ דמשפיע בדחי' שדוחה ומכווץ מלמעלה למטה למקבל שעי\"ז מונע אותו מליכלל ולהסתלק במקורו כו' והוא ענין השימור שמכווץ הנשמה בגוף שהוא מבחי' שמאל דוחה דמשפיע כדי שיתקיים בגוף ושרשו מבחי' גבורות שבחסד שבא במדה במאמר קו המדה כנ\"ל, וזהו שרש ענין הדבש בחי' דין דגדלות במשפיע הכללי שהוא גבורות דע\"י בח\"ס<sup data-n=\"1429\">115</sup> שלמעלה מהתחלקות הקוין ומשם נמשך גם לבחי' המדות דז\"א עם המוחין שבו וכמ\"ש מי אסף רוח כו' ששם ג\"כ יש יחוד משפיע ומקבל דת\"ת ומל' בשמאל דוחה וימין כו' במדה ושיעור דוקא ושרש שמאל דוחה שבז\"א כמ\"ש שמאלו תחת לראשי<sup data-n=\"1430\">116</sup> כו' בא מבחי' ה' גבורות דבוצינא דקרדוניתא בחי' קו המדה שבחכמה סתימאה הנ\"ל וד\"ל.\n[לב] <b>וגם</b> בכ\"ז יובן מה שיש בטבע הדבש להפוך מרירא למיתקא שזה מה שיש בכח הגבורות שבחסד דוקא להפוך המנגד ואין זה הכח בחסד עצמו כו' לפי שבחי' גבורה שבחסד כולל דבר והיפוכו חו\"ג צמצום והתפשטות כנ\"ל בענין שמאל דוחה שזהו עיקר קיום ימין מקרבת וע\"כ גם בחי' גבורות הקשות שנאחזים בקו השמאל נמתקו לחסדים ע\"י בחי' גבורה שבחסד הנ\"ל דוקא לפי שאין מיתוק הדין אלא בשרשו<sup data-n=\"1431\">117</sup> דוקא במקור כל הגבורות עליונות והוא בבחי' הגבורה דשמאל דוחה שעיקרה בחי' חסד, וכמו יסורים של אהבה שהוא שמאל דוחה מלמעלה כדי שיתקיים בחסד עליון דימין מקרבת ובזה נמתק כל דין וקטרוג שלא יפעול דין קשה באמת מאחר שאין הכוונה בשרש שרשו למעלה רק בשביל החסד וכמ\"ש אשר יאהב יוכיח כו' אשרי הגבר<sup data-n=\"1432\">118</sup> אשר כו' וכה\"ג וד\"ל. וזהו שבכח הדבש דוקא להפוך המנגד שהוא דבר המר להיות מתוק (וכחידות שמשון מעז דוקא יצא מתוק ומהאוכל [הכלי] שהוא בחי' דין יצא כל מאכל כו' מטעם הנ\"ל, וזהו שהשיבו לו מה עז מהארי<sup data-n=\"1433\">119</sup> והוא להיותו",[["1429","115","<b>בח\"ס</b>: בכת\"י ב ליתא."],["1430","116","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["1431","117","<b>שאין מיתוק הדין אלא בשרשו</b>: ראה לעיל סוף אות י\"ב. וש\"נ."],["1432","118","<b>יסורים של אהבה. . אשר יאהב יוכיח. . אשרי הגבר</b>: ברכות ה, א. משלי ג, יב. תהלים צד, יב: אשרי הגבר אשר תייסרנו י\"ה."],["1433","119","<b>וכחידות שמשון מעז. . מה עז מהארי</b>: שופטים יד, יד. יח. וראה גם ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תפד וע' תקג."]]],[1900420334,"בקו הימין דפני ארי' להימין ה\"ז בחי' גבורה שבחסד<sup data-n=\"1434\">120</sup> ולזה א' ע\"ז ומה מתוק מדבש שיכול להפוך מר למתוק כו' וד\"ל).\n<b>ובכ\"ז</b> יובן הטעם בכל המשכות י\"ג מדה\"ר די\"ג תיקונין דדיקנא שהן מבחי' גבורות תקיפין דשערות והן ממתיקין כל הדינין הקשין דאדרבה הוא הנותנת משום דשרשם בגבורות דע\"י שבח\"ס כו' והיינו בחי' הארת פנים דא\"א שכולל י\"ג תקונין דדיקנא כו' שהוא ג\"כ מבחי' עונג העצמי שבא בהרגשה כו' וע\"כ ממתיק כל דין קשה דקטרוגים שנק' גבורות קשות עד שהקללה נהפך לברכה כו', וגם בזה יובן הטעם מה שכל שורש הברורים דרפ\"ח כו' בעה\"ד טו\"ר לאהפכא חשוכא לנהורא ומרירו למיתקא שהרע עצמו דתייסרך רעתך נהפך לטוב וחסד כו' והיינו דוקא מגבורות דח\"ס הנ\"ל דבחכמה אתברירו<sup data-n=\"1435\">121</sup> להיות בדין דגדלות ע\"כ מהפך המנגד דוקא להאיר גם את החושך ולהמתיק המרירות כו' וד\"ל (וגם בחי' הכלים דאח\"פ דא\"ק עד\"ז מבחי' הגבורות שבחסד העצמות אך הוא למטה מבחי' הבירורים דרפ\"ח כו').\n[לג] <b>ומעתה</b> יש להבין שרש ענין חלב דיניקה הנ\"ל. והנה יש להקדים תחלה ביאור ענין מוחין דיניקה למה נק' בשם מוחין הלא בימי היניקה אין בולד מבחי' המוחין שבמדות כלל ואפי' מוחין דקטנות אין בו, וגם אחר ימי היניקה אין בו מוחין רק בחי' קטנות המדות לבד כמו שחפצו ואהבתו בדברים קטנים מאד כו' כידוע. והנה בפרדס מבואר בענין ג' מדרגות שיש במדות עצמן היינו הנק' מושכל מורגש מוטבע<sup data-n=\"1436\">122</sup> והיינו בחי' חב\"ד חג\"ת נה\"י שהוא הכל במדות עצמן, ובחי' מוטבע היינו טבע המדות כמו שהן בתולדה מבטן (בל\"א נאטור) רחמני או אכזרי קמצן או פזרן רך הלבב או קשה וכה\"ג שפלות או התנשאות חדוה או עוצב וכללותו היינו אם טוב או רע, וגם בכל המדות פרטיות כמו באהבה וניצוח והתפארות הכל נולד בטבע באופן פרטי בכל א' וא' ואין א' דומה לחבירו כלל כידוע, אך שמהות המדות כמו שמוטבעי' בתולדה מבטן עדיין לא ניכר ונגלה כלל כי לא יוכר הנער בימי היניקה איך הוא בטבע לבו רך או קשה או קמצן או פזרן כו', רק אחר גידולו בשנים יבא הכל לגילוי בכל פרטי מדותיו הגם שמלובש עדיין בבחי' הקטנות דמעשה נערות בדברים קטנים מאד אבל יוכלו להכירו מהות טבעו בכל פרטיו איך ומה יהי' לכשיגדל בשנים וכמאמר בוצין בקטפוהי<sup data-n=\"1437\">123</sup> כו', ונק' מדות",[["1434","120","<b>דפני ארי' להימין. . גבורה שבחסד</b>: יחזקאל א, יו\"ד. ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' שב [ובהמ\"מ שם]."],["1435","121","<b>דבחכמה אתברירו</b>: ראה זח\"ב רנד, ב. תניא באגה\"ק סכ\"ח (קמח, א), ובהמובא עוד בס' לקוטי הגהות לשם."],["1436","122","<b>בפרדס. . מושכל מורגש מוטבע</b>: ש\"ח פכ\"ה. שי\"ב נתיב כ\"ו. [ובהנסמן עוד לעיל ח\"א ע' קיז]."],["1437","123","<b>בוצין בקטפוהי</b>: ברכות מח, א."]]],[1900420335,"המוטבעים בתולדה בבחי' ההעלם עדיין, ואח\"כ יוצאים לגילוי בפעולתם במעשיו מעט מעט והיינו בחלוקי מדרגות דקטנות וגדלות מזמן היותו בן ג' וד' שנים עד שיגדל כל צרכו שמדותיו מתגדלים בדברים גדולים בהנהגה שלימה בדרכי אדם שלם בדעתו נק' גדלות המדות שנגדלו כל צרכן, וכמו פרי העץ שצומח ונגדל כל צרכו וקודם גידולו שהוא בקטנות יש בו תוארו וצורתו העצמי רק שהוא קטן, כך מדות דקטנות דנער נק' אד\"ם קט\"ן בשכל ומדות ואין כל חדש כלל בעצם תוארו היינו בהטבעת המדות שלא ישונה בטבעו מהיפוך להיפוך כמו מרחמנות לאכזריות וכה\"ג רק שנגדל יותר בשכל ע\"כ יגדלו המדות כמ\"ש לפי שכל\"ו יהול\"ל איש במדותי\"ו<sup data-n=\"1438\">124</sup> כו', והיינו כי האד\"ם עץ השדה<sup data-n=\"1439\">125</sup> שהכונה שהאדם במדותיו גדל כעץ ממש כו', ועיקר הגידול הוא במדות שזהו עיקר האדם שנבדל מן הבהמה. וענין הגידול הן ג' מדרגות הנ\"ל דמוטבע מורגש מושכל בדרך כלל והיינו חלוקי המדרגות דקטנות וגדלות בדרך כלל בג' זמנים אלה שנק' עיבור יניקה ומוחין, שבעיבור גם הטבעת המדות בולד לא נודע כלל כי הוא בתכלית ההעלם, וכשנולד נגלה מן ההעלם שבעיבור ועדיין הוא בהעלם מכל רואה רק שבאמצעות החלב שיונק משדי אמו הוכנו טבעי מדותיו קצת לבא לגילוי אח\"כ (כמשי\"ת), והתחלת הגילוי לעין הרואה מתחיל אחר היניקה שיודע לקרות אבא כו' וידוע בפעולותיו הקטנים איך ומה מהות טבעו רק שהוא בקטנות מאד והולך וגדל כנ\"ל וד\"ל.\n[לד] <b>ולפ\"ז</b> יש להבין מה שאנו רואים שינויים רבים בטבע המדות שבאדם מהיפוך להיפוך ממש כמו גם בנער בן ה' או ו' יהופך מטוב לרע או מרע לטוב בדרך כלל כמו מדת הכעס ואכזריות יהופך לרחמנות ומהתנשאות וגובה לבו יהופך לשפלות והכנעה, הרי מוכרח לומר שיש כח במדות לגבור א' על היפוכו, ולפי הנ\"ל אין שינוי בטבעי המדות מכמו שנולד מבטן עד שיזקין כמשל גידול העץ שלא ישונה תוארו מקטנות לגדלות כו'. אלא הענין הוא דגם שעצם הטבע שבמדות לא יהופך גם לזקנתו אבל באופן ההנהגה שלהם ודאי יש שינויים רבים מעת לעת וגם בשעה א' מהיפוך להיפוך, והיינו מצד בחי' המוח שהוא השליט על הלב, כמו אם מטה טבעו לכעוס ולעשות אכזריות יגבר על טבעו זה ויעשה חסד ורחמים היפוכו ממש, והוא מפני המוח ששליט על הלב להטותו מהיפוך להיפוך ממש, והיינו כאשר יתבונן באיזה טעם ושכל שאינו ראוי לעשות כך אדרבה יחייב דעתו שיעשה חסד ישונה ויתפעל להיפך. וזהו מדרגה הב' שנקרא מורגש שהוא התפעלות הלב במורגש ישונה מדין לחסד ומהתנשאות לשפלות כפי הצריך לו עפ\"י",[["1438","124","<b>לפי שכלו יהולל איש במדותיו</b>: משלי יב, ח. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תצג. תקיד. ובכ\"מ."],["1439","125","<b>כי האדם עץ השדה</b>: שופטים כ, יט."]]],[1900420336,"דעתו שבמוחו שמורגש המדות יתנהג עפ\"י בחי' המושכל שהוא בחי' הדעת שבמוח דוקא, רק שבזה המושכל של המדות יש חילוק בין קטנות לגדלות וזה נקרא קטנות המוחין או גדלות המוחין, שכמו ערך גידול המוחין לפי השנים כך יש שליטה יותר במוח הדעת על המדות לשנותם מכפי המוטבע יותר בהנהגות צרכיו וכמ\"ש לפי שכלו יהולל איש כנ\"ל וד\"ל.\n<b>והנה</b> ענין גידול המוחין להפוך המוטבע ומורגש שבמדות אין זה רק כבן ה' או ו' דנק' פעוטות שמקחן מקח כו' שאז הדעת ששייך למדות בא בגילוי קצת בהן ולאו שלו שלא יחזור בו ע\"כ מקחן מקח וכה\"ג, אבל קודם לכן הן ולאו שלו מתהפכים מחמת קטנות הדעת דלאו בני דיעה הם כלל והן ולאו שלהם אינו כלום כידוע וזהו הנק' בחי' מוחין דקטנות, וכ\"ש בימי היניקה שאז אין בחי' מוחין כלל דהיינו שאין במדות מבחי' המושכל כלל, וגם בחי' המורגש בהתפעלות המדות כמו כעס ואכזריות או להיפך לא ניכר כלל (רק חדוה או בכי' וגם זה בקטנות מאד כמדות הבהמה בלא מחשבה כלל גם לאהוב דבר מה או לשנוא בכח המדמה שבו הוא בקטנות מאד כמו לציור ומראה נאה וכגוון האש ולא יותר כו'), וא\"כ יש להבין מהו שנק' ימי היניקה בשם מוחין דיניקה או מוחין דקטנות כו'. אך הענין הוא שיש ב' מיני גידול א' גידול המדות והב' גידול המוחין שבמדות ובב' אופנים הא' בהעלם וקטנות והב' בגילוי וגדלות, ושניהם נק' גידול עכ\"פ רק שזה הגידול בחומר שיהי' מוכן לקבל הצורה (כמ\"ש למעלה) וזה הגידול בצורה שיבא לגילוי בחומר יותר. והנה גידול המדות בב' אופנים כנ\"ל היינו בב' זמנים אלה א' בימי היניקה ב' שנים ע\"י יניקת החלב ששטח גופו נגדל ואז נגדלים המדות ג\"כ, אך שאינו ניכר כלל כי גידול זה הוא רק בהעלם מן מוחין דאמא שמלובש בהעלם גדול בחלבה שנשפע במקום בינה שבלב כו' אע\"פ שהוא חלב גשמי יש בכחו להגדיל מהות טבעי המדות שנולד מבטן כמו שהן כמו שנגדל גופו הגשמי ממש, וזהו גידול הכנת חומר המדות כגידול העץ (והוא הגורם מה שיבא גידולם זה בגילוי כשיושלם ימי היניקה שמדותיו הטבעיים ניכר ונגלה קצת כנ\"ל). וזהו ב' אופנים דגידול המדות בהעלם ביניקה וגידולם בגילוי מעט מעט אח\"כ, וכמ\"כ יש ב' אופנים אלה בגידול המוחין שבמדות אע\"פ שאין מוחין כלל בזמן היניקה מ\"מ נק' מוחין דיניקה עכ\"פ, והוא בחי' מוח ממש שהוא מצומצם בקטנות והעלם גדול בחלב אמו שנגדל מעט מעט עד כ\"ד חדש נשלם גידול דקטנות חומר המוחין בהעלם, והוא הכנה לגילוי מוחין דקטנות שאח\"כ שניכר קצת בפעולתו הקטנות, ובדרך גידול המדות הטבעיים בב' אופני העלם וגילוי בב' זמנים אלה כך ממש גידול המוחין במדות בב' זמנים אלה דיניקה ואח\"כ, והכל רק בחומר המדות והמוחין שבהם בצמצום גדול שיהי' מן המוכן לקבל מוחין דגדלות שנק' צורה באמת להחיות המדה ולהפוך אותה כנ\"ל, אך ההפרש בין ימי היניקה לאח\"כ הוא שזה בקטנות והעלם בין במדות בין במוחין רק להגדיל גשם חומר טבעם להיות בהתפשטות יותר ואחר היניקה מתחיל"],[1900420337,"גידול המדות בגילוי ובגדלות יותר היינו בבחי' צורתם הרוחני יותר והוא קצת מבחי' המושכל שבמוח רק שהוא בקטנות מאד עדיין כמו שיחפוץ התינוק בן ג' וד' בדבר הטוב וימאס ברע מצד הכרתו והבחנתו היטב ולא יטעו אותו כלל וד\"ל (אבל בחי' גדלות המוחין שבמדות מתחיל מזמן ה' שנים עד י\"ג שנה דהיינו מה שחומר מדותיו הוכנו בכי טוב לקבל צורת המוח שלא יסור ימין ושמאל מהוראת המוח גם להפוך הרגש הלב כנ\"ל, וזהו שנמשך זמן רב יותר שבזמן זה נכנס מעט מעט מצורת השכל במדות עד שנשלם גידול זה דמוחין שנקרא מוחין דגדלות, פי' מוחין דגדלות המדות לאחר שנגדלו חומרם וגם צורתם בקטנות עכ\"פ יבא גידול השכל בעצם עד שיתחיל לאהוב דכשגדול יותר מפני שדעתו גדול יותר ונקרא גידול שני הכל בבחי' הצורה דמדות ומוחין הרוחניים, וגם זה בא בב' אופנים הנ\"ל גידול בהעלם וקטנות, והוא שבהעלם וקטנות נעשה ענין גידול שני זה דצורה שבמוחין מדות עד י\"ג שנה שנעשה בר עונשין שאז מתחיל גילוי הגידול ולא בהעלם ובגדלות היינו בגדלות השכל עצמו שיגדל בעצם עד היותו בן ך' כידוע, וזהו עיקר גידול הצורה בחומר בשלימותו להיות המוח שליט על הלב כנ\"ל וד\"ל).\n<b>(ונמצא</b> מובן עכ\"פ דרך כלל בהפרש בין ג' זמנים אלה דעיבור יניקה ומוחין, דבעיבור הי' גם חומר טבע המדות בהעלם וקטנות תלת גו תלת כו', וביניקה נגדל גם המוחין בהעלם דחלב עכ\"פ, ובגדלות נק' גידול המוחין והמדות בגילוי רק שיש בזה חלוקי מדרגות בהעלם וגילוי קטנות וגדלות מזמן היניקה עד שיגדל שלימות גידולו במוחין ומדות כנ\"ל וד\"ל).\n[לה] <b>ומעתה</b> יש להבין הטעם שבחלב אמו איך גנוז בה מהעלם מוחין שלה עד שיגדלו גם המוחין שבמדות בהעלם עכ\"פ כנ\"ל לפי שדם נעכר ונעשה חלב<sup data-n=\"1440\">126</sup> כו'. הענין הוא כמ\"ש בע\"ח דבשעת לידה נצטננו הירכים<sup data-n=\"1441\">127</sup> כו' ועולים בחי' נה\"י בחב\"ד כו' ומזה בא התגברות שפע ריבוי גשם המוחין מחמת עכירת הדמים שנעשה חלב והוא מיץ דק שבגידי המוח שנעשה דוקא מן ההעלאה דבר שלמטה בעליון הימנו כו' וכמ\"ש במ\"א, וזהו המועיל לגידול החומר בקטנות והעלם לבד כנ\"ל, אבל לגידול הצורה דמוחין דגדלות המדות הנ\"ל אין החלב אמו מועיל כלל רק המזון דטעם דגן דוקא וכמו שא' אין התינוק יודע לקרות אבא עד שיטעום טעם דגן דוקא לפי שהלחם שרשו בחכמה כידוע וד\"ל (אבל מזון של הולד במעי אמו היינו ממה שאמו אוכלת",[["1440","126","<b>שדם נעכר ונעשה חלב</b>: ראה נדה ט, א. בכורות ו, ב. וראה תו\"ח וארא צו, ב ואילך. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תפב ואילך."],["1441","127","<b>בע\"ח דבשעת לידה נצטננו הירכים</b>: שער המוחין (ש\"כ) פ\"ג. מבוא שערים ש\"ה ח\"ב פ\"ב. [ע\"פ סוטה יא, ב]. וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' ערב. וש\"נ."]]],[1900420338,"כו' שזהו מדמי' שבגופה שנהפך מן המאכלים שאוכלת כו' ואוכל דרך טיבורו כו' וכמ\"ש במ\"א<sup data-n=\"1442\">128</sup>).\n<b>והנה</b> הדוגמא מכל זה יובן בנשמה הפרטית שנק' אד\"ם בצלם אלקים וממנו יובן בבחי' אד\"ם העליון דאצי' בג' מדרגות הנ\"ל דבחי' עיבור יניקה ומוחין כו'. דהנה ע\"ד הנ\"ל בג' מדרגות דמושכל מורגש מוטבע דרך כלל ודרך פרט בג' זמנים הללו דעיבור כו', כך הוא בנשמה האלקית בטבע המדות דאוי\"ר שנולד מבטן בכל נשמה שנק' אור זרוע לצדיק בהכרח שיש בכל א' כמו טבע ממש לירא וליפחד מדבר הרע שמזיק לנפשו ולאהוב הטוב שהוא מחי' לנפשו, כך יראת אלקים ואהבתו לענין מעשה דסור מרע ועשה טוב כמו טבע בנפש אלקית רק שיש לכל א' אופן מיוחד כטבע המדות בגשמיות לב רך או קשה רחמני ואכזרי התנשאות ושפלות חדוה ועוצב כו' כל אלה תוכן לבות ה'<sup data-n=\"1443\">129</sup> אין לב דומה לחבירו באור אלקי במדות דנשמתו כמו שנולד ממקור חוצבו בלי ישונה גם כשיזקין ויוסיף דעת וחכמה באלקות הכל יהי' ע\"ד טבעי המדות שבנשמתו כמו שנולד אם מחסדים או גבורות וכל פרטי אופניהם, וזהו בחי' מוטבע שעדיין לא ניכר ונגלה כלל רק הכל בהעלם גדול בכל ניצוץ עד שיגדל והוא בפעולותיו ועבודותיו בתו\"מ ותפלה הגם שעדיין הכל בבחי' הקטנות דמוחין ומדות בצמצום ההשגה אלקית שלפי קטנות מוחו ודעתו וכן אהבה ויראה שלו כמו בענינים קטנים דנער בן ג' וד' כו' וכמ\"ש כי נע\"ר ישרא\"ל<sup data-n=\"1444\">130</sup> ואוהבהו כו' מ\"מ בוצין כו' שיוכלו להכירו מה שיהי' בגדולתו כנ\"ל, וזהו בחי' מורגש דמדות שהמוחין בקטנות וזהו מה שיגדל מי\"ג שנה בתו\"מ עד היותו בן ע' שגדל כל צרכו בגדלות המוחין והמדות באלקות כאדם שלם בדעתו ומדותיו בגשמיות, כך הוא ממש ברוחניות דנשמה האלקית שנק' אד\"ם בקטנות ובגדלות אנפי זוטרי ואנפי רברבי וכמ\"ש כי האד\"ם עץ השדה כנ\"ל וכמו כל הנ\"ל בתינוק שיודע לקרות אבא אחר היניקה דקטנות כו' כך הנשמה יודע ומכיר בוראו לקרותו אבא כמו אבינ\"ו כו', אך עדיין בקטנות ההשגה עד שיגדל יותר, וג' זמנים הנ\"ל הכל מי\"ג שנה ואילך שמתחיל גידול המוחין ומדות דנשמה דרך פרט (כי עד י\"ג שנה היא בבחי' עיבור בהעלם).\n[לו] <b>והנה</b> כמו שמבואר למעלה בענין מוח שליט על הלב בהפרש שבין ימי הקטנות לימי הגדלות כמ\"ש לפי שכל\"ו יהולל איש, כך הוא בנשמה וכמ\"ש תוכן רוחות ה' בבחי' המושכל שבמדות יש שכל אלקי שמתפעל מזה דוקא שאין זולתו מתפעל כלל והוא כפי אופן בחי' המוחין של",[["1442","128","<b>ואוכל דרך טיבורו כו' וכמ\"ש במ\"א</b>: נדה ל, ב. ראה תו\"ח וארא שם. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תקיג ואילך."],["1443","129","<b>תוכן לבות ה'</b>: משלי כא, ב."],["1444","130","<b>כי נער ישראל</b>: הושע יא, א."]]],[1900420339,"כל נשמה, וכך ישונה אופן הגידול מזה לזה שבזה המוח שליט להפוך דבר המנגד לאלקות שזהו עיקר בחי' שלימות גידול הדעת להטות הלב מדבר להיפוכו כנ\"ל, אבל מי שמושכל האלקי שמתפעל בלב אין ביכולתו להפוך בחי' טבעיות שלא יהי' מנגד כלל אין דעתו האלקי שלם בגידולו עדיין וכנ\"ל שכל ערך גידול הדעת במדות הוא לפי ערך השני', כך יש שליטה יותר למוח על הלב כו' וכך כל שיגדל איש בשנים וימים בעבודת ה' בתו\"מ ותפלה יותר יגדל הדעת אלקי לשלוט על הלב כו' וד\"ל, וכנ\"ל דבן ה' ו' נק' פעוטות שמקחן מקח<sup data-n=\"1445\">131</sup> שהן ולאו שלו קיימים זהו לענין מילי דעלמא, אבל במילי דשמיא אין זה רק בי\"ג שנה שנק' בר עונשין שאז התחלת גילוי דעת האלקי במדות טבעיים דנשמה כו' אבל קודם לכן לאו והן שלו במילי דשמיא אינו כלום ואוי\"ר שרש מ\"ע ול\"ת ע\"כ אינו בר עונשין כלל, והוא שא' דקטן אין לו מחשבה<sup data-n=\"1446\">132</sup> אע\"פ שיש בו אוי\"ר טבעיים אבל הוא בבחי' עיבור או יניקה שהוא תכלית הקטנות כנ\"ל, וכמו הנ\"ל בענין ב' מיני גידול דחומר וצורה דמדות ומוחין ובב' אופנים בהעלם וקטנות ובגילוי ובגדלות בשני זמנים דיניקה ומוחין דגדלות עד י\"ג שנה ועד בן כ' כו' הכל יובן בנשמה האלקית גם בהיותה בגידול השנים כו' וד\"ל.\n<b>אך</b> יש להקדים ענין ושרש ההפרש בין גידול חומר ובקטנות לגידול הצור' ובגדלות שזהו הנקרא גידול ראשון דאימא וגידול שני דאבא דרך כלל (הגם שדרך פרט יש מוחין דגדלות גם בגידול דאימא). והענין הוא כידוע ההפרש בין חכמה לבינה, דמה שמשיג בהשגה ותפיסה במוחו להטעים הדבר ולהסבירו לכל אדם נקרא בינה בחי' יש ודבר מה המושג וזהו ל' השגה בהשגת יד שנתפס הדבר, וע\"כ גידול שלה במדות המוטבעים להנהיגם עפ\"י שכל המושג במוחו כנ\"ל בא בדרך הגשמה כפי אופן המדות כמו שהן בקטנות כמו לאהוב דבר קטן, היינו מפני שגם השכל שממנו יבא ההתפעלות בלב ג\"כ בא בקטנות והגשמת ענין קטן שלא יתפעל שכל הגדול מזה כלל להיות בחי' בינה בעצם היא בחי' יש בהשגת דבר מה גם בגדול כו', וע\"כ אע\"פ שיש בטבע המוח להיות שליט על הלב כנ\"ל אין זה בגידול ראשון דבינה עדיין להיות באה בהגשמה לפי קטנות המדות, וז\"ש לפי שכל\"ו דוקא יהולל איש במדותיו שכפי גדלות או קטנות שכלו במוח החכמה כן ערך קטנות או גדלות המדות וגידול שכלו עם גידול מדותיו כא' ממש (וכמו גידול הולד ע\"י היניקה שמתגשם חלב אמו בגופו להגדיל שטחו וכן לגדל הטבעות חומר מדותיו בלבד כנ\"ל כך הוא באופן זה גידול צורת המדות עפ\"י שכלו הכל בא בהגבלת הגשמת המדות במוטבע ומורגש כו', ולזה נקרא גידול זה דאימא הכל בבחי' הקטנות כקטנות דימי היניקה מחלב אמו הגשמית וד\"ל) (וכך הוא בבינה דמל'",[["1445","131","<b>דבן ה' ו' נק' פעוטות שמקחן מקח</b>: ראה גיטין נט, א. ולעיל אות ו'. וש\"נ."],["1446","132","<b>דקטן אין לו מחשבה</b>: חולין יב, א."]]],[1900420340,"דאצי' שמגדל המוחין ומדות אוי\"ר דנשמה שבא בהתלבשות דקטנות המדות ומוחין בלבד, וז\"ש לפי שכל\"ו שנגד\"ל בהשגות אלקות כך יהולל אי\"ש באוי\"ר דגידולם כא' כנ\"ל). אבל בחי' החכמה שנק' כח מ\"ה הוא עצם כח השכל שלמעלה מהתפשטות דהשגה בהסבר כו' והוא מקור ההשגה כידוע, ומפני זה כאשר יבא ממנו הגידול כמדות דמוטבע ומורגש כו' הוא בלתי הגשמה בחומר דבר המושג שהוא באופן ההטבעה שלהם להתפעל מזה כנ\"ל אלא בבחי' כח מ\"ה דבחי' נקוד' מקור ההשגה שבלתי מושג בטעם כלל, ואז יהי' בכח המוח להיות שלי\"ט על הל\"ב להפוך מטבע התפעלותו מהיפוך להיפוך כנ\"ל שיוכל להתהפך מדין לחסד מאכזריות לרחמנות ומשנאה לאהבה לגמרי, שאין זה בגידול ראשון דבינה שלא יתפעל בלבו רק לפי הטבע שלו שגדל מבחי' מוח הבינה שנתגשם בהשגה כו' (וכמו שינק חלב משדי אמו שהוא גידול חומר מדותיו הטבעיי' כנ\"ל), וא\"כ במה יהופך מדבר להיפוכו, אך ע\"י גידול שני דחכמה כח מ\"ה שלא בא בהשגה ותפיסה במוח יוכל להפוך התפעלות טבעו מן הקצה לקצה כו', והוא ההפרש בכלל בין גידול דמוחין דקטנות דיניקה דאימא לגידול מוחין דגדלות אבא וד\"ל (וכמ\"כ יובן בנשמת אדם בגידול ראשון דבינה בהשגות אלקות שנתפס במוחו כך יתפעל בלבו ע\"כ גם טבעי מדותיו במילי דעלמא לא ישלוט המוח על הלב כלל מטעם הנ\"ל, אבל בבחי' גידול שני דאור החכמ\"ה כח מ\"ה שהוא בחי' נקודת הביטול לאין האלקי למעלה מן ההשגה כידוע ישלוט המוח על הלב גם בהתפעלות אלקות שבלב כמו מהתנשאות לשפלות וכה\"ג מטעם הנ\"ל וד\"ל). ובזה יובן כל פרטי הענין הנ\"ל בגידול דחומר וצורה במדות ומוחין שעיקר כללות ההפרש בין גידול דקטנות לגידול דגדלות הוא ענין גידול ראשון דאימא וגידול שני דאבא דרך כלל וד\"ל.\n[לז] <b>ועם</b> כל זה יובן למעלה באד\"ם העליון דאצי' שכלול מג' מדרגות דעיבור יניקה ומוחין כמ\"ש לפי שכל\"ו יהולל אי\"ש העליון כו', והיינו בחי' ו\"ק העליונים דז\"א ששה מדות חג\"ת ונה\"י יש בהן ג' מדרגות מוטבע מורגש מושכל ע\"ד כל הנ\"ל בנפש הטבעית ונפש האלקית, ובכל ענין הגידול דמוחין ומדות עליונים דקטנות וגדלות וגידול ראשון ושני דאו\"א דאצי' הכל יובן ע\"ד הנ\"ל בכל פרט ופרט וד\"ל (ודרך כלל היינו מה שמבקשים יהי רצון מלפניך שיכבשו רחמיך כו' שזה בא מחמת המוח שליט על הלב לשנות הטבע, והוא בחי' המוחין דגדלות דז\"א בגידול שני דאבא דאצי' דוקא שלמעלה מגידול המוחין דאימא דאצי' וד\"ל).\n<b>ומעתה</b> יש להבין בענין עיבור דקטנות דנמשל הגלות לזה כמ\"ש כמו הרה תקריב כו', דהנה ענין חבלי לידה מעכבים ומונעים הלידה כנ\"ל והן הבאים מן הדוחק ושעבוד וצרות שאינן באין רק מחמתה הקטרוגים דמלאכים רעים כו', והן בחי' גבורות קשות דק\"נ שנאחזין בבחי' בבחי' יסוד דנוק' בשעת"],[1900420341,"לידה ע\"י חטא אדה\"ר דכתיב בעצב תלדי בנים כו', והוא מ\"ש לפתח חטאת רובץ<sup data-n=\"1447\">133</sup> לפתח יסוד דנוק' כו', והן ע' קלין דיולדת שצועקת בצירי' וחבלי לידה כידוע במ\"ש יענך ה' ביום צר\"ה כו' וכתיב קול ה' יחולל<sup data-n=\"1448\">134</sup> אילות שנמתקו כל הדינין קשין הללו ונפתח הרחם להוליד דוקא ע\"י העיכוב דחבלי' תחלה כנ\"ל, וכמ\"ש במ\"א ע\"פ ויהי כי הקשה<sup data-n=\"1449\">135</sup> פרעה לשלחנו שזהו כמו מקשה לילד שהי' מעכב הלידה כצירי' וחבלי' דפרעה עורף דקליפה המונע הגאולה שנק' לידה מאחר שהגלות נק' עיבור וצעקתם בגלות נק' חבלי לידה כנ\"ל וד\"ל.\n[לח] <b>והנה</b> להבין עיקר סיבת פתיחת היסוד דנוק' להוליד יש להקדים תחלה בטעם שלפני הלידה בג' חדשים האחרונים יתכווצו גידי הרחם שטבעו להתכווץ ולקמוץ ויעמדו בפני הולד שלא יצא כלל כו', אך בעת הלידה דוקא יפתח הרחם פתאום כי נתפשטו הגידים ויעשו בחי' התפשטות פתיחת חלל כו' והיינו לפי שנבקע הרחם ע\"י כובד ודוחק הולד עליו שיצא פתאום כמ\"ש בס' הרפואה כו'. ולהבין ביאור הענין למה נבקע היסוד שהוא הרחם בעת הלידה דוקא ומתחלה הי' בהיפך לכווץ ולקשר הולד שלא יצא כו', הנה ידוע שבחי' יסוד דנוק' הוא בחי' ההתקשרות שיש בכלי המקבל דנוק', וכמו בחי' יסוד אימא היינו בחי' התקשרות המושכל בכלי המקבל שקולט שפע השכל המושג שנק' בינה, עד\"מ כשלומד דבר שכל וסברא ומשיגה בכלי מוח הבינה שהוא כח המשיג כל שכל כידוע, אך בעת שלומד<sup data-n=\"1450\">136</sup>",[["1447","133","<b>בעצב תלדי בנים. . לפתח חטאת רובץ</b>: בראשית ג, טז. ד, ז. ראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רעג."],["1448","134","<b>ע' קלין דיולדת. . יענך. . קול ה' יחולל</b>: תהלים כ, ב. כט, ט [וראה ב\"ב טז, רע\"ב: אילה זו רחמה צר כו']. ראה זח\"ב קיט, ב. זח\"ג סח, ב. רמט, ב. פע\"ח שער קריאת ס\"ת (שי\"ג) פ\"ד (מזמור יענך). וגם בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רעא ואילך. שער האמונה קב, א."],["1449","135","<b>במ\"א ע\"פ ויהי כי הקשה</b>: בא יג, טו. וראה בד\"ה לה\"ע שמחת חו\"כ [המקביל לכאן] בתו\"א קח, ג ואילך. וסה\"מ תקס\"ג הנסמן לעיל בתחילת המאמר."],["1450","136","<b>שלומד</b>: ע\"כ נרשם בגוכי\"ק [והמשך העמוד פנוי]. ולשלימות הענין נעתיק כאן סיום המאמר מתו\"א קח, ד [שם ד\"ה לה\"ע שמחת חו\"כ, הנחת כ\"ק אדהאמ\"צ משנת תקס\"ג שעליו מיוסד המאמר כאן]:\nוביאור טעם הדבר מה שנבקע יסוד אימא בעת הלידה ומתחלה הוא בהיפוך כנ\"ל כמ\"ש בע\"ח, יובן עד\"מ ממה שאנו רואים בשכל והשגה הנק' בינה ג\"כ כידוע, והנה בחי' יסוד אימא הוא כלי המקבל שמקבל וקולט בו שפע השכל והסברא ונקרא התקשרות המושכל פי' כשלומד דבר שכל ומשיגה במוחו הרי יש כח ההשגה במוחו מתחלה שהוא משיג כל השכליים והוא מוח בינה כידוע, ובעת שלומד שכל זה הפרטי ומשיגה בכח השגתו הנה יש כח פרטי בכח המשיג שיקשר את המושכל שלומד בו ויקלטנו בתוכו בעומק כו' עד שע\"י ענין התקשרות זו וקליטה זו נתקצר ונתקמץ אורך ורוחב של השכל שלומד כו' כי טבע היסוד לקלוט ולכווץ ולקשר בו כו' וד\"ל. ואמנם אנו רואים שלפעמים יפתח היסוד הזה פתאום, עד\"מ הרב המשפיע שכל לתלמידו הנה אם דעת הרב וחכמתו אינו נובע במוחו כ\"א בצמצום אז יוכל הרב לעצור ולקמץ שפע השכל ביסוד דבינה שבו כו' כטבעו כו' אך אם שפע החכמה נובע בו בריבוי ותגבורת גדול יותר מדאי אזי לא יוכל היסוד הזה להתקמץ וממילא ועל כרחו יפתח וישפיע שפע רב יותר מכדי קבלת התלמיד כו' משא\"כ אם אין שפע החכמה ברב כ\"כ יוכל למנוע במוחו מלגלות שום דיבור יותר מכדי הצורך כו' לפי שטבע היסוד לקשר המושכל ולכווצו כנ\"ל וד\"ל, ונמצא סיבת פתיחת היסוד הוא רק מחמת תגבורת הריבוי שבמוח עד שאין ביכולתו לכווץ ופתאום יפתח על כרחו כו', כמ\"כ ממש יובן הטעם בפתיחת יסוד דנוק' בעת הלידה דוקא מחמת תגבורת כובד הולד כו'. וכמ\"כ למעלה יובן ענין בקיעת יסוד אימא דאצי' וכענין מה שכתוב במ\"א ע\"פ הזהר פ' אמור יעקב אמר אז יבקע כשחר אורך (בסידור גבי סוכות). ע\"כ בתו\"א. [בגוכי\"ק אדהאמ\"צ (1195) שנרשם שם מאמר התו\"א — שורה האחרונה היא בשינוי: וכענין ובוקע חלוני רקיע וכמ\"ש במ\"א שהוא מפני ריבוי הא[ור]ו' דוקא יפתח בדרך בקיעה וד\"ל].\nובסה\"מ תקס\"ג ח\"א ע' קנב, [בהנחת הר\"מ בן אדה\"ז מדרוש זה] נמצא ענין זה בשם הה\"מ ובשינוי, וז\"ל: והתהוות הלידה הוא (כמו ששמע ממורו ע\"ה) ע\"פ ויעבור ה' כו', פי' שיסוד אימא הוא המקשר ומעצר את ההשגה כו' ויעבור ה' פי' שנתמלא מאד ריבוי אורו בבינה שלא הי' יכול יסוד אימא לקשר ולעצור כו' שנבקע יסוד אימא ונתגלה כו'. ע\"ש בארוכה. ועד\"ז הוא באוה\"ת שמות ע' ב'תקלא]."]]],[1900640016,"<b>בס\"ד</b>\n<b>אתה</b> אחד ושמך אחד ומי כעמך כישראל גוי אחד בארץ כו'. הנה בכללות נוסח זה נחלק ד' פעמים לג' קווין חג\"ת בד' מדריגות, והיינו אתה [הוא] בחי' חסד כידוע בכמה מקומות בזהר שאתה הוא בחי' חסד כמו אתה כהן, ושמך [הוא] בחי' גבורה כי אין לשון שם נופל כי אם על בחי' התנשאות (שהוא בחי' הגבורה) על דבר מה להיות שמו נקרא עליו ובלתי [שום] דבר מה אין לאדם צורך לשם כי אם כשיש דבר מה אזי שמו נקרא עליו. נמצא שעיקר בחי' שם הוא בחי' התנשאות שהוא בחי' הגבורות. גם בחי' שם הוא בחי' אותיות שהוא על ידי בחי' גבורה והתחלקות. ומי כעמך כישראל הוא בחי' תפארת. הרי כאן בחי' חג\"ת פעם א', אתה בחי' חסד, ושמך בחי' גבורה, וישראל בחי' תפארת. תפארת גדולה הוא בחי' חסד, כידוע שבחי' גדולה הוא בחי' חסד. עטרת ישועה הוא בחי' גבורה, כי לשון ישועה אינו נופל כי אם להושיעו מן ההיפוך המנגדו, כמו ויושע ה' את ישראל מיד מצרים המנגדים ובודאי לעמוד נגד המנגד צריך התגברות בתגבורת. ומטעם זה בכל מקום נקרא ישועה בשם גבורה. וגם עטרת הוא בחי' נוקבא כמו אשת חיל עטרת בעלה. יום מנוחה וקדושה לעמך נתת הוא בחי' תפארת. הרי בחי' חג\"ת"],[1900640030,"פעם ב'. אברהם יגל כידוע שהוא בחי' החסד, יצחק ירנן הוא בחי' גבורה, יעקב ובניו ינוחו בו הוא בחי' תפארת, הרי בחי' חג\"ת פעם ג'. מנוחת אהבה ונדבה הוא בחי' החסד, כי בחי' אהבה שרש בחי' החסד, ונדיבות גם כן ענין א' עם בחי' החסד. מנוחת אמת ואמונה הוא בחי' גבורה, בחי' נוקבא כמו אמת ואמונה כל זאת בחי' נוקבא. מנוחת שלום השקט ובטח הוא בחי' תפארת, כי ענין שלום הוא המכריע בין חסד וגבורה המנגדים ותפארת הוא המכריע ועושה שלום. הרי בחי' חג\"ת פעם ד'. ודרך כלל מדבר בד' מדריגות, א' קודם הצמצום כמו שהי' אור אין סוף ממלא כל מקום החלל ומכל מקום גם שם מסרו אנשי כנסת הגדולה שהוא בחי' כנסת ישראל לומר אתה א' כו' בחי' חג\"ת בג' קוין כמו שיתבאר. ובחי' תפארת גדולה מדבר בבחי' פרצופים דע\"י וא\"א שאחר הצמצום ומקום פנוי שנק' עדיין בשם עולמות האין סוף בחי' אחרונה שבמאציל להיותם בלתי כלים המגבילים כו', לזאת נאמר בו לשון נתינה יום מנוחה כו' לעמך נתת, שידוע שענין הנתינה הוא דבר הניתן מיד ליד בלי שינוי בין קודם הצמצום לאחר הצמצום כמו שיתבאר. אברהם יגל כו' הוא בחי' חג\"ת דעולם הנאצלים והוא בחי' ז\"א שהוא בחי' המדות דאצילות עם בחי' המוחין למדות שהוא בחי' כללות עולם האצילות. מנוחת אהבה ונדבה מדבר בבחי' נה\"י דבחי' הנאצלים המקור לחיות הנבראים, היינו בחי' אלקות המצומצם לערך הנבראים אך הוא בבחי' אצילות עדיין והוא גם כן בציור ג' קווין חג\"ת. הרי כללות כל בחי' ההשתלשלות נכללו בנוסח זה שנמסר לכנסת ישראל. מנוחה שלימה שאתה רוצה בה, מנוחה שלימה הוא בחי' שלימותא דכולא שלמעלה גם ממקור הג' קוין אף כמו שהן בשרשן בבחי' האין סוף שקודם"],[1900640044,"הצמצום, כי אם קאי על בחי' אחדות הפשוטה בתכלית דבחי' ולאו מכל אילין מדות כלל אף כמו שהן בבחי' אין סוף עצמו כו' הרי גם זה יכירו בניך וידעו (כמו שיתבאר).\n<b>ולהבין</b> כל זה בדרך קצרה, הא' איך שייך בחי' חג\"ת היינו בחי' שם חו\"ג בבחי' אין סוף (שקודם הצמצום), לכאורה אם הוא בחי' א\"ס איך נופל שם לשון חסד כו'. ויובן זה בהקדים מאמר העץ חיים בענין טבע הטוב להטיב, שהמשיל משל זה על בחי' אור אין סוף שקודם הצמצום שמצד טבע הטוב להיטיב חפץ חסד ועלה ברצונו הפשוט להאציל כו' וקאי בחי' טבע הטוב זה איך שהוא בעצם הנפש הפשוטה בלתי גור'. והנה חז\"ל ג\"כ תפסו משל זה ואמרו מה הנשמה ממלא את כל הגוף כך הקב\"ה ממלא את העולם כו'. וקאי גם כן על בחי' אור אין סוף שקודם הצמצום שהי' ממלא כל מקום החלל בלשון ע\"ח, ובלשון הגמרא הוא ממלא את העולם, המשילו משל מבחי' נפש הפשוטה כו', אך בעץ חיים מדבר מבחי' טבע הטוב שבנפש הפשוטה, ובגמ' מדבר בכללות חיות הנפש. הנה באמת אין המשל דומה לנמשל כי הנפש אף קודם בואה לגוף, אף שבודאי הי' פשוטה ומופשטת מעשר כחות בפרט, אך בודאי כי כזאת נמצא אתה להחיות את הגוף ודייקא בעשר כחות אלו רצון ושכל ומדות ושארי כחותיה ולא באופן אחר, והרי בחי' טבע [הטוב] להחיות ולהיטיב נמצא בה אף קודם בואה לגוף. והראי' לזה הוא מב' אופנים, הא' מאחר שאנו רואים שבבואה לגוף תחי' באופן זה ולא באופן אחר, והרי בהכרח שנמצא בה בעצמה בחי' טבע להחיות, והיינו כאשר תבוא לגוף בודאי תחי'. והראי' מוכרחת יותר לזה הוא מהיפוכה, והיינו מבחי' הגלגולים שנמצא בספרים שבשביל איזה עונש תתגלגל הנפש בצומח ודומם ולגלות ועונש תחשב לה. ואם נאמר שצורתה פשוטה בתכלית מה לה באיזה מקום שתהי', אלא מוכרח"],[1900640057,"לומר שנמצא בנפש עצמה בחי' טבע [הטוב] להחיות ולזאת כאשר תבוא בגוף אדם שהוא חומר מוכן לקבל צורת חיות הנפש תתפשט אור טבע הנפש להחיות, מה שאין כן אם תתגלגל בדבר אחר שאינו חומר מוכן הרי בחי' טבע להחיות שבה בכיווץ, ובגלות. אך כל זה לא שייך כי אם בנפש האדם היותה באמת נברא ובעל גבול וכל מציאותה מוגבלת, לזאת אפשר לומר בה שאף שהיא פשוטה מעשר כחות גלוים ומחולקים אך טבע[ה] להחיות ולהמציא עשר כחות כאלו נמצא בה גם קודם בואה לגוף והכרח כנ\"ל. אבל איך אפשר לומר זה בבחי' אור אין סוף, מאחר שהוא בחי' אין סוף הרי הוא בודאי בהיפוך מכל הנ\"ל שאי אפשר לומר בו שטבע [ה]טוב העצמי להטיב ולהאציל עשר ספירות כמשל הנ\"ל, אם כן אין זה בחי' אין סוף, כי פירוש אין סוף הוא שאין סוף להתפשטותו ויכול להאציל ספירות עד אין קץ ושיעור, וגם לאו דוקא באופן זה כי אם באופנים אחרים עד אין שיעור, שאם לא כן אינו [בבחי'] אין סוף, ואם כן אין הנמשל דומה למשל כלל וכלל, כי אם באפס קציהו והיינו מהתפשטות הנפש בעשר כוחות גלוים ומחולקים כרצון ושכל ומדות בהתחלקות בודאי מזה מופשטת הנפש כו', אבל בעיקר המהות אין ערוך כלל.\n<b>אך</b> מאחר שעל כל פנים נדמה למשל בגמרא ועץ חיים, דהיינו לשון ובחי' טבע הטוב גם בבחי' אין סוף עצמו, גם זה אמת שבודאי יש גם בבחי' א\"ס טבע הטוב, אך לא כדוגמת הנפש [ממש] ששם נמצא הוא כל עצמותה מוגבלת בבחי' טבע הטוב הנמצא בה, והיינו שאינו כי אם באופן א' ובבואה לגוף אדם דוקא ולא בגוף אחר כנ\"ל, ואם היינו אומרים כדוגמא זו בבחי' א\"ס הרי אין זה בחי' א\"ס, אך מה שנמצא בחי' טוב וחסד בבחי' א\"ס הוא דוקא מצד בחי' א\"ס ודוקא היא הנותנת כי מאחר שהוא בבחי' א\"ס הרי בודאי נמצא בו גם בחי' החסד והטוב וכו', אם לא נמצא בו זאת הרי אדרבה אינו בחי' א\"ס, ועיקר שם בחי' א\"ס הוא שהוא כל יכול, ויכול המצא בו גם בחי' החסד והטוב להטיב, אך לא כדוגמת הנפש, שבנפש הרי חיות הנפש מוגבלת דוקא בטבע הטוב דלהחיות ולא באופן אחר, מה שאין כן בחי' א\"ס מה שנמצא בו בחי' הטוב והחסד הוא דוקא מצד שהוא כל יכול, ויכול להיות גם בחי' טוב וחסד, וכמו כן יכול להיות באופן אחר לגמרי עד אין קץ ושיעור מה שאין כן בנפש שמוכרחת להיות דוקא בטבע להחיות וכנ\"ל. וזה מה שאמרו רז\"ל מה הנשמה ממלאה בטבע הטוב להחיות אף הקב\"ה, היינו שגם בחינת הטוב והחסד נמצא מצד בחינת כל יכול אך לא שיתואר דוקא באופן זה כו'. וזה שאמרו"],[1900640069,"רז\"ל ממש לכאורה הוא היפוך מאמר זה הוא מקומו של עולם ואין העולם מקומו, והיינו הוא מקומו של עולם שמחי' את כל העולם בטובו כטבע הטוב שבנפש, ואין העולם מקומו היינו כי מה שנמצא בחי' הטוב בבחי' א\"ס לא שיתואר בו כי אין העולם מקומו ויכול להיות בכמה אופנים שונים לגמרי, להיותו כל יכול, ומה שנמצא בו בחי' טבע הטוב הוא גם כן מחמת בחי' כל יכול כו', ואם כן שמאחר שכל עיקר שם בחי' החסד שבא\"ס הוא מצד היותו בחי' אא\"ס ולזאת נמצא בו גם בחי' החסד והטוב, ואם כן בודאי חסד זה הוא בחי' אין סוף, והיינו שיכול לימשך למטה מטה עד אין קץ ושיעור לטובים ולרעים בשוה ממש ובהשוואה ממש, השפעת החסד לנשמות בגן עדן וגם להשפעת מזון וחסד גשמי לישראל ולאומות העולם ממש בהשוואה א' היותו בחי' אין סוף, ואם נאמר תוארים והגבלות ואופנים מיוחדים אם כן אינו בבחי' אין סוף, [ו]הרי כל עיקר סיבת מציאותו הוא מצד בחי' אין סוף, אם כן בודאי חסד זה הוא בחי' א\"ס ואין קץ ושיעור לחסדו וטובו ובהשוואה לכל א' ואין לומר בו שום התחלקות כו'. והנה כמו כן בודאי נמצא בבחי' א\"ס גם בחי' הגבורה הוא בחי' רוממות עצמותו כמו שנמצא בחי' החסד שהוא הירידה וההמשכה למטה מטה עד אין קץ ושיעור, כמו כן נמצא בו בחי' הרוממות בעילוי אחר עילוי עד אין קץ ושיעור למעלה, וכמאמר למעלה עד אין קץ ולמטה עד אין תכלית. ואף שבאמת גם זה אי אפשר לומר על בחי' אין סוף שהוא מרומם ומנושא דוקא הרי אין זה בחי' אמיתית א\"ס כמו שהכרחנו על בחי' החסד הנמצא בבחי' א\"ס שהוא מצד בחי' כל יכול גם להטיב, כמו כן בודאי נמצא בו גם בחי' הרוממות והתנשאות וכמו שחסדו וטובו עד אין קץ ותכלית למטה מצד בחי' הא\"ס כמו כן בחי' הרוממות וההתנשאות גם כן למעלה בעילוי אחר עילוי עד אין קץ ושיעור למעלה.\n<b>וזהו</b> אתה אחד ושמך אחד היינו בחי' חסד וגבורה איך שהם בחי' אחדות הא\"ס עצמו וזהו בחי' אחד, ומי כעמך כישראל גוי אחד בארץ הוא בחי' תפארת, וג\"כ כמו שהוא בבחי' אחדות הא\"ס, והיינו מ\"ש ישראל אשר בך אתפאר, והיינו אף כמו שהוא בבחי' האל\"ף שהוא פלא שהוא בבחי' א' שהוא פלא שהוא בחי' אחדות הפשוטה, גם שם אתפאר בבחי' שם תפארת כמו בבחי' חסד וגבורה. וזהו שנמסר מכנה\"ג לכללות נש\"י, שגם הם יכולים לומר אתה אחד ושמך אחד כמו שהן בבחי' א\"ס עצמו. אף שהן נשמות נבראים. והיינו מצד שרשן שעלו במחשבה"],[1900640080,"הקדומה ג\"כ בבחי' א\"ס עצמו. וזהו ועשיתם אתם א\"ת אותם אלא אתם כאלו עשאוני בכפי' כי פי' עשאוני בלה\"ק הוא ענין כפי' כמו גט מעושה כו', והיינו שאתם כופים אותי להקרא בשם חג\"ת אף בבחי' א\"ס היות שרש נש\"י גם כן בבחי' א\"ס, לזאת דוקא ע\"י ימצא גם בבחי' הא\"ס בבחי' חג\"ת והיינו מצד בחי' הא\"ס דוקא וכו'. וכמו\"כ תפארת גדולה ועטרת ישועה יום מנוחה וקדושה לעמך נתת, היינו בחי' חג\"ת שאחר הצמצום ומקו\"פ והיינו בבחי' ע\"י וא\"א שנק' ג\"כ בשם עולם הא\"ס. אך שהם אחר הצמצום ולכן נאמר בהם לשון נתינה, כי ענין נתינה הוא בדבר הניתן מיד הנותן ליד המקבל הרי אף שבגילוי הרי אותו הדבר עצמו שהי' אצל הנותן הוא כעת אצל המקבל, אך היינו בגילוי הדבר הוא, אך באמת במהות הדבר השתנה מכל וכל, מאחר שיצאתה מרשות הנותן מכל וכל ונשתנה מרשות לרשות אחר לגמרי. וכדוגמא לזה הוא בחי' פרצופי' ע\"י וא\"א אף שהם ג\"כ בבחי' א\"ס, אך הוא אחר הצמצום ומקו\"פ והיינו שנסתלק ונתצמצם כל מהות ועצמות הא\"ס ולא נשאר כ\"א רשימו בעלמא, כמבואר בע\"ח שמבחי' רשימו בעלמא שנשאר אחר הצמצום ומקו\"פ נמשך בחי' הקו וחוט שרש לכל ההשתל' וראשית הגילוי קו וחוט הוא בא\"ק וע\"י וא\"א ולזה לשון הקודש על זה הוא בחי' נתינה וכו'.\n<b>ויש</b> שני משלים ע\"ז א' מבנין של זכוכית כולו מגגו וקרקעיתו ודופנותיו כולו מזכוכית נקי' בתכלית (בל\"א קרישטאל) הרי אותם העומדים בפנים רואים כל אויר ובנינים שבחוץ בטוב הראות בכל פרטיו עד תכלית פרט הקטן, בדקות ממש כאותן העומדי' בחוץ, להיות הזכוכית זכה בתכלית, והן [הוא] האמת כי כן הוא הדבר שרואה את הכל לא נעדר מאתו כל מאומה, אך כל זה הוא בגילוי הדבר, אבל לא במהות הדבר כ\"א אדרבה נעלם מאתו מהות הנראה מכל וכל לגמרי מאחר שאינו רואה כ\"א ע\"י מחיצות והפסק מבדיל. והמשל הב' הוא מהעתק [הכתב] מספר אל ספר הוא ג\"כ עד\"ז ממש והיינו שכל מה שהי' כתוב בספר הא' הועתק לספר הב' אות באות, וא\"כ לכאורה אין שום הפרש בין ספר הא' לספר הב'. אך כ\"ז הוא בגילוי והתפשטות האותיות אבל עצם האותיות הרי נשארו בספר הא' ולא נלקח ממהותם לספר הב' מאומה. וככה ממש ע\"ד דוגמא זו בחי'"],[1900640091,"ע\"י וא\"א שאחר הצמצום הראשון אף שהם בבחי' א\"ס ג\"כ, אבל מאחר שהם אחר הצמצום נסתלק מאתם כל מהות ועצמיות הא\"ס, אשר א\"א לשער שום צמצום גדול יותר מזה, וכדוגמת משלים הנ\"ל כמו בנתינת דבר מה מיד ליד הרי נלקח לגמרי מרשות המשפיע ולא נשאר בדבר ההוא שום רושם מעצם המשפיע, כ\"א נשתנה מרשותו לגמרי לרשות אחר לגמרי, וכמו\"כ משל הא' מבנין הזכוכית אף שרואה כל אויר החוץ, אך אינו כ\"א גילוי הדבר אבל לא ממהות הדבר לגמרי אפילו אפס קצהו מאחר שהוא ע\"י מחיצות מפסיקות לגמרי מכל וכל, כמו\"כ משל הב' מהעתק הדבר מספר לספר הרי לא נמצא בהעתק שום דבר מעצמיות האותיות שהיו בספר הא' כ\"א התפשטות אבל לא מעצמיות האותיות כלל וכלל, וזהו ענין לשון עתיק מלשון העתק והיינו שהועתק מבחי' עצמות הא\"ס ע\"י בחי' צמצום הראשון שצמצם עצמו כביכול ולא נשאר מבחי' עצמותו ומהותו כי אם הארתו כמשל העתק הנ\"ל ולזאת נאמר בספרי הקבלה שיותר אין ערוך מבחי' ע\"י וא\"א לגבי עצמות הא\"ס מערך הנבראים לגבי הנאצלים, אף שהוא ג\"כ ע\"י צמצום הפרסא המפסיק אך אין ערוך כל הצמצומים שבבחי' ההשתלשלות לגבי בחי' צמצום הראשון שאין כמוהו סילוק כל עצמותו בכל הצמצומים שנסתלק כל עצמותו מכל וכל ובאופן המשלים הנ\"ל.\n<b>אברהם</b> יגל יצחק ירנן יעקב ובניו ינוחו בו. הוא בחי' חג\"ת דעולם הנאצלים בבחי' אורות וכלים המגבילים את האורות בבחי' הקוין חח\"ן בג\"ה ודת\"י. והנה על בחי' יעקב שהוא בחי' תפארת נאמר ינוחו בו בעצמותו ממש ואף שהוא בחי' שבג' קוין אך דווקא על בחי' תפארת נאמר בו בעצמותו, כי תפארת [לבד] עולה עד הכתר והיינו בבחי' פנימיות הכתר כי שני הקוין חח\"ן בג\"ה שרשם הראשון בחיצוניות הכתר אבל קו האמצעי דת\"י שרשו בבחי' פנימיות הכתר שהוא בחי' אין, וזאת ידוע שבבחי' אין עצמו אין נופל בו לשון השתל' מעלה ומטה, ולזאת בחי' התפארת אף שהוא בבחי' הקוין מאחר ששרשו בבחי' הכתר שהוא בחי' האין הוא ממש אותו האין עצמו שבבחי' הכתר עצמו בלי הפרש ושינוי כלל, ולזה נאמר על בחי' יעקב שהוא בחי' התפארת ינוחו בו בעצמותו ממש בחי' האי\"ן שבבחי' הכתר אף שהוא בבחי' קוין בעולם הנאצלים [הוא] בלי שינוי וכו'."],[1900640102,"<b>מנוחת</b> אהבה ונדבה מנוחת אמת ואמונה מנוחת שלום השקט ובטח, זה קאי על בחי' נה\"י דאצי' היינו [צמצום] בחי' אלקות עצמו להחיות נבראים ולזה נאמר בו לשון השקט ובטח, כי ענין בטח הוא יושב בטח לבדו ואין לו שום ענין עם כל וכמו שנאמר ביהושע על עיר ליש שיושבת בטח אין לה דבר, והיינו שמופרשת ומובדלת לעצמה ואין לה שום צורך עסק עם שום אדם, וכאן מדבר על בחי' האלקות שלהחיות הנבראים איך שהוא בבחי' אצי' עדיין שנחשב לבחי' עצמות אלקות ממש מובדלת עדיין מערך בחי' חיות הנבראים.\n<b>מנוחה</b> שלימה שאתה רוצה בה. הנה זה מדבר בבחי' ומדריגה היותר נעלה מכל ד' מדריגות הנ\"ל ולזאת נק' מנוחה שלימה היינו בחי' שלימותא דכולא שאתה מעצמותו רוצה בה בפנימיות רצונו העצמי, וזהו שאתה כי תיבת שאתה הוא חיבור מב' הפכים יחד, כי אתה הוא בחי' החסד איך שהוא נקרא בשם חסד כבר בבחי' קו והשי\"ן הוא בחי' היחוד והתכללות הג' קוין כאחד כציור השי\"ן שהוא חיבור ג' קוין. והיינו יחוד וביטול הג' קוין איך שהם מיוחדים בתכלית עצמיות הא\"ס, אך מחמת שבתיבת שאתה נאמרו כאחד בחי' אתה הוא בחי' גילוי החסד בבחי' קוין והשי\"ן הוא בחי' יחוד הקוין בהתכללותם שהם ב' הפכים ונאמרו כאחד מוכרח לומר שיש בחי' ומדריגה אשר לגבי שם בחי' יחוד הקוין וגילוי הקוין בהשואה א' ממש והיינו בחי' שלימותא דכולא ממש כו'.\n<b>והנה</b> גם זה יכירו וידעו שהם בחי' הנשמות בגופים דוקא כי מאתך היא מנוחתם היינו מנוחתם דשבת שבעשי' דוקא מאתך היא מאתך ממש ודווקא במצות שבת, וכידוע שבמצות שבת אין שום הפרש בין גדולי עולם לקטני ההמון ממש, והטעם הוא כי מצות שבת הוא שביתה ממלאכה ובורר אסור בגשמיות וברוחניות, וכמו\"כ בנפש עצמה נאסר עבודת מלאכה, ועבודת הנפש היא במוח ולב בעשי' ועיקר המצוה היא במנוחת הנפש בעצמותה בבחי' יחידה שלמעלה מבחי' הגילוי במוח ולב. ולזאת הושווה במצוה זו צדיקים הגדולים שעבודתם בעונג וכוונת המוח והלב בתכלית עם פחותי ההמון אבל מצות שבת היא בבחי' שביתה ממלאכה זו כ\"א בעצמות הנפש [עצמה] בבחי' יחידה ובבחי' יחידה [עצמה] שווין הכל ממש, ולזאת אף שבגילוי המצוה בודאי צדיקים הגדולים מקבלים"],[1900640113,"בעונג וקבלות נפלאות בתפלה ובאכילת שבת, מה שאין כן ההמון אך אין זה כ\"א בבחי' הכלים המקבלים, אבל בעצם המצוה בבחי' השביתה דבחי' יחידה הכל שוין ממש.\n<b>והנה</b> להבין ענין בחי' יחידה מה היא, הוא בחי' עצם נקודת יהדות שנמצא בכל נפש מישראל אף בפחותים וקלים. ולזאת נמצא בחי' מס\"נ על קידוש השם אף בקל שבקלים והוא מצד בחי' יחידה והוא למעלה אף מבחי' מזלא הנזכר בגמרא על דניאל וחביריו דאע\"ג דאינהו לא חזו מזלייהו חזי אשר מבחי' מזלא הנ\"ל נופל עכ\"פ לפעמים הרהורי תשובה במוח ולב בלתי הכנה מוכנת במוחו ולבבו והוא מבחי' מזלי' הנ\"ל היינו בחי' מקיפי הנפש אבל בחי' יחידה אינה שייך כלל לשום בחי' התפעלות מוח ולב, ואף להיות מעורר כו' והוא בחי' עצם יהדותו ולזאת אינו נוגע לבחי' יחידה שום פנימיות הנפש להיותו אינו שייך כלל לבחי' גילוי הנפש, וזהו כולך יפה רעייתי מצד בחי' היחידה שהיא שלימה בכל פחותי הערך ואפילו מי שעבר כל עבירות שבתורה מלבד מאותן הידועים, וז\"ש שובה ישראל עד הוי' אלקיך והיינו אפילו מי שפגם בכל שם הוי' יכול לשוב בתשובה שלימה מצד בחי' יחידה לזאת בודאי לא ידח ממנו נדח [ח\"ו] מצד בחי' היחידה ששלימה בכל איש ישראלי מצד היותה אינה שייך כלל לחיבור הנפש בכלי המוח ולב. והנה מקום להשראתה לא נמצא בכלי הגוף כ\"א בד' אמות של אדם שבודאי רחוק ערכה מאד מערך הנפש וכלי הגוף דמוח ולב המוכנים לקבל צורת השכל ושם לא תשכון הארת בחי' יחידה, גם בבחי' מקיפים של הראש עד מקום כלות הגבהת הידים בנשיאת כפים דכהן. ואף לא בבחי' הלבושים דאף שהן לבוש גשמי לגבי ערך כלי המוח והלב, גם בהם לא ישכון הארת בחי' יחידה כ\"א מקיפי"],[1900640124,"הנפש שורה על בחי' הלבושים אבל לא בחי' יחידה, ואף גם בית שהוא מקיף עוד יותר חיצוני ישכון בו מקיפים היותר עליונים מעל גבי הלבושים אבל לא בחי' יחידה עצמה כ\"א דייקא בד' אמות הרחוקים בתכלית בריחוק אשר אין ריחוק יותר ממנו שם דוקא ישכון הארת בחי' יחידה, וכידוע שכל איש הישראלי העובר בארץ העמים מתברר עי\"ז, והיינו ע\"י בחי' יחידה שלו בד' אמות. וכדוגמא זו יובן למעלה ג\"כ שיש שני בחי' בהשתל' היינו בחי' השתל' יש מאין והיינו מבחי' החכמה ולמטה וכמ\"ש והחכמה מאין תמצא ובזה יש בחי' השתל' מעלה ומטה כי בודאי בחי' האין לא ישרה כ\"א בחכמה שהוא כלי מוכן לקבל הארת האי\"ן דכתר אבל לא במקום אחר כו', ויש בחי' השתל' שנק' י\"ש מי\"ש, והיינו בחי' יש האמיתי לא ישרה כ\"א דוקא ביש גמור, והטעם כי גם בחי' האי\"ן אינו כלי מוכן לקבל השראת בחי' יש האמיתי [להיות אין ערוך כלל, כ\"א דוקא ביש גמור שם דוקא ישרה בחי' יש האמיתי] היות בחי' היש הגמור תכלית ההסתר היותר אחרון שם דוקא אפשר להיות שורה בו בחינת יש האמיתי כמו שהוא ממש.\n<b>ומכ\"ז</b> יובן ג\"כ שורש בחי' שבת שהוא בחי' שביתה ממלאכות הנפש ומקומו בבחי' יחידה לזאת ה[ו]שוו בו בחי' השבת שאצל הצדיקים הגדולים שמקבלים בבחי' עונג ודביקות נפלא עם בחי' השבת שבהמון עם שהוא שביתה ומנוחה ממלאכה גשמיות [ו]מעונג דאכילה ושתי' גשמית השראת בחי' יחידה שוה בהם ממש, ואדרבה במנוחה גשמיות שם דוקא תהי' השראת בחי' יחידה, וכדוגמת ד' אמות של אדם. וזהו אל יצא איש ממקומו היינו בחי' ד' אמות שבו השראת בחינת יחידה. וכמו כן יובן למעלה בבחינת אדם העליון שנקרא ז\"א בחינת יחידה שלו היינו בחינת יש האמיתי דבחינת עצמות האין סוף לא בבחינת האין המקור לחכמה ולא בהארת [ה]אין שבחכמה ומדות שלו כי אם דוקא בבחינת יש גמור שלו היינו בבנין הפרצופים וקיום היש דעשר ספירות שבו, שם דוקא ישרה בחינת יש האמיתי דבחינת יחידה שלו. מה שאין כן בשאר המצות כמו תפילין ושארי מצות שעיקר מצותה בעבודה ועשי', בודאי יש בזה חילוקי מדריגות שהצדיקים עושים באהבה ויראה בכוונת ועונג, משא\"כ הקטנים מהם כו'. וזהו מנוחה שלימה מבחי' שלימותא דכלא בחי' היש האמיתי שאתה רוצה בה"],[1900640135,"בעצמותו, יכירו בניך וידעו כי מאתך העצמי היא מנוחתם שבמנוחת העשי' היות כי במנוחה שבעשי' דוקא שם תשרה הארת בחי' יחידה, וזהו ועל מנוחתם יקדישו את שמך בחי' מס\"נ על קידוש השם שהוא בחי' יחידה, והשראתה הוא בבחי' מנוחה שבעשי' דוקא וד\"ל."],[1900640017,"להבין ענין ההשתטחות על קברי הצדיקים. הנה ענין השתטחות על הקבר יש בזה כמה מדריגות ואופנים שונים, ובדרך כלל יש בזה ה' מדריגות. הא' מה שמבואר בשו\"ע א\"ח הט\"ב וז\"ל, ומה שנוהגי' לילך על הקברות הוא כדי לעורר האבילות ולהכניע היצה\"ר לשוב בתשובה, והוא ע\"ד מאמרז\"ל וא\"ל יזכיר לו יום המיתה שעי\"ז נכנע היצה\"ר וכמ\"ש טוב לכת אל בית אבל מלכת אל בית המשתה [משום] והחי יתן אל לבו, הרי שבזה יוכל להכניע את לבבו כנ\"ל. והב' הוא ג\"כ נזכר בשו\"ע הלכות ר\"ה נוהגי' לילך על הקברות ולהרבות שם בתחנונים כו', ושם הטעם משום דבה\"ק הוא מקום מנוחות הצדיקים, ומתוך כך הוא מקום קדוש וטהור והתפילה מתקבלת שם ביותר וכו'. ויבקש מהשי\"ת שיתן אליו רחמים בזכות הצדיקים שוכני עפר ויש בזה ב' טעמים, הא' שהמקום קדוש וטהור וזה גורם שמקבלים תפלתו, הב' שבודאי יתפלל שם בכונה רצוי' ביותר מחמת התעוררות הלב בתשובה כנ\"ל משום והחי יתן אל לבו כו', וזה גורם שתהי' תפילתו רצוי' ומקובלת. והג' הוא מה שהולכים אל מקום מנוחות אביהם או בנו יחידו כו' וכדומה שמעורר הבכיה וההספד ועושה פתיחות הלב לגמרי כמו שמתו מוטל לפניו ממש שנשבר לבבו באמת מצד עג\"נ שנגע עד [תוך] נקודת לבבו לבכות במר נפשו, וכמו שאמר ר\"י דין גרמא דעשיראה ביר שהי' נושא אצלו העצם משום עג\"נ שלא ישכח על בנו שמת ובעבור זה תמיד לבו נשבר, וכמו יעקב אבינו ע\"ה שהתאבל על בנו ימים רבים שהי' תמיד בוכה במר נפשו על הסתלקות בנו מצד שלא נשכח כלל מאתו כידוע, וכמ\"כ בהליכתו אל הקבר אעפ\"י שנשכח מאתו זמן רב אעפי\"כ חוזר ונזכר עד שיכול לבכות במר נפשו מאד וגורם בזה פתיחו' הלב לגמרי שיוכל לבכות על חטאיו ממש ג\"כ בלב נשבר ונדכה ובבכי' רבה, ויכול לבוא לידי תשובה שלימה כידוע, כי עיכוב התשובה הוא מחמת גסות וגבהות הלב, אבל אם הלב נשבר היטב באמת יהי' מאיזה דבר שיהי' אזי תומ\"י יכול לבוא לידי תשובה שלימה, וזהו [ענין] יסורים שבאין על"],[1900640031,"האדם שנק' יסורים של אהבה אפי' בבני חיי ומזוני שמבטשים לאדם כדי להשיבו בתשובה שלימה מקרב [איש] ולב עמוק ביותר, וראי' מר\"י שאמר דין גרמא דעשיראה ביר שבודאי הי' אצלו יסורים של אהבה כנ\"ל.\n<b>והמדריגה</b> הד' הוא מה שהולכים על קברי הצדיקים שהיו יודעים ומכירים אותם בהיותם בחיים כו' אזי מצד תוקף אמונתו שהי' מאמין בו בעודו בחיים חיותו שהוא איש אלקי קדוש יאמר לו, וכשהי' נכנס אצלו בהיותו בחיים חיותו הי' מתבטל ממציאותו כשנכנס להיכל כבודו כו' מצד גודל הבושה וההכנעה שמתבושש ונכנע מפני הצדיק עד שנעשה כאבן דומם ממש ולא יכול לדבר כו', כי זהו אמיתות הביטול כמ\"ש אדני שפתי תפתח כו', וכמו\"כ כשהולך על מקום מנוחת קדשו מתבטל שם ביתר שאת כו' כי גדולים צדיקים במיתתן יותר מבחייהן, ומצד תוקף אמונה הגדולה שמאמין בקדושת נשמתו הקדושה והטהורה שעלתה כבר למקומה למעלה מעלה בעילוי אחר עילוי והשראות (נ' שצ\"ל והשארות) הנפש הנשארת על הגוף בקבר כמ\"ש ונפשו עליו תאבל שהולכת עמו בקבר כמ\"ש בלק\"ת, וגם מקיפים של הנפש מתקשרים עם הנפש שלזה מצוה לעשות ציון על הקבר שהוא כסא למקיף כידוע ומבואר בלק\"ת, הנה בודאי כשיבוא אל מקום קדושת מנוחות הצדיק ומצייר לפניו דמות פניו הקדוש והטהור תפול עליו אימתה ופחד יותר מבחיים חיותו, כי אז הי' בגדר גוף גשמי ועתה הנפש של הצדיק היא ברוחניותה כמו שהיא, גם יכול הוא לבוא עי\"ז לבחי' ביטול במציאות ויר\"ע ממש, וענין יר\"ע היא הנזכר בסידור בהערה של תקון חצות שהיר\"ע היא יראה פנימית והיא יראת בושת כמו המתבייש מאדם גדול וצדיק מפני שפלות ערכו לגבי הצדיק הוא מתבטל ממציאותו לגמרי עד שכלא נחשב הוא, ועד\"ז הוא יר\"ע שמתבושש מגדולתו ית' שלגדולתו [ית'] אין חקר שאא\"ס למעלה עד אין קץ ולמטה עד אין תכלית, שזהו מ\"ש אם אין חכמה אין יראה"],[1900640045,"שהחכמה עילאה שהיא בחי' כח מה בחי' ביטול גורם ליר\"ע וכמ\"ש שם באריכות. והנה עד\"ז יובן ג\"כ בהליכתו ע\"ק הצדיק והקדוש יכול לבוא לידי בושה גדולה וביטול במציאות ממש שמתבושש מאוד בכל מעשיו ומחשבותיו אשר עשה וחשב עד היום כי גלוים המה, כי הצדיק אפי' בהיותו בחיים נודע לו מחשבות אדם ותחבולותיו כידוע וכש\"כ הנפש של הצדיק אחרי הסתלקותו כי רוחני' היא, והביטול והבושה היא ג\"כ מפני אוא\"ס [ממש] המחי' את נפש הצדיק הזה כי היא חלק אלוה ממעל ובטילה ממש לגבי אוא\"ס ב\"ה כמבואר במ\"א, ועי\"ז יכול לעורר ר\"ר על ניצוץ אלקי שבנפשו מצד שפלות ערכו והוא ענין תשו\"ע כמשנ\"ת כי ע\"י הביטול שמתבטל לפני ת\"ח הוא ממש הביטול לה' וכמאמר וכי אפשר לדבק בשכינה אלא כל הדבק בת\"ח כו' כמבואר בתניא (וכדאיתא בגמרא גבי מלכי ישראל), והיא תשו\"ע ביותר שאין ערוך לגבי התשובה הנ\"ל באות ג', ועוד כי ע\"י [תוקף] התקשרות האמונה בנפש הצדיק מפנימיות ונקודות לבבו, וע\"י כח המדמה ציורו ע\"ד הרוחניות וע\"י הביטול הגדול תוכל נפשו לידבק באיזה פרט מנפש הצדיק השוכן שם, והוא קרוב קצת לענין התדבקות רוחא ברוחא הנז' בצדיקים כמו שית' במדרגה הה', ועי\"ז אפשר שתפילתו שיתפלל שם תוכל לעלות למעלה בעליות נפש הצדיק ויכול תפילתו לעשות פרי למעלה ולמטה, וזהו אמונת הצדיקים אשר אנשים נוסעים על קבריהם אעפ\"י שאינם משיגים כלום כמשי\"ת.\n<b>(וזהו)</b> וענין המדריגה הה' הוא מדריגה גבוה מאוד שאין למעלה ממנה והוא ענין ההשתטחות על קברי הצדיקים המבואר בס\"ח שהוא גדולה כ\"כ בערך עד שהוא יכול להשיג שם השגות עי\"ז, והיינו שיכול להעלות שם נשמתו עד מקום [אחיזת] נשמת הצדיק באברי אדה\"ר [ר\"ל] בנשמה הכוללת ויעוררנו כדי להעלות נשמתיהן בסוד העלאת מ\"ן ואז יכול להוריד נשמתיהן לגופם ולדבר עמם והוא אתדבקות רוחא ברוחא ממש, ועי\"ז יכולים להשיג השגות גדולות ברזין דאורייתא וליחוד יחו\"ע, וכמו שנז' בספר עמהמ\"ל והיחודים שהי' האריז\"ל מוסר"],[1900640058,"לתלמידיו ליחד ע\"י הצדיקים הגדולים ולהשיג שם השגות עליונות, וזהו כל גודל מעלות האריז\"ל שהנשמות הגבוהות הי' מגלין לו רזי תורה, והמדריגה הזאת היא גבוה יותר מגילוי אליהו ורוה\"ק וכמ\"ש בשער הק' (להאריז\"ל) להרח\"ו ז\"ל, וכמבואר בס' עמה\"מ על הרח\"ו שנתלבש בו נשמת בניהו בן יהוידע עד שהאיר גם בפנימיות, והוא ע\"י היחוד הנ\"ל שחזר על קברו כמה וכמה פעמים והוא שייך לנשמתו כו' כמו\"ש שם, ובודאי יש בזה מדריגות רבות אך [הכל] לגדולי הערך אשר נפשם לא נפגמו כלל ונפשם ברורה וזכה ויש להם נר\"ן המאירים כו', [או] עכ\"פ [בחי'] רוח ונפש בלא פגם כלל, ומדריגה זו גבוה יותר מאוד ונעלה ממדריגה הד' הנ\"ל כי אין להם שום השגה כלל בגילוי, אבל במדריגה הזאת אפי' הפחותים יוכלו להשיג השגות וליחד יחודים לפ\"ע הנפש כנ\"ל וד\"ל, והוא ענין האתדבקות רוחא ברוחא ממש היינו ש[מחבר ו] מדבק רוחו ברוח של הצדיק ושניהם עולים בסוד העלאת מ\"ן, וכמ\"ש ג\"ס מ\"ח פ\"א ע\"ס היחודים משנה ג' וז\"ל ואם זכה הוא בנר\"ן יחברם כולם בנר\"ן של הצדיקים הללו כשעולי' כו' ע\"ש באריכות וד\"ל.\n<b>ויובן</b> כ\"ז בתוס' ביאור מענין המבואר באגרת הקדש (של אדמו\"ר נ\"ע) על מאמר הזה\"ק דצדיקיא דאתפטר מעלמא אשתכח בכולהו עלמין יתיר מבחיוהי כו', ותוכן דבריו הקדוש הוא על מארז\"ל דשביק חל\"ח כי הנה חיי הצדיקים הם חיים רוחניים אמונה ואהבה ויראה כו', ובהיות הצדיק חי ע\"פ האדמה היו ג' מדות הללו בתוך כלי שלהם ובתוך לבושם שהוא בחי' נפש הקשורה בגופו, וכל תלמידיו אינם מקבלים רק הארת מדות הללו וזיון המאיר חוץ לכלי זהו ע\"י דיבורו ומחשבותיו הקדושים ולאחר פטירתו לפי שמתפרדין בחי' הנפש נשארה בקבר ובחי' הרוח בג\"ע ש[ה] ם ג' מדות הללו חג\"ת שנק' רוח כי האמונה היא בבחי'"],[1900640070,"הדעת קו האמצעי כידוע שהוא בחי' ת\"ת כו', לפיכך יכול כ\"א מתלמידיו וכל הקרוב אליו לקבלו חלק מבחי' רוחו שבג\"ע הואיל ואינו גשמי ולא בתוך כלי (פי' לכך יכולה הארה זו להתפשט סביב כו' לפי שהוא בחי' רוחניות ואינה מלובשת בכלי גשמיות), משא\"כ בחי' הצדיקים שבחי' הרוח מלובשת בתוך נפשם והנפש קשורה בגופה אינם יכולים לקבל מהם התלמידים או כ\"א מישראל כ\"א ע\"י דיבוריו ומחשבותיו הקדושים כו', משא\"כ כשנפרדת הרוח מן הנפש אזי תוכל להאיר לכל א' מתלמידיו לפי ערכו. וראי' לכ\"ז הובא מיעקב אבינו ע\"ה שנכנס עמו ג\"ע כו' וכמ\"ש בספר עשרה מאמרות שאויר ג\"ע מתפשט סביב כל אחד ונרשמים באור זה כל מחשבותם ודיבורם הקדושים בתורה ועבודת ה', וזהו ראי' גמורה שבחי' רוחניות יכול להתפשט בכ\"מ ממש כו' ולכך נקל מאוד לתלמידיו לקבל חלקם מבחי' רוח רבם העצמיות ומאת בחי' אהבתו ויראתו ואמונתו אשר עבד בהם ולא זיום בלבד (שהיא רק בחי' רוח [שלו] חג\"ת כנ\"ל ולא נפש כו'), לפי שבחי' רוחו העצמיות מתעלה בעילוי אחר עילוי להיכלל בבחי' נשמה וג\"ע העליון שבעולמות עליונים, ונודע שכל דבר שבקדושה אינו נעקר לגמרי מכל וכל ממדריגה הראשונה גם לאחר שנתעלה למעלה למעלה, אלא מדריגתו הראשונה נשארה למטה במקומו, ובחי' זו הראשונה הנשארת למטה היא המתפשטת בהתלמידים לכ\"א כפי התקשרותו וקרבתו אליו באה\"ר כו' כמבואר שם, אבל לקבל כל הרוחנית אינו אלא ע\"י התעוררות גדולה באה\"ר והכנעה עצומה אז רוחא דרעותא דליבא אמשיך רוחא מלעילא כו' ע\"ש.\n<b>והנה</b> אעפ\"י שמבואר ומובן מכ\"ז שיכול כל אחד מן התלמידים לקבל חלקם ותורתם מבחי' רוח רבם בכל מקום שהוא ע\"י שאור ג\"ע מתפשט סביב כ\"א, וא\"כ א\"צ כלל ליסע אל מקום מנוחתו ולהשתטח שם על קברו. אך הנה כ\"ז הוא אם לא נפסק חבל התקשרות אה\"ר אל רבו כמו שהי' בעודו בחיים חיותו ומתנהג בעבודת ה' באה\"ר ובאמונה כפי אשר הורהו רבו, ע\"כ יוכלו לקבל חלקם מבחי' רוח רבם וכמ\"ש שם, אבל אם נפסק ח\"ו חבלי עבותות האהבה מצד טרדות הזמן בעניני עוה\"ז בענינים גשמיים, אשר כמעט נכבה אור תורתו ואוי\"ר אשר הופיע עליהם בעודו בחיים חיותו עד שבמשך זמן נוכל לכבות ולהיות נשכח ממנו לגמרי כידוע, שלזה הי' צריך [תמיד] גם בעודו בחיים חיותו לקבל פני הרב"],[1900640081,"תמיד ולשמוע מפיו דוקא דא\"ח, ואעפ\"י שדבריו המה בכתובים אעפ\"כ אינו דומה שמיעה מרחוק לראיית פניו דוקא, כי הארת פניו גדולה יותר מקבלת דברים ושניהם כא' טובים וגורמים אליו תוקף ועוז התקשרות האה\"ר בתשוקה נפלאה, שזהו שארז\"ל כל הדבוק בת\"ח כאילו דבוק בשכינה כי ע\"י דבוקו והתקשרותו יכול לקבל הארת [מבחי' רוחו אליו ע\"י דיבורו ומחשבותיו הקדושים באור תורתו ועבודתו ולקבל ולקלוט היטב במוחו ולבו] אור אהבתו ויראתו בבחי' קליטה ממש כענין דברים היוצאים מן הלב נכנסים אל הלב כו'.\n<b>וזהו</b> מארז\"ל חייב אדם להקביל פני רבו ברגל לפי שאז הוא מקבל תוס' אור מרוח רבו שמאיר אז ביתר שאת ויתר עז, שהיא הנותנת כח ועוז אחרי התפרדותו מעמו להיות מתחזק בעבודת ה' באוי\"ר כפי אשר קיבל מרבו והכל מכח הארת פניו דוקא. וראי' לזה הוא כאשר מתרחק זמן רב מרבו אפי' בעודו בחיים אזי נפסק חבל התקשרות האה\"ר ונופל ממדריגתו באה\"ר בעבודת ה', וכאשר יקרה מקרה זה בכמה אנשים כידוע, וזהו אמיתית טעם הנוסעים תמיד לשמוע דא\"ח מפי רבם דוקא אעפ\"י שכבר שמעו וראו בכתובים ויש אתם כו', אעפי\"כ נוסעים תמיד לקבל פני הרב בתוס' אור פנים מאירות פנים מסבירות לגלות להם אור תורת אמת כו', כי עי\"ז מאיר נפשם בעבודת ה' באהוי\"ר כו' כי עי\"כ התקשרות האה\"ר נקשרה נפשו בנפש של הצדיק כמ\"ש ונפשו קשורה בנפשו, ואעפ\"י שאין לו ערך לגבי נפש הרב מ\"מ איזה ערך ושייכות יש לו עכ\"פ כיון שמקושר אליו ומאמין בו [בודאי יש לו איזה שייכות] ועי\"ז יכול לקבל חלקו מרוח רבו כנ\"ל וד\"ל.\n<b>והנה</b> מובן מכל זה עכ\"פ אשר מכ\"ש וק\"ו כאשר שחל\"ח אעפ\"י שחיים שלו שהם אמונה ואהבה ויראה נמצאים בכל העולמות ויכולים התלמידים לקבל חלקם כו', אך מ\"מ במשך זמן רב וטרדת הפנאי בלחץ ודוחק הפרנסה יכול לכבות אור תורתו ועבודתו לגמרי מן התלמידים, לכן מן ההכרח הוא לנסוע אל מקום מנוחתו על קברו ולהשתטח שם על קברו ולעורר את האהבה מקרב איש ולב עמוק, כי בוודאי עדיין לא נפסק [לגמרי] מכל וכל רק נשאר איזה רשימו"],[1900640092,"שהוא בחי' רוחא דשביק בגווה (שאין האשה כורתת כו' אלא למי שעשאה כו', לכן אף שנפרדה ממנו רוחו מקשקש תמיד בגווי ואינה יכולה לקבל כו', וזהו שהפליגו בזוה\"ק שלא לישא אלמנה ע\"ש כידוע), והוא ענין הרצון שיש לאדם ליסע אל מקום מנוחת הצדיק כדי לעורר את האהבה כי אם הי' נפסק ח\"ו לגמרי לא הי' לו גם רצון לזה כלל, וככה רוח זה דשביק בגווי יכול הוא לעורר [את] רוח רבו מחדש בעוז אה\"ר והכנעה עצומה ויגיעה גדולה לקבל ג' מדות הללו שהם אמונה ואה' ויראה כנ\"ל כמו שהורהו רבו כנ\"ל.\n<b>אמנם</b> מה שצריך ליסע דווקא אל מקום מנוחות קדשו לעורר שם את האהבה יש בזה ב' טעמים, הא' הוא ע\"ד הפשוט כי ע\"י הנסיעה בתשוקה נפלאה יהי' מזה העלאת מ\"ן גדולה, ואח\"כ בבואו לשם עם כח האמונה גדולה בוודאי יתבטל ממציאותו לגמרי יכוון עצמו לקראת אלקים בהכנעה רבה במס\"נ ממש וישפוך שיחו לפני ה' מעומקא דליבא על שנתרחק לגמרי כו', ועי\"ז יערה ה' עליו רוח ממרום והוא רוח רבו שיש לו חלק בו להחיות נפשו באור תורה ועבודה של רבו כו', והב' הוא ע\"ד מ\"ש בלק\"ת של האריז\"ל בסוד קבורת המת ודיני האבילות, ותוכן דבריו בקיצור הוא כי האדם יש לו נשמת פנימיות ומקיפים כו' דוגמת הצלם דז\"א כי צ' הוא בחי' פנימית ולמ\"ד מ\"ם [הם ב' מקיפים ל'] הוא ג' מקיפים ומ\"ם הוא בחי' ד' מקיפים הרי ז' מקיפים, והאדם בהיותו בחיים חיותו יש בו כל המקיפים הנ\"ל. אמנם למ\"ד יום קודם שמת האדם מסתלקים ממנו בחי' המקיפים שהם צלם על ראשו וזהו שכתוב בזוהר עד שיפוח היום ונסו הצללים כו' (שהם צללים הנ\"ל), ואמנם בשעת פטירתו של אדם הם חוזרים אליו כולם יחד בכדי שיסבלו כולם צער מיתה מהעונשים וז\"ש תוסף רוחם יגוועון, אמנם בשעת פטירתו של האדם הנשמה והרוח הולכים עם המקיפים שלהם אל מקום הרא[וי] להם כו', והנפש עם ז' מקיפים שלה שהוא הצל דצל\"ם (כנודע שיש צלם [מ] נרנח\"י). ואמנם צלם של הנפש נחלק לפנימיות וחיצוניות הפנימיות הוא הצל דצל\"ם והוא ההולך עם הגוף על הקבר כמ\"ש ונפשו עליו תאבל, אך הז' מקיפים"],[1900640103,"[של הנפש] שהם למ\"ד מ\"ם דצלם הרי אלו נשארים בבית האבל כי אינם יכולים להפרד כ\"כ בנקל משום שנפרד ונפטר בו, וזהו שארז\"ל כל ז' ימי האבילות באה נפשו של המת אל ביתו, והוא סוד של המקיפים של הנפש, אמנם הם הולכים ובאים כי הם רוצים להיות בבית שמת שם המת ונפטר בו וגם רוצים להשתתף עם נפש הפנימית שבו ולכן הולכים עה\"ק וחוזרים לבית, אמנם בכל יום מז' ימי האבילות מסתלקת מגוף א' מן המקיפים ונשאר דבוק עם הנפש וכך הם עושים עד כלות ז' ימי האבילות ואז נשלמו כלם מלהסתלק ומתקשרים עם הנפש בקבר, ולכן תקנו ז' ימי האבילות בעוד שעדיין נפש של המת בבית האבל, ואמנם כאשר הי' המקיפים עדיין בבית האבל אזי הקליפות הם נאחזות מאד בנפש המת כי בבחי' מקיף אין להם שום אחיזה, ובכ\"י מסתלק כח הקליפה עד כלות ז' ימים ואז אינו נשאר שם רק מה שהוא בחי' הכרחיות לשאר שם בעוד שהבשר קיים כו' ע\"ש. ואמנם מה שמתחיל מחלק המקיף לילך בקבר הוא מלמ\"ד דצלם יום א' דעת יום ב' בינה יום ג' חכמה ואז הוא עיקר דין המת בקבר כנודע, ומשם ואילך שהולך בחי' המ\"ם דצלם מתמעטין הדינים, ולכן נוהגין האשכנזים שלא לעשות ציון על הקבר רק אחר ז' ימי האבילות, כי ענין בנין הציון הוא לתת כח אל המקיף לעמוד שם ואם יבנה הציון קודם שיבא לשם נמצא שאז נותנים כח אל הטומאה הנאחזת במת שישאר שם ולא תלך, דוגמת הבונה בית ואינו מזכיר שם שמו ית' ששורה שם רוה\"ט כו', אך אחר ז' ימים שאז בא המקיף אז מצוה לעשות ציון ולהכין כסא למקיף כו' עכ\"ל הלק\"ת הנ\"ל.\n<b>והנה</b> מובן מכל הנ\"ל כי במקום מנוחת הצדיק שם שוכן פנימיות נפשו שהוא בחי' צ' דצלם, ובבנין הציון על קברו שוכן בתוכה בחי' מקיפים שהם למ\"ד דצלם כמבואר שם באריכות, ובוודאי המקום ההוא קדוש יאמר לו ושם יכול"],[1900640114,"לעורר גם את נפש הצדיק ע\"י כח התעוררות שלו באהבה ויראה ובתעצמות עוז התקשרות בוודאי יכול לעורר את נפש הצדיק הקדוש, וקרוב הדבר שיוכל להדביק את נפשו אל נפש הצדיק ולהתעורר באיזה התעוררות רק אם ישים אליו לבו באמת ובלבב שלם וישוב [בתחלה] בתשובה שלימה לפני השי\"ת ויחפוץ וירצה באמת להמשיך עליו רוח קדושה מרוח רבו כנ\"ל. וע\"י תוקף האמונה והתקשרות בנפש הצדיק עם כח המדמה ציורו ע\"ד הרוחניות שיש בכאן פנימיות נפשו והשראתו בפנימיות ומקיפים שנקרא צלם כנ\"ל יוכל לבוא עי\"ז אל בחי' מעין ודוגמא קצת אל בחי' התדבקות רוחא ברוחא כנ\"ל, ועי\"ז ימשיך על עצמו חלקו מרוח רבו להיות חי מחדש מן אור תורתו ועבודתו כאשר הי' באמנה אתו בהיות בחיים חיותו ע\"י הארת פניו ממש ואדרבה יותר מזה, כי אז הי' ע\"י הלבושים דמחשבה ודיבור כנ\"ל וכעת הוא מקבל מרוח רבו העצמית לבד כנ\"ל, וגם תפילתו שיתפלל שם בוודאי היא קרובה להתקבל וכמבואר לעיל בשם ספר עשרה מאמרות שאויר ג\"ע מתפשט סביב כ\"א מן הצדיקים ושם נרשמים כל מחשבותיו ודיבוריו הטובים כו', אך אין כ\"ז שייך רק בצדיקים שהולכים עם אורה בג\"ע כו' כיעקב כו', אבל באנשים פשוטים הרי יש אוירא דגהנם שמתפשט סביב כ\"א וכמבואר שם.\n<b>אמנם</b> בעת בואו לכאן על מקום מנוחות הצדיק ומתפלל שם על קברו שבודאי התפילה שלו היא שם בכוונה רצוי' ושלימה מקרב איש כו', וכאשר מכניס את ראשו על הציון אשר שם שוכנים המקיפים של הנפש הצדיק אזי בוודאי כל אות ואות מדיבורו ומחשבותיו דשם נכללים באוירא דג\"ע דשם (כי הרוח נקרא אוירא דג\"ע וכמ\"כ הנפש). ובעת אשר נפש הצדיק עולה למעלה תוכל גם תפילתו לעלות למעלה מעלה בג\"ע העליון ויוכל לעשות פרי למעלה ולמטה, כידוע שכל התפילות צריכות לעלות למעלה דרך פתח של ג\"ע הארץ, וע\"כ התפילה שמתפללי' אצל מערת המכפלה היא רצויה ומקובלת מאוד לפי שיש קבלה בידינו ששם הי' פתחו של ג\"ע ממש. משא\"כ התפלה שאנו מתפללים בכאן מתערבות באוירא מסאבא של ארץ העמים, ויכול להיות אשר התפילות דכאן מכמה שנים אינה עולה כלל כמ\"ש בשם הבעש\"ט. ודוגמא מערת המכפלה הוא כאן ע\"ק הצדיק התפיל' שאנו מתפללים שם תוכל היא לעלות מהרה למעלה בעת"],[1900640125,"עליות נפש הצדיק למעלה כי אותיות של התפילה הם נרשמים שם בנפש הצדיק. וגם אם יזכה ימליץ טוב עליו ויכול לפעול בקשתו שתומשך למטה בגשמיות כו' וד\"ל.\n<b>ודבר</b> זה שהתפילה מתקבל שם, הוא יסוד מובן לכל דורש ומבקש ה' שיכולים ליסע לשם ולהתפלל שם בכוונה גדולה מעומקא דליבא, ויהי' נכון לבו בטוח שבוודאי יקובל שם תפילתו מהר כנ\"ל, כי המקום הקדו' הזה גורם לב' דברים, הא' שיכוון שם את לבו בתפילתו מצד כח האמונה החזקה שתפיל עליו אימתה ופחד כנ\"ל, והב' שיהי' מובטח שיקובל שם תפילתו, וזהו אפי' לכל בר ישראל אף שאינו תלמידו שזהו רק מחמת טעמים הנ\"ל, וכש\"כ לתלמידיו המקושרים אל אור תורתו כנ\"ל. אמנם אף אותם שלא ידעו בו ולא הכירו בו בעודו בחיים חיותו רק שלמד בספרים הקדושים שהניח ברכה אחריו, ונהנים מאור זיו תורתו ומתחזקים עי\"ז בעבודת ה' כאשר יורהו הספרים בעבודת ה' לילך בדרכי ה' כו' בוודאי גם המה נק' תלמידיו כי יש להם שייכות אליו ג\"כ. כי המה מאמינים בהצדיק ההוא ומקבלים ממנו אור תורתו כי מי שאין לו שייכות אליו אינו מאמין בו כלל וכלל (וזהו שמבואר במ\"א שיש לכל צדיק בדורו כמה וכמה אנשים שאינם מאמינים בו [כלל] ואינם רוצים לקבל ממנו כלל וכלל, ואדרבה להיפוך כו' היינו לפי שאין לו חלק בו כלל). כי ענין אמונה הוא מלש' ויהי אומן כו' שנמשך לשרשו, ולכן נק' בנ\"י מאמינים כו' כי המה חלק אלוה ממעל ממש לכן נמשכו לשרשן. וכמו\"כ הוא אמונת הצדיקים לפי שהם שרשים, והענפים נמשכים לשרשן כמבואר במ\"א. ובוודאי אותם הלומדים בספרים הקדושים ומתנהגים בדרכי ה' עפ\"י אשר הורהו ומשתעשע ונהנה מאוד מאור תורתו הם כולם נקר' תלמידיו ממש ויכול לדבק אליו את נפשו בהתקשרות עצומה כמו בעודו בחיים ממש.\n<b>ויש</b> להביא ראי' לזה ממעשה הנזכר בגמרא בהאי בר בי רב דחזי לגוהרקי דר\"ח [רבה] ומקליי' לעינ' בנורא כו' ולמחר הלך ונשתטח על קברו ואמר מתניתא דמר קא מתנינא ונתרפא, הרי מחמת שלמד מתניתא שלו דווקא יש לו זכות שיה' יכול להסתכל בו ולכך נתרפא כו' וד\"ל. כי הענין מה דחזי לגוהרקי דר\"ח"],[1900640136,"רבו בעליתו למתיבתא דרקיע זהו בוודאי ראי' רוחני' ולא ראי' חושית שזהו ע\"י דביקות הנפש ממש והפשטת הגשמיות כו' וד\"ל.\n<b>והנה</b> זה שמבואר באג[ה] \"ק הנ\"ל עוד [שיש עוד] בחי' הארה לתלמידי' רק שאינה מתלבשת [ב] תוך מוחין כראשונה רק מאירה עליהם מלמעלה והוא מעליות רוחו ונשמתו אל מקור חוצבה דהיינו לחקל תפוחין קדישין, ועי\"ז נעשה העלאות מ\"ן מכל מעשיו ודיבוריו ומחשבותיו ותורתו ועבודתו אשר עבד כל ימי חייו ונזרעו בחקל תפוחין קדישין אורות עליונים (פי' תורה ועבודה הם האורות העליונים כי שכר מצוה מצוה כו'. והאורות העליוני' [אלו] מאירים על כל תלמידיו שנעשו עובדי ה' ע\"י תורתו ועבודתו והארה זו מכנסת בלבבם הרהורי תשו' ומע\"ט ונק' גדולי גדולים כו'), והאר' זו [היא] בהעל' כו' כמו שמש המאיר לכוכבים מתחת לארץ וכדאיתא בתיקוני' על משרע\"ה שאחר פטירתו נתפשטה הארתו בכל דרא ודרא כו' עכ\"ל האגה\"ק ע\"ש, הנה הארה זו מתפשטת בוודאי על כל התלמידים בשוה, אף לאותם שלא הכירו בו רק שלמדו בספרים הקדושים ונהנין מאור קדושת תורתו ועבודתו, ועוד שגם המה עבדו את ה' ע\"פ התנהגותיו. וכמו\"א שם הלשון על כל תלמידיו שנעשו עובדי ה' ע\"י תורתו ועבודתו, וראי' לזה הוא ממרע\"ה שמתפשטת תורתו (הארתו) בכל דרא ודרא לכל ס\"ר נש\"י כמבוא' כו' והיינו כשלומדים תורת משה דווקא כו' וד\"ל. וזהו מתניתא דמר קא מתנינא, וצריך להיו' ההארתו מאירה עליו ע\"כ יש לו זכות להסתכל בו כו' וד\"ל. וכל זה הוא מדריגה הד', אמנם מדריגה הה' הנ\"ל שהוא אמיתות ההשתטחות ע\"ק הצדיקים ליחוד יחודים עליונים ולהשיג שם השגות גדולת כמ\"ש עולמך תרא' בחייך ממש שנוטל חלק בג\"ע בחיים ממש, שכאשר מעלה את נר\"ן שלו למעלה לחברם בנר\"ן של הצדיק היושב בג\"ע ונהנה מזיו השכינה בהשגות אלקות ממש"],[1900640146,"שעז\"נ הי[ו] שבת בגנים חבירים מקשיבים לקולך כו', דקאי על המלאכים המקשיבים לקולם של הנשמות היושבים בג\"ע, כמו\"כ גם אותם הצדיקים המגלים רזי תורה בהיותו בחיים חיותו בגוף גשמי אזי באים ג\"כ המלאכים לשמוע ד\"ת מפיו, וכנזכר בגמרא שבאו מלאכי השרת במזמוטי חתן וכלה וכמ\"ש בזוה\"ק וכולהו צייתין לקוליהן ולמילוהן כו' וד\"ל. וזהו התגלות של בחי' יחידה שבנפשו שהוא התגלות עצם אור נשמתו כמו שהוא למעלה דבוקה באלקים חיים שעי\"ז זוכה ממילא לגילוי אליהו ורוה\"ק כמ\"ש בכתבי האריז\"ל כו' וד\"ל."],[1900640311,"<b></b><b>בעז\"ה לכללות אנ\"ש דמדינתנו מאדמו\"ר דובער זצוק\"ל נבג\"מ זיע\"א\n[אגרת מאדמו\"ר לכללות אנ\"ש דמדינתינו שנת תקע\"ד לפ\"ק]</b>\n<b>בהיות</b> מבואר במכתבי הראשון, מאשר רבים מאנ\"ש ישנים גם חדשים נבוכים ומוטעים בכמה מיני טעות בדרכי קבלת דא\"ח באור תורה ועבודה שבמדות ולב מן הקצה אל הקצה ממש, לומר לאור חושך ולחושך אור מצד מיעוט הידיעה ומצד מיעוט העסק והרגילות. ו[ה] עיקר מצד הסתעפות הקלקולים שיצא[ו] מרבוי הדרשנים המתחכמים להתהלל ואומרים רזי לי כו' כי יש סודות באמיתת העבודה, ומטעים א\"ע ולזולתם עד שנפל טעות גמור מן הקצה כו'. אשר צר לי מאד מאד מזה בהיות שתולין הכל בי ושואלין ממני כמה מאנ\"ש דברים בזה שא\"א לסבול ולהכיל דבריהם המוטעים שנקבע כמו הלכה פסוקה. וזהו מסיבת התלמידים שלא שמשו כל צרכן שנסתעפו לשתות מים הרעים הממיתים ומאבדים את הנפש ומוציאים אותו מאור לחושך [גמור] כו'. ע\"כ אמרתי שמצוה וחובה עלי דוקא לפרש ולבאר היטב בכל פרטי ופרטי ענינים החלוקים בכל דרכי העבודה במוח ולב כל דבר על מקומו ומדריגתו ואופניו בפרטי פרטיות, למען לא יטעה הטועה בדרך ולא יטעה לזולתו, וגם למען הקים בנין קבוע בנפשו באור תורה שמקבל שיהיה הכל נטוע ומושרש בשרש וקשר קיים בל ימוט לעולם כו'. וה\"ז דומה לקערה מלאה כל מעדני מאכלים טובים המשיבים את הנפש ואין לו כף במה ליקח אל פיו, שתצא נפשו בתשוקתו רק מצד העדר כלי הקבלה בלבד כו' כך כל תורת אמת בהתבוננות וידיעות אלקות שהנחילנו כבוד אאמו\"ר ז\"ל נ\"ע בכ\"ח לפושי\"ד, הגם ששגור הכל בפיו, אך מצד העדר ידיעת אופן הקבלה בנפשו, הנה רעבים גם צמאים אבל בלי אור וחיות בנפשו כלל, עד שישאל השואל אחר שגמר וסבר, איזה תועלת בנפשו יבוא מזה. וכן יש להיפוך שהשמיעה מרחוק לגמור ולסבור זהו אצלו עיקר החסידות, והקבלה בנפשו בהתפעלות אם במוח ומכ\"ש בלב [זה] איסור גמור אצלו, עד ששואל ומבקש עצה איך לפטור מהתפעלות שנעשית פתאום בלי בחירה כלל כי זהו נקר' הרגשת עצמותו (ער הערט זיך), שזהו אצלו מן העונות החמורים המאבדים את הנפש כו' כדרכי הישנים כו'."],[1900640320,"<b>עתה</b> ראו נא ב' הפכים כאלו מן הקצה אל הקצה, וביניהם נמצא כמה מיני ממוצעים בחילוק מדריגות ומינים שונים, אשר נמצאו גם בהם רבוי הטעות מאור לחושך ממש, גם בין הישנים הבקיאים ורגילים [מ] כמה מדריגות שונות וחכמים בעיניהם לתכלית דה\"ח והמה מוטעים בתכלית. ולזאת ההכרח מאד לפרש ולבאר הכל למען לא יתלו בי בוקי סרוקי כו'. והעיקר להעמיד ולקיים עיקר תוכן וכוונת רצון הק' של אאמו\"ר ז\"ל נ\"ע באור תורתו [אשר] הופיע עלינו זה שלשים שנה, וזהו כל מגמתי מנעוריי לכל אהוביי ומבקשי דא\"ח באמת, שיוקבע בנפשם אור חיי עולם לתכלית המכוון, שהוא ענין גלוי אלקות בנפשם בכ\"ח לפושי\"ד וכידוע:\n<b>והנה</b> פתח דברי יאיר בחלוקי [ה] כללי' שבין ד\"ח הישנים ובין ד\"ח אשר הנחילנו והאיר לנו אאמו\"ר ז\"ל נ\"ע באור תורתו, מה שכל עיקר"],[1900640328,"מגמתו היה מתחילת עבודתו בקודש, אשר לא פעם ושתים שמעתי מפי רוח קדשו ז\"ל שכל עיקר מגמתו ויגיעתו במס\"נ ממש על אנ\"ש רק שיוקבע בנפשם גלוי אלקות, דהיינו שיהיה התפעלות נפשם רק התפעלות אלקות דוקא ולא התפעלו' חיי בשר שאינו התפעלות אלקות כלל. וזה עיקר וקיצור תוכן המכוון, שהוא ההפרש בין עובדי ה' בנשמתם לעובדי ה' בגופם. ובזה הכלל נמצאו פרטים רבים ושונים מאד. ומתחלה צריך לבאר היטיב שרש הכלל הזה הגם שידוע לכל אבל אינם מבינים לתכליתו. והענין יובן בהקדים הידוע ע\"פ ואתם הדבקים בה' כו' חיים כולכם כו' דמשמע שבלתי [ה] דביקו' אינם נק' חיים אלא מתים, וכתיב לאהבה את ה' כי הוא חייך, וא\"א לפרש דכי הוא חייך קאי על לאהבה [את ה'] כו' דהאהבה הזאת היא חייך, דא\"כ הל\"ל כי היא חייך ולמה אמר הוא [חייך] , ובודאי פשט המקרא הזה מובן לכל דכי הוא חייך נתינת טעם הוא, למה תאהוב לפי שהוא חייך, וא\"כ י\"ל מה צורך"],[1900640336,"להתפעלות האהבה אחר שכבר הוא חייך ממש. אך הנה ידוע שיש הפרש בין ענין האהבה ובין ענין הדביקות, וכלל ההפרש הוא רק בדבר הזה בלבד, שהדביקות הוא חיות והתקשרות הנפש בחיי החיים עצמות אא\"ס ב\"ה שנק' מקור חיי כל הנשמות, וז\"ש כי הוא חייך ממש כידוע, וע\"כ בענין הדביקות אמר ואתם הדבקים פי' אתם מצד שרש נשמתכם הדבקים ממילא בהתקשרות עצמיית ותמידיית ולא בחינת התפעלות לפרקים, כמ\"ש רשב\"י בחד קטירא אתקטרנא בי' אחידא כו' (וכמשי\"ת בסמוך במדריגה הה' דנה\"א בבחי' יחידה כו'), וזה יש בכל נפש מישראל גם מי ששרשו בבחי' נפש דעשיה בלבד"]]});
